map backfillCashPaymentMadeDetailsBatch()
{
                 	result = Map();
                 	// =====================================================
                 	// CHANGE THIS FOR EACH BATCH
                 	// Examples:
                 	// 0, 500, 1000, 1500...
                 	// =====================================================
                 	start_from = 0;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded = 0;
                 	updated = 0;
                 	skipped = 0;
                 	failed = 0;
                 	failed_details = List();
                 	for each  rec in Payment_Made_Details[Amount_Paid > 0] sort by ID asc range from start_from to end_at
                 	{
                 		loaded = loaded + 1;
                 		amount_to_post = round(ifnull(rec.Amount_Paid,0.0),2);
                 		if(amount_to_post <= 0 || rec.Payment_Made_Voucher == null)
                 		{
                 			skipped = skipped + 1;
                 			continue;
                 		}
                 		// -----------------------------------------------
                 		// Load Payment Made Voucher header
                 		// -----------------------------------------------
                 		pmv = Payment_Made_Voucher[ID == rec.Payment_Made_Voucher];
                 		if(pmv.ID == null)
                 		{
                 			skipped = skipped + 1;
                 			continue;
                 		}
                 		voucher_number = ifnull(pmv.Payment_Made_Number,"").toString().trim();
                 		if(voucher_number == "")
                 		{
                 			skipped = skipped + 1;
                 			continue;
                 		}
                 		transaction_date = zoho.currentdate;
                 		if(pmv.Payment_Made_Date != null)
                 		{
                 			transaction_date = pmv.Payment_Made_Date;
                 		}
                 		// -----------------------------------------------
                 		// Build Grapes Group posting payload
                 		// -----------------------------------------------
                 		post = Map();
                 		post.put("Display_Name_Application","Masaka Site Management");
                 		post.put("Source_Form","Payment Made Details");
                 		post.put("Source_Record_ID",rec.ID.toString());
                 		post.put("Voucher_Number",voucher_number);
                 		// Lookup to Masaka Payment Made Details
                 		post.put("MSM_Payment_Made_Details",rec.ID);
                 		post.put("Transaction_Date",transaction_date);
                 		post.put("Business_Division",null);
                 		post.put("Display_Name_Business_Division","");
                 		// Receivable side
                 		post.put("Amount_To_Receive",0.0);
                 		post.put("Amount_Received",0.0);
                 		post.put("Amount_Not_Received",0.0);
                 		// Payable side
                 		post.put("Amount_To_Pay",0.0);
                 		post.put("Amount_Paid",amount_to_post);
                 		post.put("Amount_Not_Paid",amount_to_post * -1);
                 		resp = grapes_group.masakasite.postBusinessDivisionDetail(post);
                 		if(resp != null && ifnull(resp.get("ok"),false) == true)
                 		{
                 			updated = updated + 1;
                 		}
                 		else
                 		{
                 			failed = failed + 1;
                 			m = Map();
                 			m.put("Detail_ID",rec.ID);
                 			m.put("Voucher",voucher_number);
                 			m.put("Amount_Paid",amount_to_post);
                 			m.put("Response",resp);
                 			failed_details.add(m);
                 		}
                 	}
                 	result.put("start_from",start_from);
                 	result.put("end_at",end_at);
                 	result.put("batch_size",batch_size);
                 	result.put("loaded",loaded);
                 	result.put("updated",updated);
                 	result.put("skipped",skipped);
                 	result.put("failed",failed);
                 	result.put("failed_details",failed_details);
                 	if(loaded < batch_size)
                 	{
                 		result.put("last_batch",true);
                 	}
                 	else
                 	{
                 		result.put("last_batch",false);
                 	}
                 	info result;
                 	return result;
                 }

map backfillCashPaymentReceiptDetailsBatch()
{
                 	result = Map();
                 	// =====================================================
                 	// CHANGE THIS FOR EACH BATCH
                 	// =====================================================
                 	start_from = 10500;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded = 0;
                 	updated = 0;
                 	skipped = 0;
                 	failed = 0;
                 	failed_details = List();
                 	for each  rec in Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Sales_Voucher != null && Payment_Type == "Cash"] sort by ID asc range from start_from to end_at
                 	{
                 		loaded = loaded + 1;
                 		amount_to_post = round(ifnull(rec.Amount_Allocated,0.0),2);
                 		if(amount_to_post <= 0 || rec.Payment_Receipt_Voucher == null)
                 		{
                 			skipped = skipped + 1;
                 			continue;
                 		}
                 		post = Map();
                 		post.put("Display_Name_Application","Masaka Site Management");
                 		post.put("Source_Form","Payment Receipt Details");
                 		post.put("Source_Record_ID",rec.ID.toString());
                 		post.put("Voucher_Number",ifnull(rec.Display_Name_Voucher,""));
                 		// Lookup field
                 		post.put("MSM_Payment_Receipt_Details",rec.ID);
                 		post.put("Transaction_Date",rec.Payment_Receipt_Voucher.Payment_Receipt_Date);
                 		post.put("Business_Division",null);
                 		post.put("Display_Name_Business_Division","");
                 		// Receivable
                 		post.put("Amount_To_Receive",0.0);
                 		post.put("Amount_Received",amount_to_post);
                 		post.put("Amount_Not_Received",amount_to_post * -1);
                 		// Payable
                 		post.put("Amount_To_Pay",0.0);
                 		post.put("Amount_Paid",0.0);
                 		post.put("Amount_Not_Paid",0.0);
                 		resp = grapes_group.masakasite.postBusinessDivisionDetail(post);
                 		if(resp != null && ifnull(resp.get("ok"),false) == true)
                 		{
                 			updated = updated + 1;
                 		}
                 		else
                 		{
                 			failed = failed + 1;
                 			m = Map();
                 			m.put("Detail_ID",rec.ID);
                 			m.put("Voucher",ifnull(rec.Display_Name_Voucher,""));
                 			m.put("Amount_Allocated",amount_to_post);
                 			m.put("Response",resp);
                 			failed_details.add(m);
                 		}
                 	}
                 	result.put("start_from",start_from);
                 	result.put("end_at",end_at);
                 	result.put("batch_size",batch_size);
                 	result.put("loaded",loaded);
                 	result.put("updated",updated);
                 	result.put("skipped",skipped);
                 	result.put("failed",failed);
                 	result.put("failed_details",failed_details);
                 	result.put("last_batch",loaded < batch_size);
                 	info result;
                 	return result;
                 }

map backfillCashPaymentReceiptVoucherLookup()
{
                 	result = Map();
                 	start_from = 5000;
                 	batch_size = 1000;
                 	end_at = start_from + batch_size - 1;
                 	loaded = 0;
                 	updated = 0;
                 	already_filled = 0;
                 	not_found = 0;
                 	blank = 0;
                 	not_found_details = List();
                 	for each  rec in Payment_Receipt_Details[ID != 0] range from start_from to end_at
                 	{
                 		loaded = loaded + 1;
                 		if(ifnull(rec.Payment_Type,"") != "Cash")
                 		{
                 			continue;
                 		}
                 		if(rec.Payment_Receipt_Voucher != null)
                 		{
                 			already_filled = already_filled + 1;
                 			continue;
                 		}
                 		voucher_no = ifnull(rec.Display_Name_Voucher,"").trim();
                 		if(voucher_no == "")
                 		{
                 			blank = blank + 1;
                 			continue;
                 		}
                 		voucher = Payment_Receipt_Voucher[Payment_Receipt_Number == voucher_no];
                 		if(voucher.ID != null)
                 		{
                 			rec.Payment_Receipt_Voucher=voucher;
                 			updated = updated + 1;
                 		}
                 		else
                 		{
                 			not_found = not_found + 1;
                 			m = Map();
                 			m.put("Detail_ID",rec.ID);
                 			m.put("Voucher",voucher_no);
                 			not_found_details.add(m);
                 		}
                 	}
                 	result.put("loaded",loaded);
                 	result.put("updated",updated);
                 	result.put("already_filled",already_filled);
                 	result.put("blank",blank);
                 	result.put("not_found",not_found);
                 	result.put("not_found_details",not_found_details);
                 	info result;
                 	return result;
                 }

map backfillCashReceiptAllocations()
{
                 	result = Map();
                 	// Keep this at zero because processed vouchers leave the Unpaid filter
                 	start_from = 0;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded_count = 0;
                 	processed_count = 0;
                 	allocated_count = 0;
                 	no_receipt_balance_count = 0;
                 	no_sales_balance_count = 0;
                 	missing_link_count = 0;
                 	failed_count = 0;
                 	failure_details = List();
                 	// =====================================================
                 	// LOOP ONLY THROUGH CASH ROWS LINKED TO UNPAID
                 	// SALES VOUCHERS
                 	// =====================================================
                 	for each  rec in Payment_Receipt_Details[Payment_Type == "Cash" && Payment_Receipt_Voucher != null && Sales_Voucher != null && Sales_Voucher.Payment_Status == "Unpaid"] range from start_from to end_at
                 	{
                 		loaded_count = loaded_count + 1;
                 		try 
                 		{
                 			receipt_id = rec.Payment_Receipt_Voucher.ID;
                 			sales_id = rec.Sales_Voucher.ID;
                 			receipt_rec = Payment_Receipt_Voucher[ID == receipt_id];
                 			sales_rec = Sales_Voucher[ID == sales_id];
                 			if(receipt_rec.ID == null || sales_rec.ID == null)
                 			{
                 				missing_link_count = missing_link_count + 1;
                 				continue;
                 			}
                 			// Extra safety check
                 			if(ifnull(sales_rec.Payment_Status,"").trim() != "Unpaid")
                 			{
                 				continue;
                 			}
                 			// =====================================================
                 			// 1. FIND RECEIPT MONEY AVAILABLE FOR THIS DETAIL
                 			// =====================================================
                 			other_receipt_allocated = 0.0;
                 			for each  other_det in Payment_Receipt_Details[Payment_Receipt_Voucher == receipt_id]
                 			{
                 				if(other_det.ID != rec.ID)
                 				{
                 					other_receipt_allocated = other_receipt_allocated + ifnull(other_det.Amount_Allocated,0.0);
                 				}
                 			}
                 			total_received = ifnull(receipt_rec.Total_Amount_Received,0.0);
                 			receipt_available = total_received - other_receipt_allocated;
                 			if(receipt_available < 0)
                 			{
                 				receipt_available = 0.0;
                 			}
                 			if(receipt_available <= 0)
                 			{
                 				no_receipt_balance_count = no_receipt_balance_count + 1;
                 				continue;
                 			}
                 			// =====================================================
                 			// 2. FIND SALES VOUCHER BALANCE BEFORE THIS DETAIL
                 			// =====================================================
                 			other_cash_allocated = 0.0;
                 			other_credit_allocated = 0.0;
                 			for each  sales_det in Payment_Receipt_Details[Sales_Voucher == sales_id && Payment_Document == "Sales Voucher"]
                 			{
                 				if(sales_det.ID != rec.ID)
                 				{
                 					payment_type = ifnull(sales_det.Payment_Type,"").trim();
                 					if(payment_type == "Cash")
                 					{
                 						other_cash_allocated = other_cash_allocated + ifnull(sales_det.Amount_Allocated,0.0);
                 					}
                 					else if(payment_type == "Credit")
                 					{
                 						other_credit_allocated = other_credit_allocated + ifnull(sales_det.Amount_Credited,0.0);
                 					}
                 				}
                 			}
                 			grand_total = ifnull(sales_rec.Grand_Total,0.0);
                 			sales_available = grand_total - other_cash_allocated - other_credit_allocated;
                 			if(sales_available < 0)
                 			{
                 				sales_available = 0.0;
                 			}
                 			if(sales_available <= 0)
                 			{
                 				no_sales_balance_count = no_sales_balance_count + 1;
                 				continue;
                 			}
                 			// =====================================================
                 			// 3. ALLOCATE AVAILABLE RECEIPT MONEY
                 			// =====================================================
                 			amount_to_allocate = receipt_available;
                 			if(amount_to_allocate > sales_available)
                 			{
                 				amount_to_allocate = sales_available;
                 			}
                 			rec.Payment_Document="Sales Voucher";
                 			rec.Display_Name_Invoice_Voucher=ifnull(sales_rec.Sales_Voucher_Number,"");
                 			rec.Customer=ifnull(sales_rec.Display_Name_Customer,"");
                 			rec.Amount_Due=sales_available;
                 			rec.Amount_Allocated=amount_to_allocate;
                 			detail_balance = sales_available - amount_to_allocate;
                 			if(detail_balance < 0)
                 			{
                 				detail_balance = 0.0;
                 			}
                 			rec.Balance_Due=detail_balance;
                 			if(sales_rec.Customer != null && sales_rec.Customer.Delivery_Note_Required == true)
                 			{
                 				rec.Delivery_Note=sales_rec.Delivery_Note;
                 			}
                 			else
                 			{
                 				rec.Delivery_Note=null;
                 			}
                 			// =====================================================
                 			// 4. RECALCULATE PAYMENT RECEIPT VOUCHER
                 			// =====================================================
                 			receipt_total_allocated = 0.0;
                 			for each  receipt_det in Payment_Receipt_Details[Payment_Receipt_Voucher == receipt_id]
                 			{
                 				receipt_total_allocated = receipt_total_allocated + ifnull(receipt_det.Amount_Allocated,0.0);
                 			}
                 			receipt_not_allocated = total_received - receipt_total_allocated;
                 			if(receipt_not_allocated < 0)
                 			{
                 				receipt_not_allocated = 0.0;
                 			}
                 			receipt_rec.Total_Amount_Allocated=receipt_total_allocated;
                 			receipt_rec.Total_Amount_Not_Allocated=receipt_not_allocated;
                 			if(receipt_total_allocated <= 0)
                 			{
                 				receipt_rec.Payment_Receipt_Voucher_Status="Unassigned";
                 			}
                 			else if(receipt_not_allocated > 0)
                 			{
                 				receipt_rec.Payment_Receipt_Voucher_Status="Partially Assigned";
                 			}
                 			else
                 			{
                 				receipt_rec.Payment_Receipt_Voucher_Status="Assigned";
                 			}
                 			for each  receipt_det2 in Payment_Receipt_Details[Payment_Receipt_Voucher == receipt_id]
                 			{
                 				receipt_det2.Amount_Not_Allocated=receipt_not_allocated;
                 			}
                 			// =====================================================
                 			// 5. RECALCULATE SALES VOUCHER
                 			// Cash   -> Amount Paid
                 			// Credit -> Amount Credited
                 			// =====================================================
                 			cash_total = 0.0;
                 			credit_total = 0.0;
                 			for each  sales_det2 in Payment_Receipt_Details[Sales_Voucher == sales_id && Payment_Document == "Sales Voucher"]
                 			{
                 				payment_type = ifnull(sales_det2.Payment_Type,"").trim();
                 				if(payment_type == "Cash")
                 				{
                 					cash_total = cash_total + ifnull(sales_det2.Amount_Allocated,0.0);
                 				}
                 				else if(payment_type == "Credit")
                 				{
                 					credit_total = credit_total + ifnull(sales_det2.Amount_Credited,0.0);
                 				}
                 			}
                 			sales_balance = grand_total - cash_total - credit_total;
                 			if(sales_balance < 0)
                 			{
                 				sales_balance = 0.0;
                 			}
                 			sales_rec.Amount_Paid=cash_total;
                 			sales_rec.Amount_Credited=credit_total;
                 			sales_rec.Balance_Due=sales_balance;
                 			if(grand_total > 0 && sales_balance <= 0)
                 			{
                 				if(credit_total > 0 && cash_total <= 0)
                 				{
                 					sales_rec.Payment_Status="Credit";
                 				}
                 				else
                 				{
                 					sales_rec.Payment_Status="Paid";
                 				}
                 			}
                 			else if(credit_total > 0 && cash_total > 0)
                 			{
                 				sales_rec.Payment_Status="Partially Paid";
                 			}
                 			else if(credit_total > 0)
                 			{
                 				sales_rec.Payment_Status="Partially Credited";
                 			}
                 			else if(cash_total > 0)
                 			{
                 				sales_rec.Payment_Status="Partially Paid";
                 			}
                 			else
                 			{
                 				sales_rec.Payment_Status="Unpaid";
                 			}
                 			processed_count = processed_count + 1;
                 			if(amount_to_allocate > 0)
                 			{
                 				allocated_count = allocated_count + 1;
                 			}
                 		}		catch (backfill_error)
                 		{
                 			failed_count = failed_count + 1;
                 			error_row = Map();
                 			error_row.put("payment_receipt_detail_id",rec.ID);
                 			error_row.put("message",backfill_error.toString());
                 			failure_details.add(error_row);
                 		}
                 	}
                 	result.put("ok",failed_count == 0);
                 	result.put("message","Unpaid cash receipt allocation backfill completed.");
                 	result.put("loaded_unpaid",loaded_count);
                 	result.put("processed",processed_count);
                 	result.put("allocated",allocated_count);
                 	result.put("no_receipt_balance",no_receipt_balance_count);
                 	result.put("no_sales_balance",no_sales_balance_count);
                 	result.put("missing_links",missing_link_count);
                 	result.put("failed",failed_count);
                 	result.put("failure_details",failure_details);
                 	info result;
                 	return result;
                 }

map backfillCreditNoteAmounts()
{
                 	result = Map();
                 	start_from = 1500;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded = 0;
                 	updated = 0;
                 	already_filled = 0;
                 	no_amount_due = 0;
                 	failed = 0;
                 	failure_details = List();
                 	for each  credit_rec in Credit_Note[ID != 0] range from start_from to end_at
                 	{
                 		loaded = loaded + 1;
                 		try 
                 		{
                 			amount_due = ifnull(credit_rec.Amount_Due,0.0);
                 			credit_amount = ifnull(credit_rec.Credit_Amount,0.0);
                 			if(amount_due <= 0)
                 			{
                 				no_amount_due = no_amount_due + 1;
                 				continue;
                 			}
                 			// Fill Credit Amount when empty or zero
                 			if(credit_amount <= 0)
                 			{
                 				credit_amount = amount_due;
                 			}
                 			else
                 			{
                 				already_filled = already_filled + 1;
                 			}
                 			// Credit Amount must never exceed Amount Due
                 			if(credit_amount > amount_due)
                 			{
                 				credit_amount = amount_due;
                 			}
                 			credit_rec.Credit_Amount=credit_amount;
                 			balance_due = amount_due - credit_amount;
                 			if(balance_due < 0)
                 			{
                 				balance_due = 0.0;
                 			}
                 			credit_rec.Balance_Due=balance_due;
                 			updated = updated + 1;
                 		}		catch (backfill_error)
                 		{
                 			failed = failed + 1;
                 			error_row = Map();
                 			error_row.put("credit_note_id",credit_rec.ID);
                 			error_row.put("credit_note_number",ifnull(credit_rec.Credit_Note_Number,""));
                 			error_row.put("message",backfill_error.toString());
                 			failure_details.add(error_row);
                 		}
                 	}
                 	result.put("ok",failed == 0);
                 	result.put("message","Credit Note amount backfill completed.");
                 	result.put("start_from",start_from);
                 	result.put("next_start",start_from + loaded);
                 	result.put("loaded",loaded);
                 	result.put("updated",updated);
                 	result.put("already_filled",already_filled);
                 	result.put("no_amount_due",no_amount_due);
                 	result.put("failed",failed);
                 	result.put("failure_details",failure_details);
                 	info result;
                 	return result;
                 }

map backfillCreditNoteCustomerDetails()
{
                 	result = Map();
                 	start_from = 1200;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded_count = 0;
                 	updated_count = 0;
                 	missing_customer_count = 0;
                 	failed_count = 0;
                 	failure_details = List();
                 	for each  credit_rec in Credit_Note[ID != 0] range from start_from to end_at
                 	{
                 		loaded_count = loaded_count + 1;
                 		if(credit_rec.Customer == null)
                 		{
                 			missing_customer_count = missing_customer_count + 1;
                 			continue;
                 		}
                 		try 
                 		{
                 			customer_rec = credit_rec.Customer;
                 			// ==========================================
                 			// COPY CUSTOMER CREDIT DETAILS
                 			// ==========================================
                 			credit_rec.Display_Name_Customer=ifnull(customer_rec.Display_Name_Customer,"");
                 			credit_rec.Credit_Limit=ifnull(customer_rec.Credit_Limit,0.0);
                 			credit_rec.Current_Outstanding_Balance=ifnull(customer_rec.Current_Outstanding_Balance,0.0);
                 			credit_rec.Available_Credit=ifnull(customer_rec.Available_Credit,0.0);
                 			credit_rec.Credit_Days_Allowed=ifnull(customer_rec.Credit_Days_Allowed,0);
                 			// ==========================================
                 			// CREDIT AMOUNT
                 			// ==========================================
                 			credit_amount = ifnull(credit_rec.Balance_Due,0.0);
                 			available_credit = ifnull(credit_rec.Available_Credit,0.0);
                 			if(credit_amount > available_credit)
                 			{
                 				credit_amount = available_credit;
                 			}
                 			if(credit_amount < 0)
                 			{
                 				credit_amount = 0.0;
                 			}
                 			credit_rec.Credit_Amount=credit_amount;
                 			// ==========================================
                 			// DUE DATE
                 			// Use Credit Note Date for historical records
                 			// ==========================================
                 			base_date = credit_rec.Credit_Note_Date;
                 			if(base_date == null)
                 			{
                 				base_date = zoho.currentdate;
                 			}
                 			credit_rec.Due_Date=base_date.addDay(ifnull(credit_rec.Credit_Days_Allowed,0));
                 			updated_count = updated_count + 1;
                 		}		catch (backfill_error)
                 		{
                 			failed_count = failed_count + 1;
                 			error_row = Map();
                 			error_row.put("credit_note_id",credit_rec.ID);
                 			error_row.put("credit_note_number",ifnull(credit_rec.Credit_Note_Number,""));
                 			error_row.put("customer",ifnull(credit_rec.Display_Name_Customer,""));
                 			error_row.put("message",backfill_error.toString());
                 			failure_details.add(error_row);
                 		}
                 	}
                 	result.put("ok",failed_count == 0);
                 	result.put("message","Credit Note customer details backfill completed.");
                 	result.put("start_from",start_from);
                 	result.put("next_start",start_from + loaded_count);
                 	result.put("loaded",loaded_count);
                 	result.put("updated",updated_count);
                 	result.put("missing_customer",missing_customer_count);
                 	result.put("failed",failed_count);
                 	result.put("failure_details",failure_details);
                 	info result;
                 	return result;
                 }

map backfillCreditNotePayments()
{
                 	result = Map();
                 	// Always remain at zero because processed vouchers leave the Unpaid filter
                 	start_from = 0;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded_count = 0;
                 	processed_count = 0;
                 	payment_details_updated = 0;
                 	credit_notes_updated = 0;
                 	sales_vouchers_updated = 0;
                 	missing_payment_detail = 0;
                 	missing_credit_amount = 0;
                 	failed_count = 0;
                 	failure_details = List();
                 	// =====================================================
                 	// LOOP ONLY THROUGH CREDIT NOTES WHOSE SALES VOUCHER
                 	// IS CURRENTLY UNPAID
                 	// =====================================================
                 	for each  credit_rec in Credit_Note[Sales_Voucher != null && Sales_Voucher.Payment_Status == "Unpaid"] range from start_from to end_at
                 	{
                 		loaded_count = loaded_count + 1;
                 		try 
                 		{
                 			sales_id = credit_rec.Sales_Voucher.ID;
                 			sales_rec = Sales_Voucher[ID == sales_id];
                 			// Additional safety check
                 			if(sales_rec.ID == null)
                 			{
                 				continue;
                 			}
                 			if(ifnull(sales_rec.Payment_Status,"").trim() != "Unpaid")
                 			{
                 				continue;
                 			}
                 			// =====================================================
                 			// 1. ENSURE CREDIT NOTE AMOUNTS ARE CORRECT
                 			// =====================================================
                 			amount_due = ifnull(credit_rec.Amount_Due,0.0);
                 			credit_amount = ifnull(credit_rec.Credit_Amount,0.0);
                 			if(amount_due <= 0)
                 			{
                 				missing_credit_amount = missing_credit_amount + 1;
                 				continue;
                 			}
                 			// Backfill an empty Credit Amount from Amount Due
                 			if(credit_amount <= 0)
                 			{
                 				credit_amount = amount_due;
                 			}
                 			// Credit cannot exceed Amount Due
                 			if(credit_amount > amount_due)
                 			{
                 				credit_amount = amount_due;
                 			}
                 			credit_balance = amount_due - credit_amount;
                 			if(credit_balance < 0)
                 			{
                 				credit_balance = 0.0;
                 			}
                 			credit_rec.Credit_Amount=credit_amount;
                 			credit_rec.Balance_Due=credit_balance;
                 			// =====================================================
                 			// 2. UPDATE LINKED PAYMENT RECEIPT DETAILS
                 			// =====================================================
                 			detail_found = false;
                 			for each  pay_det in Payment_Receipt_Details[Credit_Note_Voucher == credit_rec.ID && Payment_Type == "Credit"]
                 			{
                 				detail_found = true;
                 				pay_det.Payment_Type="Credit";
                 				pay_det.Display_Name_Voucher=ifnull(credit_rec.Credit_Note_Number,"");
                 				pay_det.Payment_Document="Sales Voucher";
                 				pay_det.Sales_Voucher=sales_rec.ID;
                 				pay_det.Display_Name_Invoice_Voucher=ifnull(sales_rec.Sales_Voucher_Number,"");
                 				pay_det.Amount_Due=amount_due;
                 				pay_det.Amount_Credited=credit_amount;
                 				detail_balance = amount_due - credit_amount;
                 				if(detail_balance < 0)
                 				{
                 					detail_balance = 0.0;
                 				}
                 				pay_det.Balance_Due=detail_balance;
                 				if(pay_det.Customer == null)
                 				{
                 					pay_det.Customer=ifnull(sales_rec.Display_Name_Customer,"");
                 				}
                 				payment_details_updated = payment_details_updated + 1;
                 			}
                 			if(detail_found == false)
                 			{
                 				missing_payment_detail = missing_payment_detail + 1;
                 				continue;
                 			}
                 			// =====================================================
                 			// 3. REFRESH CREDIT NOTE DETAILS
                 			// =====================================================
                 			credit_rec.Sales_Voucher=sales_rec.ID;
                 			credit_rec.Display_Name_Sales_Voucher=ifnull(sales_rec.Sales_Voucher_Number,"");
                 			if(sales_rec.Customer != null)
                 			{
                 				credit_rec.Customer=sales_rec.Customer;
                 			}
                 			credit_rec.Display_Name_Customer=ifnull(sales_rec.Display_Name_Customer,"");
                 			credit_rec.Credit_Amount=credit_amount;
                 			credit_rec.Balance_Due=credit_balance;
                 			credit_notes_updated = credit_notes_updated + 1;
                 			// =====================================================
                 			// 4. RECALCULATE THE SALES VOUCHER
                 			//
                 			// Cash   -> Amount Paid
                 			// Credit -> Amount Credited
                 			// =====================================================
                 			cash_total = 0.0;
                 			credit_total = 0.0;
                 			for each  payment_rec in Payment_Receipt_Details[Sales_Voucher == sales_id && Payment_Document == "Sales Voucher"]
                 			{
                 				payment_type = ifnull(payment_rec.Payment_Type,"").trim();
                 				if(payment_type == "Cash")
                 				{
                 					cash_total = cash_total + ifnull(payment_rec.Amount_Allocated,0.0);
                 				}
                 				else if(payment_type == "Credit")
                 				{
                 					credit_total = credit_total + ifnull(payment_rec.Amount_Credited,0.0);
                 				}
                 			}
                 			grand_total = ifnull(sales_rec.Grand_Total,0.0);
                 			sales_balance = grand_total - cash_total - credit_total;
                 			if(sales_balance < 0)
                 			{
                 				sales_balance = 0.0;
                 			}
                 			sales_rec.Amount_Paid=cash_total;
                 			sales_rec.Amount_Credited=credit_total;
                 			sales_rec.Balance_Due=sales_balance;
                 			// =====================================================
                 			// 5. UPDATE PAYMENT STATUS
                 			// =====================================================
                 			if(grand_total > 0 && sales_balance <= 0)
                 			{
                 				// Entire Sales Voucher settled using cash and/or credit
                 				if(credit_total > 0 && cash_total <= 0)
                 				{
                 					sales_rec.Payment_Status="Credit";
                 				}
                 				else
                 				{
                 					sales_rec.Payment_Status="Paid";
                 				}
                 			}
                 			else if(credit_total > 0)
                 			{
                 				sales_rec.Payment_Status="Partially Credited";
                 			}
                 			else if(cash_total > 0)
                 			{
                 				sales_rec.Payment_Status="Partially Paid";
                 			}
                 			else
                 			{
                 				sales_rec.Payment_Status="Unpaid";
                 			}
                 			sales_vouchers_updated = sales_vouchers_updated + 1;
                 			processed_count = processed_count + 1;
                 		}		catch (backfill_error)
                 		{
                 			failed_count = failed_count + 1;
                 			error_row = Map();
                 			error_row.put("credit_note_id",credit_rec.ID);
                 			error_row.put("credit_note_number",ifnull(credit_rec.Credit_Note_Number,""));
                 			error_row.put("sales_voucher_number",ifnull(credit_rec.Display_Name_Sales_Voucher,""));
                 			error_row.put("message",backfill_error.toString());
                 			failure_details.add(error_row);
                 		}
                 	}
                 	// =====================================================
                 	// RESULT
                 	// =====================================================
                 	result.put("ok",failed_count == 0);
                 	result.put("message","Unpaid Credit Note payment backfill completed.");
                 	result.put("loaded_unpaid",loaded_count);
                 	result.put("processed",processed_count);
                 	result.put("payment_details_updated",payment_details_updated);
                 	result.put("credit_notes_updated",credit_notes_updated);
                 	result.put("sales_vouchers_updated",sales_vouchers_updated);
                 	result.put("missing_payment_detail",missing_payment_detail);
                 	result.put("missing_credit_amount",missing_credit_amount);
                 	result.put("failed",failed_count);
                 	result.put("failure_details",failure_details);
                 	info result;
                 	return result;
                 }

