map backfillEmployeeMonthlyDailyBillingBatch()
{
                 	result = Map();
                 	// =====================================================
                 	// BATCH SETTINGS
                 	//
                 	// RUN:
                 	// 5700
                 	// 5710
                 	// 5720
                 	// 5730
                 	// ...
                 	// =====================================================
                 	start_from = 6600;
                 	batch_size = 20;
                 	end_at = start_from + batch_size - 1;
                 	// =====================================================
                 	// COUNTERS
                 	// =====================================================
                 	loaded = 0;
                 	processed = 0;
                 	skipped = 0;
                 	failed = 0;
                 	employee_days_processed = 0;
                 	special_site_days_processed = 0;
                 	monthly_bills_created = 0;
                 	monthly_bills_found = 0;
                 	monthly_details_created = 0;
                 	monthly_details_updated = 0;
                 	special_monthly_details_created = 0;
                 	special_monthly_details_updated = 0;
                 	failed_details = List();
                 	// =====================================================
                 	// PREVENT REPEATING SAME GROUP INSIDE THIS BATCH
                 	// =====================================================
                 	processed_employee_days = List();
                 	processed_special_site_days = List();
                 	// =====================================================
                 	// LOAD CURRENT BATCH
                 	// =====================================================
                 	for each  rec in Voucher_Register[Employee != null] sort by ID asc range from start_from to end_at
                 	{
                 		loaded = loaded + 1;
                 		record_ready = false;
                 		record_failed = false;
                 		try 
                 		{
                 			// =================================================
                 			// 1. REQUIRE EMPLOYEE + DATE
                 			// =================================================
                 			if(rec.Employee != null && rec.Date_Time_In != null)
                 			{
                 				vDate = rec.Date_Time_In.toDate();
                 				employee_id = rec.Employee.ID;
                 				// =================================================
                 				// 2. EMPLOYEE + DATE KEY
                 				// =================================================
                 				employeeDayKey = employee_id.toString() + "|" + vDate.toString("yyyy-MM-dd");
                 				if(!processed_employee_days.contains(employeeDayKey))
                 				{
                 					processed_employee_days.add(employeeDayKey);
                 					employee_days_processed = employee_days_processed + 1;
                 					// =================================================
                 					// 3. BASIC VALUES
                 					// =================================================
                 					voucherType = ifnull(rec.Display_Name_Voucher_Type,"").trim();
                 					sourceVal = ifnull(rec.Display_Name_Employee,"").trim();
                 					siteVal = ifnull(rec.Display_Name_Site,"").trim();
                 					accountVal = siteVal;
                 					if(accountVal == "")
                 					{
                 						accountVal = "Unassigned Account";
                 					}
                 					// =================================================
                 					// 4. EMPLOYEE DETAILS
                 					// =================================================
                 					empName = ifnull(rec.Employee.Employee_Name,"").trim();
                 					empNumber = "";
                 					employee_number_value = 0;
                 					if(rec.Employee.Employee_Number != null)
                 					{
                 						employee_number_value = rec.Employee.Employee_Number;
                 						empNumber = employee_number_value.toString();
                 					}
                 					displayVendorName = empName;
                 					if(empNumber != "")
                 					{
                 						displayVendorName = empName + " - " + empNumber;
                 					}
                 					billName = displayVendorName;
                 					// =================================================
                 					// 5. GET MONTHLY SALARY
                 					// =================================================
                 					monthlySalary = 0.0;
                 					allowanceInput = Map();
                 					allowanceInput.put("Employee_ID",employee_id);
                 					allowanceResp = employee_management.getEmployeeActiveAllowance(allowanceInput);
                 					if(allowanceResp != null)
                 					{
                 						monthlySalary = ifnull(allowanceResp.get("Monthly_Salary"),0.0);
                 					}
                 					// =================================================
                 					// ONLY MONTHLY EMPLOYEES
                 					// =================================================
                 					if(monthlySalary > 0)
                 					{
                 						// =================================================
                 						// 6. SPECIAL EMPLOYEE?
                 						//
                 						// 10000 - 20000
                 						// =================================================
                 						specialMonthlyEmployee = false;
                 						if(employee_number_value >= 10000 && employee_number_value <= 20000)
                 						{
                 							specialMonthlyEmployee = true;
                 						}
                 						// =================================================
                 						// 7. NORMAL MONTHLY EMPLOYEE
                 						// =================================================
                 						if(specialMonthlyEmployee == false)
                 						{
                 							// =============================================
                 							// BUILD ALL VOUCHERS USED BY THIS EMPLOYEE
                 							// ON THIS DATE
                 							// =============================================
                 							dailyVoucherReference = "";
                 							dailyVoucherDetails = "";
                 							employeeVouchers = Voucher_Register[Employee == employee_id];
                 							for each  dayRec in employeeVouchers
                 							{
                 								if(dayRec.Date_Time_In != null)
                 								{
                 									if(dayRec.Date_Time_In.toDate() == vDate)
                 									{
                 										dayVoucherNumber = ifnull(dayRec.Voucher_Number,"").trim();
                 										dayVoucherType = ifnull(dayRec.Display_Name_Voucher_Type,"").trim();
                 										if(dayVoucherNumber != "")
                 										{
                 											// =================================
                 											// REFERENCE
                 											// =================================
                 											if(dailyVoucherReference == "")
                 											{
                 												dailyVoucherReference = dayVoucherNumber;
                 											}
                 											else
                 											{
                 												if(!dailyVoucherReference.contains(dayVoucherNumber))
                 												{
                 													dailyVoucherReference = dailyVoucherReference + ", " + dayVoucherNumber;
                 												}
                 											}
                 											// =================================
                 											// DETAILS
                 											// =================================
                 											voucherLine = dayVoucherNumber;
                 											if(dayVoucherType != "")
                 											{
                 												voucherLine = voucherLine + " - " + dayVoucherType;
                 											}
                 											if(dailyVoucherDetails == "")
                 											{
                 												dailyVoucherDetails = voucherLine;
                 											}
                 											else
                 											{
                 												if(!dailyVoucherDetails.contains(voucherLine))
                 												{
                 													dailyVoucherDetails = dailyVoucherDetails + "\n" + voucherLine;
                 												}
                 											}
                 										}
                 									}
                 								}
                 							}
                 							// =============================================
                 							// FALLBACK
                 							// =============================================
                 							if(dailyVoucherReference == "")
                 							{
                 								dailyVoucherReference = ifnull(rec.Voucher_Number,"");
                 							}
                 							if(dailyVoucherDetails == "")
                 							{
                 								dailyVoucherDetails = ifnull(rec.Voucher_Number,"");
                 								if(voucherType != "")
                 								{
                 									dailyVoucherDetails = dailyVoucherDetails + " - " + voucherType;
                 								}
                 							}
                 							// =================================================
                 							// 8. GET MONTHLY PERIOD
                 							// =================================================
                 							monthlyPeriodResp = thisapp.billing.getEmployeeBillPeriod(vDate,"Monthly Payment");
                 							monthlyBillDate = monthlyPeriodResp.get("Bill_Date");
                 							monthlyReference = monthlyPeriodResp.get("Bill_Number");
                 							// =================================================
                 							// 9. FIND / CREATE MONTHLY BILL
                 							// =================================================
                 							existingMonthlyBill = Bill[Employee_Vendor == employee_id && Bill_Number == monthlyReference && Bill_Type == "Employee Bill"];
                 							monthlyBillID = null;
                 							if(existingMonthlyBill.ID != null)
                 							{
                 								monthlyBillID = existingMonthlyBill.ID;
                 								monthly_bills_found = monthly_bills_found + 1;
                 								existingMonthlyBill.Bill_Date=monthlyBillDate;
                 								existingMonthlyBill.Bill_Type="Employee Bill";
                 								existingMonthlyBill.Employee_Vendor=employee_id;
                 								existingMonthlyBill.Display_Name_Vendor=displayVendorName;
                 								existingMonthlyBill.Bill_Name=billName;
                 								existingMonthlyBill.Bill_Number=monthlyReference;
                 							}
                 							else
                 							{
                 								monthlyBillID = insert into Bill
                 								[
                 									Bill_Date=monthlyBillDate
                 									Bill_Type="Employee Bill"
                 									Employee_Vendor=employee_id
                 									Display_Name_Vendor=displayVendorName
                 									Bill_Name=billName
                 									Bill_Number=monthlyReference
                 									Bill_Status="Draft"
                 									Payment_Status="Not Paid"
                 									Added_User=zoho.loginuser
                 								];
                 								if(monthlyBillID != null)
                 								{
                 									monthly_bills_created = monthly_bills_created + 1;
                 								}
                 							}
                 							// =================================================
                 							// 10. ONE MONTHLY DETAIL PER EMPLOYEE PER DAY
                 							// =================================================
                 							if(monthlyBillID != null)
                 							{
                 								monthlyDetailText = "";
                 								monthlyDetailText = "Date: " + vDate.toString("dd-MMM-yyyy");
                 								monthlyDetailText = monthlyDetailText + "\nEmployee: " + displayVendorName;
                 								monthlyDetailText = monthlyDetailText + "\nSite: " + siteVal;
                 								monthlyDetailText = monthlyDetailText + "\nMonth: " + monthlyReference;
                 								monthlyDetailText = monthlyDetailText + "\nMonthly Salary: " + monthlySalary.toString();
                 								monthlyDetailText = monthlyDetailText + "\n\nVouchers:";
                 								monthlyDetailText = monthlyDetailText + "\n" + dailyVoucherDetails;
                 								// =============================================
                 								// UNIQUE:
                 								// BILL + DATE + MONTHLY PAYMENT
                 								// =============================================
                 								existingMonthlyDetail = Bill_Details[Bill == monthlyBillID && Details_Date == vDate && Expense_Type == "Monthly Payment" && Source_Form == "Masaka Site Management - Voucher Register"];
                 								if(existingMonthlyDetail.count() == 0)
                 								{
                 									newMonthlyDetailID = insert into Bill_Details
                 									[
                 										Bill=monthlyBillID
                 										Display_Name_Bill=billName + " - " + monthlyReference
                 										Details_Date=vDate
                 										Source=sourceVal
                 										Reference=dailyVoucherReference
                 										Details=monthlyDetailText
                 										Expense_Type="Monthly Payment"
                 										Quantity=1.00
                 										Account=accountVal
                 										Current_Site=siteVal
                 										Source_Record_ID=rec.ID
                 										Source_Form="Masaka Site Management - Voucher Register"
                 										Bill_Details_Status="Draft"
                 										Added_User=zoho.loginuser
                 									];
                 									if(newMonthlyDetailID != null)
                 									{
                 										monthly_details_created = monthly_details_created + 1;
                 										record_ready = true;
                 									}
                 								}
                 								else
                 								{
                 									for each  monthlyBD in existingMonthlyDetail
                 									{
                 										monthlyBD.Display_Name_Bill=billName + " - " + monthlyReference;
                 										monthlyBD.Source=sourceVal;
                 										monthlyBD.Reference=dailyVoucherReference;
                 										monthlyBD.Details=monthlyDetailText;
                 										monthlyBD.Quantity=1.00;
                 										monthlyBD.Account=accountVal;
                 										monthlyBD.Current_Site=siteVal;
                 										monthly_details_updated = monthly_details_updated + 1;
                 										record_ready = true;
                 										break;
                 									}
                 								}
                 							}
                 							else
                 							{
                 								record_failed = true;
                 								fail_map = Map();
                 								fail_map.put("Voucher_ID",rec.ID);
                 								fail_map.put("Voucher_Number",ifnull(rec.Voucher_Number,""));
                 								fail_map.put("Reason","Monthly Bill could not be created or found.");
                 								failed_details.add(fail_map);
                 							}
                 						}
                 						// =================================================
                 						// 11. SPECIAL MONTHLY EMPLOYEES
                 						//
                 						// EMPLOYEE NUMBER 10000 - 20000
                 						//
                 						// DO NOT CREATE MONTHLY BILL
                 						//
                 						// ONE MONTHLY DETAIL:
                 						// SITE + DATE
                 						// =================================================
                 						else
                 						{
                 							if(siteVal != "")
                 							{
                 								specialSiteDayKey = siteVal + "|" + vDate.toString("yyyy-MM-dd");
                 								// =============================================
                 								// PROCESS SITE/DAY ONLY ONCE IN THIS BATCH
                 								// =============================================
                 								if(!processed_special_site_days.contains(specialSiteDayKey))
                 								{
                 									processed_special_site_days.add(specialSiteDayKey);
                 									special_site_days_processed = special_site_days_processed + 1;
                 									specialEmployees = List();
                 									specialSupervisorVouchers = List();
                 									specialEmployeeCount = 0;
                 									specialDetailsText = "";
                 									// =============================================
                 									// GET ALL VOUCHERS AT THIS SITE
                 									// =============================================
                 									siteVouchers = Voucher_Register[Display_Name_Site == siteVal];
                 									for each  siteVr in siteVouchers
                 									{
                 										if(siteVr.Employee != null && siteVr.Date_Time_In != null)
                 										{
                 											if(siteVr.Date_Time_In.toDate() == vDate)
                 											{
                 												siteEmpNo = 0;
                 												if(siteVr.Employee.Employee_Number != null)
                 												{
                 													siteEmpNo = siteVr.Employee.Employee_Number;
                 												}
                 												// =================================
                 												// SPECIAL RANGE
                 												// =================================
                 												if(siteEmpNo >= 10000 && siteEmpNo <= 20000)
                 												{
                 													siteEmployeeID = siteVr.Employee.ID;
                 													// =================================
                 													// CHECK MONTHLY SALARY
                 													// =================================
                 													siteAllowanceInput = Map();
                 													siteAllowanceInput.put("Employee_ID",siteEmployeeID);
                 													siteAllowanceResp = employee_management.getEmployeeActiveAllowance(siteAllowanceInput);
                 													siteMonthlySalary = 0.0;
                 													if(siteAllowanceResp != null)
                 													{
                 														siteMonthlySalary = ifnull(siteAllowanceResp.get("Monthly_Salary"),0.0);
                 													}
                 													if(siteMonthlySalary > 0)
                 													{
                 														siteEmployeeKey = siteEmployeeID.toString();
                 														siteEmployeeName = ifnull(siteVr.Employee.Employee_Name,"").trim();
                 														siteEmployeeDisplay = siteEmployeeName;
                 														if(siteEmpNo > 0)
                 														{
                 															siteEmployeeDisplay = siteEmployeeName + " - " + siteEmpNo.toString();
                 														}
                 														// =================================
                 														// EMPLOYEE HEADING ONCE
                 														// =================================
                 														if(!specialEmployees.contains(siteEmployeeKey))
                 														{
                 															specialEmployees.add(siteEmployeeKey);
                 															specialEmployeeCount = specialEmployeeCount + 1;
                 															if(specialDetailsText != "")
                 															{
                 																specialDetailsText = specialDetailsText + "\n";
                 															}
                 															specialDetailsText = specialDetailsText + "\n" + siteEmployeeDisplay;
                 														}
                 														// =================================
                 														// VOUCHER
                 														// =================================
                 														siteVoucherNo = ifnull(siteVr.Voucher_Number,"").trim();
                 														siteVoucherType = ifnull(siteVr.Display_Name_Voucher_Type,"").trim();
                 														if(siteVoucherNo != "")
                 														{
                 															siteVoucherLine = "  - " + siteVoucherNo;
                 															if(siteVoucherType != "")
                 															{
                 																siteVoucherLine = siteVoucherLine + " - " + siteVoucherType;
                 															}
                 															if(!specialDetailsText.contains(siteVoucherLine))
                 															{
                 																specialDetailsText = specialDetailsText + "\n" + siteVoucherLine;
                 															}
                 														}
                 														// =================================
                 														// SUPERVISOR VOUCHER
                 														// =================================
                 														supervisorVoucher = ifnull(siteVr.Display_Name_Issued_By,"").trim();
                 														if(supervisorVoucher != "")
                 														{
                 															if(!specialSupervisorVouchers.contains(supervisorVoucher))
                 															{
                 																specialSupervisorVouchers.add(supervisorVoucher);
                 															}
                 														}
                 													}
                 												}
                 											}
                 										}
                 									}
                 									// =============================================
                 									// BUILD REFERENCE
                 									// =============================================
                 									specialReference = "";
                 									for each  supVoucher in specialSupervisorVouchers
                 									{
                 										if(specialReference == "")
                 										{
                 											specialReference = supVoucher;
                 										}
                 										else
                 										{
                 											specialReference = specialReference + ", " + supVoucher;
                 										}
                 									}
                 									// =============================================
                 									// CREATE / UPDATE SITE DAILY MONTHLY DETAIL
                 									// =============================================
                 									if(specialEmployeeCount > 0)
                 									{
                 										specialMonthlyText = "";
                 										specialMonthlyText = "Date: " + vDate.toString("dd-MMM-yyyy");
                 										specialMonthlyText = specialMonthlyText + "\nSite: " + siteVal;
                 										specialMonthlyText = specialMonthlyText + "\nEmployees: " + specialEmployeeCount.toString();
                 										specialMonthlyText = specialMonthlyText + "\n\nEmployees / Vouchers:";
                 										specialMonthlyText = specialMonthlyText + specialDetailsText;
                 										// =========================================
                 										// USE A DIFFERENT SOURCE FORM
                 										// SO IT CANNOT MIX WITH NORMAL EMPLOYEE
                 										// MONTHLY DETAILS
                 										// =========================================
                 										existingSpecialDetail = Bill_Details[Details_Date == vDate && Current_Site == siteVal && Expense_Type == "Monthly Payment" && Source_Form == "Masaka Site Management - Site Daily Monthly Employees"];
                 										if(existingSpecialDetail.count() == 0)
                 										{
                 											newSpecialDetailID = insert into Bill_Details
                 											[
                 												Details_Date=vDate
                 												Source=siteVal
                 												Reference=specialReference
                 												Details=specialMonthlyText
                 												Expense_Type="Monthly Payment"
                 												Quantity=specialEmployeeCount
                 												Account=accountVal
                 												Current_Site=siteVal
                 												Source_Record_ID=rec.ID
                 												Source_Form="Masaka Site Management - Site Daily Monthly Employees"
                 												Bill_Details_Status="Draft"
                 												Added_User=zoho.loginuser
                 											];
                 											if(newSpecialDetailID != null)
                 											{
                 												special_monthly_details_created = special_monthly_details_created + 1;
                 												record_ready = true;
                 											}
                 										}
                 										else
                 										{
                 											for each  specialBD in existingSpecialDetail
                 											{
                 												specialBD.Source=siteVal;
                 												specialBD.Reference=specialReference;
                 												specialBD.Details=specialMonthlyText;
                 												specialBD.Quantity=specialEmployeeCount;
                 												specialBD.Account=accountVal;
                 												specialBD.Current_Site=siteVal;
                 												special_monthly_details_updated = special_monthly_details_updated + 1;
                 												record_ready = true;
                 												break;
                 											}
                 										}
                 									}
                 								}
                 								else
                 								{
                 									// Same special site/date already
                 									// processed in this batch
                 									record_ready = true;
                 								}
                 							}
                 						}
                 					}
                 					else
                 					{
                 						// =============================================
                 						// NO MONTHLY SALARY
                 						// =============================================
                 						skipped = skipped + 1;
                 					}
                 					// =================================================
                 					// 12. RESULT FOR THIS EMPLOYEE/DAY
                 					// =================================================
                 					if(record_failed == true)
                 					{
                 						failed = failed + 1;
                 					}
                 					if(record_ready == true)
                 					{
                 						processed = processed + 1;
                 					}
                 				}
                 				else
                 				{
                 					// =============================================
                 					// SAME EMPLOYEE + DATE ALREADY PROCESSED
                 					// =============================================
                 					skipped = skipped + 1;
                 				}
                 			}
                 			else
                 			{
                 				skipped = skipped + 1;
                 			}
                 		}		catch (e)
                 		{
                 			failed = failed + 1;
                 			fail_map = Map();
                 			fail_map.put("Voucher_ID",rec.ID);
                 			fail_map.put("Voucher_Number",ifnull(rec.Voucher_Number,""));
                 			fail_map.put("Reason",e.toString());
                 			failed_details.add(fail_map);
                 		}
                 	}
                 	// =====================================================
                 	// RESULT
                 	// =====================================================
                 	result.put("start_from",start_from);
                 	result.put("end_at",end_at);
                 	result.put("batch_size",batch_size);
                 	result.put("loaded",loaded);
                 	result.put("employee_days_processed",employee_days_processed);
                 	result.put("special_site_days_processed",special_site_days_processed);
                 	result.put("processed",processed);
                 	result.put("skipped",skipped);
                 	result.put("failed",failed);
                 	// =====================================================
                 	// NORMAL MONTHLY
                 	// =====================================================
                 	result.put("monthly_bills_created",monthly_bills_created);
                 	result.put("monthly_bills_found",monthly_bills_found);
                 	result.put("monthly_details_created",monthly_details_created);
                 	result.put("monthly_details_updated",monthly_details_updated);
                 	// =====================================================
                 	// SPECIAL MONTHLY
                 	// =====================================================
                 	result.put("special_monthly_details_created",special_monthly_details_created);
                 	result.put("special_monthly_details_updated",special_monthly_details_updated);
                 	// =====================================================
                 	// FAILURES
                 	// =====================================================
                 	result.put("failed_details",failed_details);
                 	// =====================================================
                 	// LAST BATCH
                 	// =====================================================
                 	if(loaded < batch_size)
                 	{
                 		result.put("last_batch",true);
                 	}
                 	else
                 	{
                 		result.put("last_batch",false);
                 	}
                 	info result;
                 	return result;
                 }

void backfillInOfficeCashEnvelopes()
{
                 	updated_count = 0;
                 	for each  envelope_rec in Cash_Envelope[Cash_Envelope_Status == "In Office"]
                 	{
                 		envelope_total = ifnull(envelope_rec.Cash_Envelope_Total,0.0);
                 		// =================================================
                 		// FORCE THE FULL ENVELOPE TOTAL AS BANKED
                 		// =================================================
                 		envelope_rec.Amount_Banked=round(envelope_total,2);
                 		// =================================================
                 		// NOTHING REMAINS UNBANKED
                 		// =================================================
                 		envelope_rec.Amount_Not_Banked=0.0;
                 		// =================================================
                 		// CHANGE STATUS TO BANKED
                 		// =================================================
                 		envelope_rec.Cash_Envelope_Status="Banked";
                 		updated_count = updated_count + 1;
                 	}
                 	info "In Office Cash Envelope backfill completed.";
                 	info "Records updated: " + updated_count;
                 }

map backfillInvoiceDetailsDateAndVoucherLookup()
{
                 	result = Map();
                 	loaded = 0;
                 	updated = 0;
                 	skipped = 0;
                 	failed = 0;
                 	skipped_records = List();
                 	failed_records = List();
                 	for each  inv in Invoice_Details[Source_Form == "Sales Voucher" && Details_Date == null || Sales_Voucher == null]
                 	{
                 		loaded = loaded + 1;
                 		try 
                 		{
                 			voucher_number = ifnull(inv.Display_Name_Voucher,"").trim();
                 			if(voucher_number == "")
                 			{
                 				skipped = skipped + 1;
                 				skip_info = Map();
                 				skip_info.put("Invoice_Details_ID",inv.ID);
                 				skip_info.put("Reason","Display Name Voucher is empty.");
                 				skipped_records.add(skip_info);
                 				continue;
                 			}
                 			changed = false;
                 			// =====================================================
                 			// 1. FIND SALES VOUCHER BY VOUCHER NUMBER
                 			// Used to backfill Details Date.
                 			// =====================================================
                 			sv = Sales_Voucher[Sales_Voucher_Number == voucher_number];
                 			if(sv.ID != null)
                 			{
                 				if(inv.Details_Date == null && sv.Sales_Voucher_Date != null)
                 				{
                 					inv.Details_Date=sv.Sales_Voucher_Date;
                 					changed = true;
                 				}
                 			}
                 			// =====================================================
                 			// 2. FIND PAYMENT RECEIPT DETAIL
                 			// Sales_Voucher lookup in Invoice_Details points here.
                 			// =====================================================
                 			prd = Payment_Receipt_Details[Payment_Document == "Sales Voucher" && Display_Name_Invoice_Voucher == voucher_number] sort by ID desc;
                 			if(inv.Sales_Voucher == null && prd.ID != null)
                 			{
                 				// Assign Payment Receipt Details ID to the lookup.
                 				inv.Sales_Voucher=prd.ID;
                 				changed = true;
                 			}
                 			if(changed)
                 			{
                 				updated = updated + 1;
                 			}
                 			else
                 			{
                 				skipped = skipped + 1;
                 				reason = "";
                 				if(sv.ID == null && prd.ID == null)
                 				{
                 					reason = "No matching Sales Voucher or Payment Receipt Detail found.";
                 				}
                 				else if(prd.ID == null && inv.Sales_Voucher == null)
                 				{
                 					reason = "No matching Payment Receipt Detail found for the lookup.";
                 				}
                 				else if(sv.ID == null && inv.Details_Date == null)
                 				{
                 					reason = "No matching Sales Voucher found for Details Date.";
                 				}
                 				else
                 				{
                 					reason = "Required values were already filled.";
                 				}
                 				skip_info = Map();
                 				skip_info.put("Invoice_Details_ID",inv.ID);
                 				skip_info.put("Display_Name_Voucher",voucher_number);
                 				skip_info.put("Reason",reason);
                 				skipped_records.add(skip_info);
                 			}
                 		}		catch (e)
                 		{
                 			failed = failed + 1;
                 			failure = Map();
                 			failure.put("Invoice_Details_ID",inv.ID);
                 			failure.put("Display_Name_Voucher",ifnull(inv.Display_Name_Voucher,""));
                 			failure.put("Error",e.toString());
                 			failed_records.add(failure);
                 		}
                 	}
                 	result.put("ok",true);
                 	result.put("loaded",loaded);
                 	result.put("updated",updated);
                 	result.put("skipped",skipped);
                 	result.put("failed",failed);
                 	result.put("skipped_records",skipped_records);
                 	result.put("failed_records",failed_records);
                 	return result;
                 }

void backfillInvoiceDetailsNumberPlate()
{
                 	updated_count = 0;
                 	skipped_count = 0;
                 	error_count = 0;
                 	invoice_rows = Invoice_Details[Source_Form == "Sales Voucher" && Source_Record_ID != null];
                 	for each  inv in invoice_rows
                 	{
                 		try 
                 		{
                 			sales_voucher_id = inv.Source_Record_ID.toLong();
                 			sv_rec = Sales_Voucher[ID == sales_voucher_id];
                 			if(sv_rec.ID != null)
                 			{
                 				number_plate_text = ifnull(sv_rec.Display_Name_Number_Plate,"").trim();
                 				if(number_plate_text != "")
                 				{
                 					old_item_text = ifnull(inv.Item,"").trim();
                 					// Prevent adding the number plate more than once
                 					if(!old_item_text.startsWith("Number Plate:"))
                 					{
                 						inv.Item="Number Plate: " + number_plate_text + if(old_item_text != "","\n" + old_item_text,"");
                 						updated_count = updated_count + 1;
                 					}
                 					else
                 					{
                 						skipped_count = skipped_count + 1;
                 					}
                 				}
                 				else
                 				{
                 					skipped_count = skipped_count + 1;
                 					info "Skipped Invoice Detail " + inv.ID + ": Sales Voucher has no number plate.";
                 				}
                 			}
                 			else
                 			{
                 				error_count = error_count + 1;
                 				info "Sales Voucher not found for Invoice Detail: " + inv.ID;
                 			}
                 		}		catch (e)
                 		{
                 			error_count = error_count + 1;
                 			info "Error on Invoice Detail " + inv.ID + ": " + e.toString();
                 		}
                 	}
                 	info "NUMBER PLATE BACKFILL COMPLETED";
                 	info "Updated: " + updated_count;
                 	info "Skipped: " + skipped_count;
                 	info "Errors: " + error_count;
                 }

map backfillMasakaSalesVoucherBusinessDivisionDetails()
{
                 	result = Map();
                 	// ==================================================
                 	// BATCH SETTINGS
                 	// start_from is the record position, not the record ID
                 	// Examples: 0, 500, 1000, 1500...
                 	// ==================================================
                 	start_from = 13000;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	source_ids = List();
                 	total_loaded = 0;
                 	// ==================================================
                 	// FIRST LOOP: COLLECT SALES VOUCHER RECORD IDS
                 	// ==================================================
                 	for each  sales_rec in Sales_Voucher[ID != 0] sort by ID asc range from start_from to end_at
                 	{
                 		total_loaded = total_loaded + 1;
                 		if(sales_rec.ID != null)
                 		{
                 			source_ids.add(sales_rec.ID.toLong());
                 		}
                 	}
                 	// ==================================================
                 	// EMPTY BATCH
                 	// ==================================================
                 	if(total_loaded == 0)
                 	{
                 		result.put("ok",true);
                 		result.put("message","No Sales Voucher records were found in this batch.");
                 		result.put("start_from",start_from);
                 		result.put("end_at",end_at);
                 		result.put("next_start_from",start_from);
                 		result.put("loaded",0);
                 		result.put("created",0);
                 		result.put("updated",0);
                 		result.put("failed",0);
                 		result.put("last_batch",true);
                 		result.put("failure_details",List());
                 		info result;
                 		return result;
                 	}
                 	// ==================================================
                 	// CHECK WHICH SOURCE IDS ALREADY EXIST
                 	// ==================================================
                 	check_resp = grapes_group.masakasite.getExistingMasakaSalesVoucherIDs(source_ids);
                 	existing_ids = List();
                 	if(check_resp != null && ifnull(check_resp.get("ok"),false) == true)
                 	{
                 		returned_ids = check_resp.get("existing_ids");
                 		if(returned_ids != null)
                 		{
                 			for each  returned_id in returned_ids
                 			{
                 				if(returned_id != null && returned_id.toString().trim() != "")
                 				{
                 					existing_ids.add(returned_id.toString().toLong());
                 				}
                 			}
                 		}
                 	}
                 	else
                 	{
                 		result.put("ok",false);
                 		result.put("message","Could not check existing Business Division Details.");
                 		result.put("start_from",start_from);
                 		result.put("end_at",end_at);
                 		result.put("loaded",total_loaded);
                 		result.put("response",check_resp);
                 		info result;
                 		return result;
                 	}
                 	created_count = 0;
                 	updated_count = 0;
                 	failed_count = 0;
                 	failure_details = List();
                 	// ==================================================
                 	// SECOND LOOP: CREATE OR UPDATE EVERY RECORD
                 	// ==================================================
                 	for each  sales_rec in Sales_Voucher[ID != 0] sort by ID asc range from start_from to end_at
                 	{
                 		source_record_id = sales_rec.ID.toLong();
                 		was_existing = existing_ids.contains(source_record_id);
                 		voucher_number = ifnull(sales_rec.Sales_Voucher_Number,"").toString().trim();
                 		grand_total = round(ifnull(sales_rec.Grand_Total,0.0),2);
                 		transaction_date = zoho.currentdate;
                 		if(sales_rec.Sales_Voucher_Date != null)
                 		{
                 			transaction_date = sales_rec.Sales_Voucher_Date;
                 		}
                 		post = Map();
                 		// ------------------------------------------------
                 		// Source tracking
                 		// ------------------------------------------------
                 		post.put("Display_Name_Application","Masaka Site Management");
                 		post.put("Source_Form","Sales Voucher");
                 		post.put("Source_Record_ID",source_record_id);
                 		// Grapes Group lookup to Masaka Sales Voucher
                 		post.put("MSM_Sales_Voucher",source_record_id);
                 		post.put("Voucher_Number",voucher_number);
                 		// ------------------------------------------------
                 		// Transaction details
                 		// ------------------------------------------------
                 		post.put("Transaction_Date",transaction_date);
                 		post.put("Business_Division",null);
                 		post.put("Display_Name_Business_Division","");
                 		// ------------------------------------------------
                 		// Receivable totals
                 		// ------------------------------------------------
                 		post.put("Amount_To_Receive",grand_total);
                 		post.put("Amount_Received",0.0);
                 		post.put("Amount_Not_Received",grand_total);
                 		// ------------------------------------------------
                 		// Payable totals
                 		// ------------------------------------------------
                 		post.put("Amount_To_Pay",0.0);
                 		post.put("Amount_Paid",0.0);
                 		post.put("Amount_Not_Paid",0.0);
                 		try 
                 		{
                 			sync_resp = grapes_group.masakasite.postBusinessDivisionDetail(post);
                 			if(sync_resp != null && ifnull(sync_resp.get("ok"),false) == true)
                 			{
                 				if(was_existing)
                 				{
                 					updated_count = updated_count + 1;
                 				}
                 				else
                 				{
                 					created_count = created_count + 1;
                 				}
                 			}
                 			else
                 			{
                 				failed_count = failed_count + 1;
                 				error_row = Map();
                 				error_row.put("source_record_id",source_record_id);
                 				error_row.put("voucher_number",voucher_number);
                 				error_row.put("grand_total",grand_total);
                 				if(sync_resp != null)
                 				{
                 					error_row.put("message",ifnull(sync_resp.get("msg"),"Unknown synchronization error."));
                 					error_row.put("response",sync_resp);
                 				}
                 				else
                 				{
                 					error_row.put("message","No response received from Grapes Group.");
                 				}
                 				failure_details.add(error_row);
                 			}
                 		}		catch (sync_error)
                 		{
                 			failed_count = failed_count + 1;
                 			error_row = Map();
                 			error_row.put("source_record_id",source_record_id);
                 			error_row.put("voucher_number",voucher_number);
                 			error_row.put("grand_total",grand_total);
                 			error_row.put("message",sync_error.toString());
                 			failure_details.add(error_row);
                 		}
                 	}
                 	// ==================================================
                 	// RESULT
                 	// ==================================================
                 	next_start_from = start_from + batch_size;
                 	result.put("ok",failed_count == 0);
                 	result.put("message","Masaka Sales Voucher backfill batch completed.");
                 	result.put("start_from",start_from);
                 	result.put("end_at",end_at);
                 	result.put("next_start_from",next_start_from);
                 	result.put("loaded",total_loaded);
                 	result.put("created",created_count);
                 	result.put("updated",updated_count);
                 	result.put("failed",failed_count);
                 	result.put("failure_details",failure_details);
                 	if(total_loaded < batch_size)
                 	{
                 		result.put("last_batch",true);
                 	}
                 	else
                 	{
                 		result.put("last_batch",false);
                 	}
                 	info result;
                 	return result;
                 }

map backfillMissingPaymentReceipts()
{
                 	result = Map();
                 	start_from = 12000;
                 	batch_size = 1000;
                 	end_at = start_from + batch_size - 1;
                 	source_ids = List();
                 	total_loaded = 0;
                 	// ========================================
                 	// FIRST LOOP: COLLECT SOURCE RECORD IDS
                 	// ========================================
                 	for each  receipt_rec in Payment_Receipt_Voucher[ID != 0] range from start_from to end_at
                 	{
                 		total_loaded = total_loaded + 1;
                 		if(receipt_rec.ID != null)
                 		{
                 			source_ids.add(receipt_rec.ID.toLong());
                 		}
                 	}
                 	if(total_loaded == 0)
                 	{
                 		result.put("ok",true);
