                 	}
                 	// ========================================
                 	// CHECK WHICH RECORDS ALREADY EXIST
                 	// ========================================
                 	check_resp = payment_management.getExistingFreedomCityManagementPaymentReceiptIDs(source_ids);
                 	existing_ids = List();
                 	if(check_resp != null && ifnull(check_resp.get("ok"),false) == true)
