map backfillPaymentReceiptDetails()
{
                 	result = Map();
                 	start_from = 0;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded_count = 0;
                 	synced_count = 0;
                 	skipped_non_cash = 0;
                 	missing_voucher_count = 0;
                 	failed_count = 0;
                 	failure_details = List();
                 	for each  receipt_det in Payment_Receipt_Details[ID != 0] range from start_from to end_at
                 	{
                 		loaded_count = loaded_count + 1;
                 		// Only synchronize cash payment details
                 		if(ifnull(receipt_det.Payment_Type,"").trim() != "Cash")
                 		{
                 			skipped_non_cash = skipped_non_cash + 1;
                 			continue;
                 		}
                 		if(receipt_det.Payment_Receipt_Voucher == null)
                 		{
                 			missing_voucher_count = missing_voucher_count + 1;
                 			continue;
                 		}
                 		try 
                 		{
                 			// ==========================================
                 			// BUILD DESCRIPTION
                 			// ==========================================
                 			description = "";
                 			doc_name = "";
                 			if(ifnull(receipt_det.Display_Name_Invoice_Voucher,"") != "")
                 			{
                 				doc_name = ifnull(receipt_det.Display_Name_Invoice_Voucher,"");
                 				if(doc_name.contains(" - "))
                 				{
                 					doc_name = doc_name.getPrefix(" - ");
                 				}
                 			}
                 			if(ifnull(receipt_det.Payment_Document,"") != "")
                 			{
                 				description = ifnull(receipt_det.Payment_Document,"");
                 			}
                 			if(doc_name != "")
                 			{
                 				if(description != "")
                 				{
                 					description = description + " - ";
                 				}
                 				description = description + doc_name;
                 			}
                 			// ==========================================
                 			// AMOUNT TO SYNCHRONIZE
                 			// ==========================================
                 			sync_amount = ifnull(receipt_det.Amount_Allocated,0.0);
                 			if(receipt_det.Payment_Document == "Cash Deposit" && sync_amount <= 0)
                 			{
                 				sync_amount = ifnull(receipt_det.Amount_Not_Allocated,0.0);
                 			}
                 			// ==========================================
                 			// TRANSACTION DATE
                 			// ==========================================
                 			transaction_date_txt = "";
                 			if(receipt_det.Payment_Receipt_Voucher.Payment_Receipt_Date != null)
                 			{
                 				transaction_date_txt = receipt_det.Payment_Receipt_Voucher.Payment_Receipt_Date.toString("yyyy-MM-dd HH:mm:ss");
                 			}
                 			// ==========================================
                 			// CREATED AND UPDATED TIMES
                 			// ==========================================
                 			created_time_txt = "";
                 			if(receipt_det.Created_By_Time != null)
                 			{
                 				created_time_txt = receipt_det.Created_By_Time.toString("yyyy-MM-dd HH:mm:ss");
                 			}
                 			updated_time_txt = "";
                 			if(receipt_det.Updated_By_Time != null)
                 			{
                 				updated_time_txt = receipt_det.Updated_By_Time.toString("yyyy-MM-dd HH:mm:ss");
                 			}
                 			// ==========================================
                 			// BUILD PAYLOAD
                 			// ==========================================
                 			payload = Map();
                 			payload.put("Payment_Voucher_Source_ID",receipt_det.Payment_Receipt_Voucher.ID.toLong());
                 			payload.put("Display_Name_Payment_Voucher",ifnull(receipt_det.Display_Name_Voucher,""));
                 			payload.put("Line_Number",receipt_det.Line_Number);
                 			payload.put("Description",description);
                 			payload.put("Amount_Allocated",sync_amount);
                 			payload.put("Application","Masaka Site Management");
                 			payload.put("Transaction_Date",transaction_date_txt);
                 			payload.put("Source_Form","Payment Receipt Details");
                 			payload.put("Source_Record_ID",receipt_det.ID.toLong());
                 			payload.put("Voucher_Number",ifnull(receipt_det.Payment_Receipt_Voucher.Payment_Receipt_Number,""));
                 			payload.put("User_Name",ifnull(receipt_det.User_Name,""));
                 			payload.put("User_Email",ifnull(receipt_det.User_Email,""));
                 			payload.put("User_Role",ifnull(receipt_det.User_Role,""));
                 			payload.put("Created_By_Name",ifnull(receipt_det.Created_By_Name,""));
                 			payload.put("Created_By_Email",ifnull(receipt_det.Created_By_Email,""));
                 			payload.put("Created_By_Time",created_time_txt);
                 			payload.put("Updated_By_Name",ifnull(receipt_det.Updated_By_Name,""));
                 			payload.put("Updated_By_Email",ifnull(receipt_det.Updated_By_Email,""));
                 			payload.put("Updated_By_Time",updated_time_txt);
                 			// ==========================================
                 			// SYNCHRONIZE
                 			// ==========================================
                 			sync_resp = payment_management.syncPaymentDetailsFromMasakaSiteManagement(payload);
                 			if(sync_resp != null && ifnull(sync_resp.get("ok"),false) == true)
                 			{
                 				synced_count = synced_count + 1;
                 			}
                 			else
                 			{
                 				failed_count = failed_count + 1;
                 				error_row = Map();
                 				error_row.put("payment_receipt_detail_id",receipt_det.ID);
                 				error_row.put("voucher_number",ifnull(receipt_det.Payment_Receipt_Voucher.Payment_Receipt_Number,""));
                 				if(sync_resp != null)
                 				{
                 					error_row.put("message",ifnull(sync_resp.get("message"),"Unknown synchronization error."));
                 				}
                 				else
                 				{
                 					error_row.put("message","No response received from Payment Management.");
                 				}
                 				failure_details.add(error_row);
                 			}
                 		}		catch (sync_error)
                 		{
                 			failed_count = failed_count + 1;
                 			error_row = Map();
                 			error_row.put("payment_receipt_detail_id",receipt_det.ID);
                 			error_row.put("message",sync_error.toString());
                 			failure_details.add(error_row);
                 		}
                 	}
                 	result.put("ok",failed_count == 0);
                 	result.put("message","Payment Receipt Details backfill completed.");
                 	result.put("start_from",start_from);
                 	result.put("next_start",start_from + loaded_count);
                 	result.put("loaded",loaded_count);
                 	result.put("synced",synced_count);
                 	result.put("skipped_non_cash",skipped_non_cash);
                 	result.put("missing_voucher",missing_voucher_count);
                 	result.put("failed",failed_count);
                 	result.put("failure_details",failure_details);
                 	info result;
                 	return result;
                 }

map backfillPaymentReceiptVoucherTotals()
{
                 	result = Map();
                 	start_from = 0;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded_count = 0;
                 	updated_count = 0;
                 	failed_count = 0;
                 	failure_details = List();
                 	// Only process Unassigned Payment Receipt Vouchers
                 	for each  receipt in Payment_Receipt_Voucher[ID != 0 && Payment_Receipt_Voucher_Status == "Unassigned"] range from start_from to end_at
                 	{
                 		loaded_count = loaded_count + 1;
                 		try 
                 		{
                 			total_received = ifnull(receipt.Total_Amount_Received,0.0);
                 			// Keep existing charges (if they are entered on the header)
                 			total_charges = ifnull(receipt.Total_Charges,0.0);
                 			total_allocated = 0.0;
                 			for each  det in Payment_Receipt_Details[Payment_Receipt_Voucher == receipt.ID]
                 			{
                 				total_allocated = total_allocated + ifnull(det.Amount_Allocated,0.0);
                 			}
                 			total_not_allocated = total_received - total_charges - total_allocated;
                 			if(total_not_allocated < 0)
                 			{
                 				total_not_allocated = 0.0;
                 			}
                 			// Determine status
                 			new_status = "Assigned";
                 			if(total_allocated <= 0)
                 			{
                 				new_status = "Assigned";
                 			}
                 			else if(total_not_allocated > 0)
                 			{
                 				new_status = "Partially Assigned";
                 			}
                 			else
                 			{
                 				new_status = "Fully Assigned";
                 			}
                 			receipt.Total_Amount_Allocated=total_allocated;
                 			receipt.Total_Amount_Not_Allocated=total_not_allocated;
                 			receipt.Payment_Receipt_Voucher_Status=new_status;
                 			updated_count = updated_count + 1;
                 		}		catch (backfill_error)
                 		{
                 			failed_count = failed_count + 1;
                 			error_row = Map();
                 			error_row.put("payment_receipt_voucher_id",receipt.ID);
                 			error_row.put("payment_receipt_number",ifnull(receipt.Payment_Receipt_Number,""));
                 			error_row.put("message",backfill_error.toString());
                 			failure_details.add(error_row);
                 		}
                 	}
                 	result.put("ok",failed_count == 0);
                 	result.put("message","Unassigned Payment Receipt Voucher totals backfilled.");
                 	result.put("start_from",start_from);
                 	result.put("next_start",start_from + loaded_count);
                 	result.put("loaded",loaded_count);
                 	result.put("updated",updated_count);
                 	result.put("failed",failed_count);
                 	result.put("failure_details",failure_details);
                 	info result;
                 	return result;
                 }

map backfillSalesVoucherLookup()
{
                 	result = Map();
                 	start_from = 0;
                 	batch_size = 1000;
                 	end_at = start_from + batch_size - 1;
                 	loaded_count = 0;
                 	updated_count = 0;
                 	blank_reference_count = 0;
                 	not_found_count = 0;
                 	not_unpaid_count = 0;
                 	failed_count = 0;
                 	not_found_details = List();
                 	not_unpaid_details = List();
                 	failure_details = List();
                 	// Only load Sales Voucher rows whose lookup is empty
                 	for each  receipt_det in Payment_Receipt_Details[ID != 0 && Sales_Voucher == null && Payment_Document == "Sales Voucher"] range from start_from to end_at
                 	{
                 		loaded_count = loaded_count + 1;
                 		match_value = ifnull(receipt_det.Display_Name_Invoice_Voucher,"").trim();
                 		if(match_value == "")
                 		{
                 			blank_reference_count = blank_reference_count + 1;
                 			continue;
                 		}
                 		try 
                 		{
                 			sales_rec = Sales_Voucher[Sales_Voucher_Number == match_value];
                 			if(sales_rec.ID == null)
                 			{
                 				not_found_count = not_found_count + 1;
                 				not_found_row = Map();
                 				not_found_row.put("payment_receipt_detail_id",receipt_det.ID);
                 				not_found_row.put("sales_voucher_number",match_value);
                 				not_found_row.put("reason","Sales Voucher not found.");
                 				not_found_details.add(not_found_row);
                 				continue;
                 			}
                 			// Only backfill unpaid Sales Vouchers
                 			payment_status = ifnull(sales_rec.Payment_Status,"").trim();
                 			if(payment_status != "Draft" && payment_status != "Unpaid")
                 			{
                 				not_unpaid_count = not_unpaid_count + 1;
                 				status_row = Map();
                 				status_row.put("payment_receipt_detail_id",receipt_det.ID);
                 				status_row.put("sales_voucher_number",match_value);
                 				status_row.put("payment_status",payment_status);
                 				status_row.put("reason","Sales Voucher is not Unpaid.");
                 				not_unpaid_details.add(status_row);
                 				continue;
                 			}
                 			// Fill the empty lookup
                 			receipt_det.Sales_Voucher=sales_rec.ID;
                 			// Copy Sales Voucher details
                 			receipt_det.Payment_Document="Sales Voucher";
                 			receipt_det.Display_Name_Invoice_Voucher=ifnull(sales_rec.Sales_Voucher_Number,"");
                 			receipt_det.Customer=ifnull(sales_rec.Display_Name_Customer,"");
                 			receipt_det.Amount_Due=ifnull(sales_rec.Balance_Due,0.0);
                 			calculated_balance = ifnull(receipt_det.Amount_Due,0.0) - ifnull(receipt_det.Amount_Allocated,0.0);
                 			if(calculated_balance < 0)
                 			{
                 				calculated_balance = 0.0;
                 			}
                 			receipt_det.Balance_Due=calculated_balance;
                 			// Copy Delivery Note only when required
                 			if(sales_rec.Customer != null && sales_rec.Customer.Delivery_Note_Required == true)
                 			{
                 				receipt_det.Delivery_Note=sales_rec.Delivery_Note;
                 			}
                 			else
                 			{
                 				receipt_det.Delivery_Note=null;
                 			}
                 			updated_count = updated_count + 1;
                 		}		catch (backfill_error)
                 		{
                 			failed_count = failed_count + 1;
                 			error_row = Map();
                 			error_row.put("payment_receipt_detail_id",receipt_det.ID);
                 			error_row.put("sales_voucher_number",match_value);
                 			error_row.put("message",backfill_error.toString());
                 			failure_details.add(error_row);
                 		}
                 	}
                 	result.put("ok",failed_count == 0);
                 	result.put("message","Empty unpaid Sales Voucher lookups backfilled.");
                 	result.put("start_from",start_from);
                 	result.put("next_start",start_from + loaded_count);
                 	result.put("loaded",loaded_count);
                 	result.put("updated",updated_count);
                 	result.put("blank_reference",blank_reference_count);
                 	result.put("not_found",not_found_count);
                 	result.put("not_unpaid",not_unpaid_count);
                 	result.put("failed",failed_count);
                 	result.put("not_found_details",not_found_details);
                 	result.put("not_unpaid_details",not_unpaid_details);
                 	result.put("failure_details",failure_details);
                 	info result;
                 	return result;
                 }

map backfillTruckMovementServiceProcessingBatch()
{
                 	result = Map();
                 	// =====================================================
                 	// CHANGE THIS FOR EACH BATCH
                 	// 0, 500, 1000, 1500...
                 	// =====================================================
                 	start_from = 0;
                 	batch_size = 500;
                 	end_at = start_from + batch_size - 1;
                 	loaded = 0;
                 	processed = 0;
                 	skipped = 0;
                 	failed = 0;
                 	piece_rate_processed = 0;
                 	piece_rate_rows_updated = 0;
                 	piece_rate_bill_missing = 0;
                 	weigh_bridge_processed = 0;
                 	weigh_bridge_failed = 0;
                 	weigh_bridge_skipped = 0;
                 	labour_processed = 0;
                 	labour_failed = 0;
                 	descriptions_updated = 0;
                 	bills_recalculated = 0;
                 	failed_details = List();
                 	// =====================================================
                 	// GET HAMID ONCE FOR THIS BATCH
                 	// =====================================================
                 	hamid_employee_id = null;
                 	hamid_result = employee_management.employee.get_employee_by_display_name("Hamid Ssenoga - 50");
                 	if(hamid_result != null && ifnull(hamid_result.get("ok"),false) == true && hamid_result.get("employee_id") != null)
                 	{
                 		hamid_employee_id = hamid_result.get("employee_id");
                 	}
                 	// =====================================================
                 	// LOAD TRUCK MOVEMENT VOUCHERS
                 	// =====================================================
                 	for each  rec in Truck_Movement_Voucher[Truck_Movement_Voucher_Status == "Delivered" || Truck_Movement_Voucher_Status == "Completed"] sort by ID asc range from start_from to end_at
                 	{
                 		loaded = loaded + 1;
                 		record_ready = false;
                 		record_failed = false;
                 		try 
                 		{
                 			// =================================================
                 			// A. BASIC VALUES
                 			// =================================================
                 			movement_date = zoho.currentdate;
                 			if(rec.Time_Start != null)
                 			{
                 				movement_date = rec.Time_Start.toDate();
                 			}
                 			employee_display = ifnull(rec.Display_Name_Employee,"").trim();
                 			movement_display = ifnull(rec.Display_Name_Voucher,"").trim();
                 			truck_movement_display = movement_display;
                 			if(rec.Line_Number != null)
                 			{
                 				if(truck_movement_display != "")
                 				{
                 					truck_movement_display = truck_movement_display + " - " + rec.Line_Number.toString();
                 				}
                 				else
                 				{
                 					truck_movement_display = rec.Line_Number.toString();
                 				}
                 			}
                 			// =================================================
                 			// B. DETECT SERVICES
                 			// =================================================
                 			has_piece_rate = false;
                 			has_weigh_bridge = false;
                 			for each  srv in rec.Services
                 			{
                 				if(srv.Service != null)
                 				{
                 					service_name = ifnull(srv.Service.Service_Name,"").trim();
                 					if(service_name == "Employee Piece Rate")
                 					{
                 						has_piece_rate = true;
                 					}
                 					if(service_name == "Weigh Bridge")
                 					{
                 						has_weigh_bridge = true;
                 					}
                 				}
                 			}
                 			// =================================================
                 			// C. EMPLOYEE PIECE RATE
                 			// =================================================
                 			if(has_piece_rate == true && rec.Voucher != null && rec.Voucher.Employee != null)
                 			{
                 				employee_id = rec.Voucher.Employee.ID;
                 				// =============================================
                 				// WEEK NUMBER
                 				// =============================================
                 				day_number = movement_date.getDayOfWeek();
                 				if(day_number == 1)
                 				{
                 					days_to_monday = -6;
                 				}
                 				else
                 				{
                 					days_to_monday = 2 - day_number;
                 				}
                 				week_date = movement_date.addDay(days_to_monday);
                 				week_number = week_date.getWeekOfYear();
                 				week_text = week_number.toString();
                 				if(week_number < 10)
                 				{
                 					week_text = "0" + week_text;
                 				}
                 				weekly_bill_number = week_date.getYear().toString() + " Week " + week_text;
                 				// =============================================
                 				// FIND EXISTING WEEKLY EMPLOYEE BILL
                 				// =============================================
                 				employee_weekly_bill = Bill[Employee_Vendor == employee_id && Bill_Number == weekly_bill_number && Bill_Type == "Employee Bill"];
                 				if(employee_weekly_bill.ID == null)
                 				{
                 					piece_rate_bill_missing = piece_rate_bill_missing + 1;
                 					record_failed = true;
                 					fail_map = Map();
                 					fail_map.put("Truck_Movement_Voucher_ID",rec.ID);
                 					fail_map.put("Voucher",truck_movement_display);
                 					fail_map.put("Reason","Employee Piece Rate weekly bill not found: " + weekly_bill_number);
                 					failed_details.add(fail_map);
                 				}
                 				else
                 				{
                 					piece_rate_rows = 0;
                 					// =========================================
                 					// LINK PIECE RATE SERVICE ROWS
                 					// =========================================
                 					for each  srv in rec.Services
                 					{
                 						if(srv.Service != null && ifnull(srv.Service.Service_Name,"").trim() == "Employee Piece Rate")
                 						{
                 							current_amount = round(ifnull(srv.Line_Total,0.0),2);
                 							srv.Bill=employee_weekly_bill.ID;
                 							srv.Display_Name_Bill=employee_display + " - " + weekly_bill_number;
                 							srv.Truck_Movement_Voucher=rec.ID;
                 							srv.Display_Name_Voucher=truck_movement_display;
                 							srv.Last_Synced_Group_ID=employee_weekly_bill.ID;
                 							srv.Last_Synced_Group_Amount=current_amount;
                 							piece_rate_rows = piece_rate_rows + 1;
                 							piece_rate_rows_updated = piece_rate_rows_updated + 1;
                 						}
                 					}
                 					if(piece_rate_rows > 0)
                 					{
                 						piece_rate_processed = piece_rate_processed + 1;
                 						record_ready = true;
                 					}
                 				}
                 			}
                 			// =================================================
                 			// D. WEIGH BRIDGE
                 			// =================================================
                 			if(has_weigh_bridge == true)
                 			{
                 				truck_plate = ifnull(rec.Number_Plate_Truck_Register,"").trim();
                 				if(rec.Time_Start == null)
                 				{
                 					weigh_bridge_failed = weigh_bridge_failed + 1;
                 					record_failed = true;
                 					fail_map = Map();
                 					fail_map.put("Truck_Movement_Voucher_ID",rec.ID);
                 					fail_map.put("Voucher",truck_movement_display);
                 					fail_map.put("Reason","Weigh Bridge failed: Time Start is empty.");
                 					failed_details.add(fail_map);
                 				}
                 				else if(truck_plate == "")
                 				{
                 					weigh_bridge_failed = weigh_bridge_failed + 1;
                 					record_failed = true;
                 					fail_map = Map();
                 					fail_map.put("Truck_Movement_Voucher_ID",rec.ID);
                 					fail_map.put("Voucher",truck_movement_display);
                 					fail_map.put("Reason","Weigh Bridge failed: Truck Number Plate is empty.");
                 					failed_details.add(fail_map);
                 				}
                 				else if(hamid_employee_id == null)
                 				{
                 					weigh_bridge_failed = weigh_bridge_failed + 1;
                 					record_failed = true;
                 					fail_map = Map();
                 					fail_map.put("Truck_Movement_Voucher_ID",rec.ID);
                 					fail_map.put("Voucher",truck_movement_display);
                 					fail_map.put("Reason","Hamid Ssenoga - 50 was not found.");
                 					failed_details.add(fail_map);
                 				}
                 				else
                 				{
                 					weigh_bridge_result = thisapp.services.recalculate_weekly_weigh_bridge(hamid_employee_id,rec.Time_Start.toDate(),truck_plate);
                 					info weigh_bridge_result;
                 					if(weigh_bridge_result != null && ifnull(weigh_bridge_result.get("ok"),false) == true)
                 					{
                 						weigh_bridge_processed = weigh_bridge_processed + 1;
                 						record_ready = true;
                 					}
                 					else
                 					{
                 						weigh_bridge_failed = weigh_bridge_failed + 1;
                 						record_failed = true;
                 						fail_map = Map();
                 						fail_map.put("Truck_Movement_Voucher_ID",rec.ID);
                 						fail_map.put("Voucher",truck_movement_display);
                 						if(weigh_bridge_result != null)
                 						{
                 							fail_map.put("Reason","Weigh Bridge recalculation failed: " + ifnull(weigh_bridge_result.get("message"),ifnull(weigh_bridge_result.get("msg"),"Unknown error")));
                 						}
                 						else
                 						{
                 							fail_map.put("Reason","Weigh Bridge recalculation returned null.");
                 						}
                 						failed_details.add(fail_map);
                 					}
                 				}
                 			}
                 			else
                 			{
                 				weigh_bridge_skipped = weigh_bridge_skipped + 1;
                 			}
                 			// =================================================
                 			// E. LABOUR RECALCULATION
                 			// =================================================
                 			if(rec.Voucher != null && rec.Voucher.Employee != null)
                 			{
                 				work_date = zoho.currentdate;
                 				if(rec.Time_Start != null)
                 				{
                 					work_date = rec.Time_Start.toDate();
                 				}
                 				employee_display_name = ifnull(rec.Display_Name_Employee,"").trim();
                 				labour_result = thisapp.labour.recalculate_truck_movement_labour(rec.Voucher.Employee.ID,employee_display_name,work_date);
                 				info labour_result;
                 				if(labour_result != null && ifnull(labour_result.get("ok"),false) == true)
                 				{
                 					labour_processed = labour_processed + 1;
                 					record_ready = true;
                 				}
                 				else
                 				{
                 					labour_failed = labour_failed + 1;
                 					record_failed = true;
                 					fail_map = Map();
                 					fail_map.put("Truck_Movement_Voucher_ID",rec.ID);
                 					fail_map.put("Voucher",truck_movement_display);
                 					if(labour_result != null)
                 					{
                 						fail_map.put("Reason","Labour recalculation failed: " + ifnull(labour_result.get("message"),ifnull(labour_result.get("msg"),"Unknown error")));
                 					}
                 					else
                 					{
                 						fail_map.put("Reason","Labour recalculation returned null.");
                 					}
                 					failed_details.add(fail_map);
                 				}
                 			}
                 			// =================================================
                 			// F. BUILD DESCRIPTION FOR ALL SERVICE DETAILS
                 			// =================================================
                 			truck_plate = ifnull(rec.Number_Plate_Truck_Register,"").trim();
                 			employee_display = ifnull(rec.Display_Name_Employee,"").trim();
                 			pickup_from = ifnull(rec.Pick_Up_From,"").trim();
                 			delivery_to = ifnull(rec.Delivery_To,"").trim();
                 			job_display = "";
                 			if(rec.Job != null)
                 			{
                 				job_name_text = ifnull(rec.Job.Job_Name,"").trim();
                 				job_number_text = ifnull(rec.Job.Job_No,"").trim();
                 				if(job_name_text != "")
                 				{
                 					job_display = job_name_text;
                 				}
                 				else
                 				{
                 					job_display = job_number_text;
                 				}
                 			}
                 			for each  srv in rec.Services
                 			{
                 				if(srv.Service != null)
                 				{
                 					description_text = "";
                 					if(movement_display != "")
                 					{
                 						description_text = "Truck Movement Voucher: " + movement_display;
                 					}
                 					else
                 					{
                 						description_text = "Truck Movement Voucher: " + rec.ID.toString();
                 					}
                 					if(rec.Line_Number != null)
                 					{
                 						description_text = description_text + "\nMovement Line Number: " + rec.Line_Number.toString();
                 					}
                 					description_text = description_text + "\nMovement Date: " + movement_date.toString("dd-MMM-yyyy");
                 					if(job_display != "")
                 					{
                 						description_text = description_text + "\nJob: " + job_display;
                 					}
                 					if(truck_plate != "")
                 					{
                 						description_text = description_text + "\nTruck Number Plate: " + truck_plate;
                 					}
                 					if(employee_display != "")
                 					{
                 						description_text = description_text + "\nEmployee: " + employee_display;
                 					}
                 					if(pickup_from != "")
                 					{
                 						description_text = description_text + "\nPick Up From: " + pickup_from;
                 					}
                 					if(delivery_to != "")
                 					{
                 						description_text = description_text + "\nDelivery To: " + delivery_to;
                 					}
                 					srv.Description=description_text;
                 					descriptions_updated = descriptions_updated + 1;
                 					record_ready = true;
                 				}
                 			}
                 			// =================================================
                 			// G. COLLECT ALL BILLS LINKED TO THESE SERVICES
                 			// =================================================
                 			bill_ids_to_recalculate = List();
                 			for each  srv in rec.Services
                 			{
                 				if(srv.Bill != null)
                 				{
                 					bill_id = srv.Bill.ID;
                 					if(!bill_ids_to_recalculate.contains(bill_id))
                 					{
                 						bill_ids_to_recalculate.add(bill_id);
                 					}
                 				}
                 			}
                 			// =================================================
                 			// H. RECALCULATE BILL TOTAL FROM ACTUAL DETAILS
                 			// =================================================
                 			for each  bill_id in bill_ids_to_recalculate
                 			{
                 				service_total = 0.0;
                 				bill_detail_total = 0.0;
                 				// =============================================
                 				// SERVICE DETAILS
                 				// =============================================
                 				service_rows = Service_Details[Bill == bill_id];
                 				for each  sd in service_rows
                 				{
                 					service_total = service_total + round(ifnull(sd.Line_Total,0.0),2);
                 				}
                 				service_total = round(service_total,2);
                 				// =============================================
                 				// BILL DETAILS
                 				// =============================================
                 				bill_detail_rows = Bill_Details[Bill == bill_id];
                 				for each  bd in bill_detail_rows
                 				{
                 					bill_detail_total = bill_detail_total + round(ifnull(bd.Line_Total,0.0),2);
                 				}
                 				bill_detail_total = round(bill_detail_total,2);
                 				// =============================================
                 				// GRAND TOTAL
                 				// =============================================
                 				grand_bill_total = round(service_total + bill_detail_total,2);
                 				// =============================================
                 				// UPDATE BILL HEADER
                 				// =============================================
                 				bill_rec = Bill[ID == bill_id];
                 				if(bill_rec.ID != null)
                 				{
                 					bill_rec.Services_Total=service_total;
                 					bill_rec.Bill_Total=grand_bill_total;
                 					bill_rec.Total_Amount=grand_bill_total;
                 					bill_rec.Amount_Due=grand_bill_total;
                 					amount_paid = ifnull(bill_rec.Amount_Paid,0.0);
                 					new_balance = grand_bill_total - amount_paid;
                 					if(new_balance < 0)
                 					{
                 						new_balance = 0.0;
                 					}
                 					bill_rec.Balance_Due=round(new_balance,2);
                 					if(amount_paid <= 0)
                 					{
                 						bill_rec.Payment_Status="Not Paid";
                 					}
                 					else if(new_balance <= 0)
                 					{
                 						bill_rec.Payment_Status="Paid";
                 					}
                 					else
                 					{
                 						bill_rec.Payment_Status="Partially Paid";
                 					}
                 					bills_recalculated = bills_recalculated + 1;
                 				}
                 			}
                 			// =================================================
                 			// I. RESULT FOR RECORD
                 			// =================================================
                 			if(record_failed == true)
                 			{
                 				failed = failed + 1;
                 			}
                 			if(record_ready == true)
                 			{
                 				processed = processed + 1;
                 			}
                 			else if(record_failed == false)
                 			{
                 				skipped = skipped + 1;
                 			}
                 		}		catch (e)
                 		{
                 			failed = failed + 1;
                 			fail_map = Map();
                 			fail_map.put("Truck_Movement_Voucher_ID",rec.ID);
                 			fail_map.put("Voucher",ifnull(rec.Display_Name_Voucher,""));
                 			fail_map.put("Reason",e.toString());
                 			failed_details.add(fail_map);
                 		}
                 	}
                 	// =====================================================
                 	// BATCH RESULT
                 	// =====================================================
                 	result.put("start_from",start_from);
                 	result.put("end_at",end_at);
                 	result.put("batch_size",batch_size);
                 	result.put("loaded",loaded);
                 	result.put("processed",processed);
                 	result.put("skipped",skipped);
                 	result.put("failed",failed);
                 	result.put("piece_rate_processed",piece_rate_processed);
                 	result.put("piece_rate_rows_updated",piece_rate_rows_updated);
                 	result.put("piece_rate_bill_missing",piece_rate_bill_missing);
                 	result.put("weigh_bridge_processed",weigh_bridge_processed);
                 	result.put("weigh_bridge_failed",weigh_bridge_failed);
                 	result.put("weigh_bridge_skipped",weigh_bridge_skipped);
                 	result.put("labour_processed",labour_processed);
                 	result.put("labour_failed",labour_failed);
                 	result.put("descriptions_updated",descriptions_updated);
                 	result.put("bills_recalculated",bills_recalculated);
                 	result.put("failed_details",failed_details);
                 	if(loaded < batch_size)
                 	{
                 		result.put("last_batch",true);
                 	}
                 	else
                 	{
                 		result.put("last_batch",false);
                 	}
                 	info result;
                 	return result;
                 }

void backfill_display_name_bill()
{
                 	updated_count = 0;
                 	skipped_count = 0;
                 	records = Payment_Made_Details[Bill != null];
                 	for each  rec in records
                 	{
                 		bill_name = ifnull(rec.Bill.Bill_Name,"").trim();
                 		bill_number = ifnull(rec.Bill.Bill_Number,"").trim();
                 		new_display_name = "";
                 		if(bill_name != "" && bill_number != "")
                 		{
                 			new_display_name = bill_name + " - " + bill_number;
                 		}
                 		else if(bill_name != "")
                 		{
                 			new_display_name = bill_name;
                 		}
                 		else if(bill_number != "")
                 		{
                 			new_display_name = bill_number;
                 		}
                 		if(ifnull(rec.Display_Name_Bill,"").trim() != new_display_name)
                 		{
                 			rec.Display_Name_Bill=new_display_name;
                 			updated_count = updated_count + 1;
                 		}
                 		else
                 		{
                 			skipped_count = skipped_count + 1;
                 		}
                 	}
                 	info "Backfill completed.";
                 	info "Updated: " + updated_count;
                 	info "Already correct: " + skipped_count;
                 }

map backfill_missing_credit_sales_invoice_details()
{
                 	result = Map();
                 	failed_records = List();
                 	skipped_records = List();
                 	processed_count = 0;
                 	generated_voucher_count = 0;
                 	generated_line_count = 0;
                 	already_existing_count = 0;
                 	skipped_count = 0;
                 	failed_count = 0;
                 	target_site = "Gomba Site - ARA075";
                 	batch_size = 500;
                 	/*
                 	 * Count Invoice Details already created for eligible
                 	 * Gomba Site Sand Sales vouchers.
                 	 */
                 	existing_invoice_count = Invoice_Details[Source_Form == "Sales Voucher" && Sales_Voucher.Sales_Type == "Sand Sales" && Sales_Voucher.Display_Name_Site == target_site].count();
                 	start_index = existing_invoice_count + 1;
                 	end_index = start_index + batch_size - 1;
                 	/*
                 	 * Select only eligible Payment Receipt Details records.
                 	 *
                 	 * A Credit Note and Sales Voucher must both be present.
                 	 */
                 	payment_receipt_batch = Payment_Receipt_Details[Payment_Type == "Credit" && Payment_Document == "Sales Voucher" && Sales_Voucher != null && Credit_Note_Voucher != null && Sales_Voucher.Sales_Type == "Sand Sales" && Sales_Voucher.Display_Name_Site == target_site] sort by ID range from start_index to end_index;
                 	for each  payment_record in payment_receipt_batch
                 	{
                 		processed_count = processed_count + 1;
                 		try 
                 		{
                 			sales_voucher_id = payment_record.Sales_Voucher.ID;
                 			voucher_reference = ifnull(payment_record.Sales_Voucher.Sales_Voucher_Number,sales_voucher_id.toString());
                 			/*
                 			 * If this Sales Voucher is already found in
                 			 * Invoice Details, do not create it again.
                 			 */
                 			existing_invoice = Invoice_Details[Source_Record_ID == sales_voucher_id && Source_Form == "Sales Voucher"];
                 			if(existing_invoice.count() > 0)
                 			{
                 				already_existing_count = already_existing_count + 1;
                 			}
                 			else
                 			{
                 				sv2 = Sales_Voucher[ID == sales_voucher_id];
                 				if(sv2.ID == null)
                 				{
                 					skipped_count = skipped_count + 1;
                 					skipped_records.add("Payment Receipt Details record " + payment_record.ID.toString() + " skipped. Sales Voucher was not found.");
                 				}
                 				else
                 				{
                 					credit_note_no = "";
                 					if(payment_record.Credit_Note_Voucher != null)
                 					{
                 						credit_note_no = ifnull(payment_record.Credit_Note_Voucher.Credit_Note_Number,"");
                 					}
                 					/*
                 					 * Do not create Invoice Details without an
                 					 * actual Credit Note number.
                 					 */
                 					if(credit_note_no == "")
                 					{
                 						skipped_count = skipped_count + 1;
                 						skipped_records.add("Sales Voucher " + voucher_reference + " skipped. Credit Note number is empty.");
                 					}
                 					else
                 					{
                 						delivery_note_no = "";
                 						if(sv2.Delivery_Note != null)
                 						{
                 							delivery_note_no = ifnull(sv2.Delivery_Note.Delivery_Note_Number,"");
                 						}
                 						number_plate_text = ifnull(sv2.Display_Name_Number_Plate,"");
                 						voucher_date_text = "";
                 						if(sv2.Sales_Voucher_Date != null)
                 						{
                 							voucher_date_text = sv2.Sales_Voucher_Date.toString("dd-MMM-yyyy");
                 						}
                 						line_no = 1;
                 						product_count = 0;
                 						lines_created_for_voucher = 0;
                 						for each  p in sv2.Product_Details
                 						{
                 							product_count = product_count + 1;
                 							/*
                 							 * Additional line-level protection.
                 							 */
                 							existing_line = Invoice_Details[Source_Record_ID == sv2.ID && Source_Form == "Sales Voucher" && Line_Number == line_no];
                 							if(existing_line.count() == 0)
                 							{
                 								item_text = "Number Plate: " + number_plate_text + "\nItem: " + ifnull(p.Display_Name_Item,"") + "\nQuantity: " + ifnull(p.Quantity,0).toString() + "\nUnit Of Measure: " + ifnull(p.Display_Name_Base_Unit_Of_Measure,"");
                 								details_text = "Sales Voucher Number: " + ifnull(sv2.Sales_Voucher_Number,"") + "\nSales Voucher Date: " + voucher_date_text + "\nCustomer: " + ifnull(sv2.Display_Name_Customer,"") + "\nCredit Note: " + credit_note_no;
                 								if(delivery_note_no != "")
                 								{
                 									details_text = details_text + "\nDelivery Note: " + delivery_note_no;
                 								}
                 								new_invoice_detail_id = insert into Invoice_Details
                 								[
                 									Sales_Voucher=sv2.ID
                 									Display_Name_Voucher=ifnull(sv2.Sales_Voucher_Number,"")
                 									Details_Date=zoho.currentdate
                 									Line_Number=line_no
                 									Item=item_text
                 									Details=details_text
                 									Quantity=1
                 									Site=sv2.Display_Name_Site
                 									Account=sv2.Display_Name_Site
                 									Source_Record_ID=sv2.ID
                 									Source_Form="Sales Voucher"
                 									Invoice_Details_Status="Draft"
                 									Added_User=zoho.loginuser
                 								];
                 								if(new_invoice_detail_id != null)
                 								{
                 									generated_line_count = generated_line_count + 1;
                 									lines_created_for_voucher = lines_created_for_voucher + 1;
                 								}
                 								else
                 								{
                 									failed_count = failed_count + 1;
                 									failed_records.add("Sales Voucher " + voucher_reference + ", line " + line_no.toString() + ": insert returned no ID.");
                 								}
                 							}
                 							line_no = line_no + 1;
                 						}
                 						if(lines_created_for_voucher > 0)
                 						{
                 							generated_voucher_count = generated_voucher_count + 1;
                 						}
                 						else if(product_count == 0)
                 						{
                 							skipped_count = skipped_count + 1;
                 							skipped_records.add("Sales Voucher " + voucher_reference + " skipped. No Product Details were found.");
                 						}
                 					}
                 				}
                 			}
                 		}		catch (e)
                 		{
                 			failed_count = failed_count + 1;
                 			failed_records.add("Payment Receipt Details record " + payment_record.ID.toString() + ": " + e.toString());
                 		}
                 	}
                 	/*
                 	 * Count the total eligible Payment Receipt Details records.
                 	 */
                 	total_eligible_payment_records = Payment_Receipt_Details[Payment_Type == "Credit" && Payment_Document == "Sales Voucher" && Sales_Voucher != null && Credit_Note_Voucher != null && Sales_Voucher.Sales_Type == "Sand Sales" && Sales_Voucher.Display_Name_Site == target_site].count();
                 	/*
                 	 * This is informational only.
                 	 *
                 	 * Do not use this count to calculate remaining payment
                 	 * records because several payment records may point to
                 	 * Sales Vouchers already represented in Invoice Details.
                 	 */
                 	updated_invoice_count = Invoice_Details[Source_Form == "Sales Voucher" && Sales_Voucher.Sales_Type == "Sand Sales" && Sales_Voucher.Display_Name_Site == target_site].count();
                 	/*
                 	 * Calculate how far the Payment Receipt Details report
                 	 * has been scanned.
                 	 */
                 	scanned_through_index = end_index;
                 	if(scanned_through_index > total_eligible_payment_records)
                 	{
                 		scanned_through_index = total_eligible_payment_records;
                 	}
                 	/*
                 	 * Calculate unscanned Payment Receipt Details positions.
                 	 */
                 	remaining_count = total_eligible_payment_records - scanned_through_index;
                 	if(remaining_count < 0)
                 	{
                 		remaining_count = 0;
                 	}
                 	has_more = remaining_count > 0;
                 	result.put("ok",failed_count == 0);
                 	result.put("site",target_site);
                 	result.put("batch_size",batch_size);
                 	result.put("start_index",start_index);
                 	result.put("end_index",end_index);
                 	result.put("scanned_through_index",scanned_through_index);
                 	result.put("processed_count",processed_count);
                 	result.put("generated_voucher_count",generated_voucher_count);
                 	result.put("generated_line_count",generated_line_count);
                 	result.put("already_existing_count",already_existing_count);
                 	result.put("skipped_count",skipped_count);
                 	result.put("failed_count",failed_count);
                 	result.put("total_eligible_payment_records",total_eligible_payment_records);
                 	result.put("existing_invoice_count",updated_invoice_count);
                 	result.put("remaining_count",remaining_count);
                 	result.put("has_more",has_more);
                 	result.put("skipped_records",skipped_records);
                 	result.put("failed_records",failed_records);
                 	if(failed_count > 0)
                 	{
                 		result.put("message","Backfill batch completed with failures. Review failed_records.");
                 	}
                 	else if(skipped_count > 0)
                 	{
                 		result.put("message","Backfill batch completed. Some records were skipped.");
                 	}
                 	else if(has_more == true)
                 	{
                 		result.put("message","Backfill batch completed successfully. Execute the function again.");
                 	}
                 	else
                 	{
                 		result.put("message","Backfill completed. All eligible Gomba Site credit Sales Vouchers were checked.");
                 	}
                 	info result;
                 	return result;
                 }

map backfill_sales_voucher_stock_fields()
{
                 	result = Map();
                 	failed_records = List();
                 	processed_count = 0;
                 	updated_count = 0;
                 	failed_count = 0;
                 	// Fully populated reference voucher: FA705
                 	reference_voucher_id = 4273992000008395147;
                 	reference_voucher = Sales_Voucher[ID == reference_voucher_id];
                 	if(reference_voucher.ID == null)
                 	{
                 		result.put("ok",false);
                 		result.put("message","Reference Sales Voucher FA705 was not found.");
                 		return result;
                 	}
                 	if(reference_voucher.Item == null || reference_voucher.Unit_Of_Measure == null || reference_voucher.Store == null || reference_voucher.Store_Item_Stock == null)
                 	{
                 		result.put("ok",false);
                 		result.put("message","FA705 is missing Item, Unit Of Measure, Store, or Store Item Stock.");
                 		return result;
                 	}
                 	// Sales Voucher.Item is a Product Price Register lookup.
                 	reference_product_price_id = reference_voucher.Item;
                 	// Store Item Stock.Item is the actual Items Register lookup required
                 	// by Store Management stock functions.
                 	reference_stock_item_id = reference_voucher.Store_Item_Stock.Item;
                 	reference_uom_id = reference_voucher.Unit_Of_Measure;
                 	reference_store_id = reference_voucher.Store;
                 	reference_display_item = ifnull(reference_voucher.Display_Name_Item,"Washed Sand - BMT-0016");
                 	reference_display_uom = ifnull(reference_voucher.Display_Name_Unit_Of_Measure,"Cubic meters");
                 	reference_display_store = ifnull(reference_voucher.Display_Name_Store,"Gomba Drager Area 1 Sand Pit A - ARB861");
                 	if(reference_stock_item_id == null)
                 	{
                 		result.put("ok",false);
                 		result.put("message","FA705 Store Item Stock does not contain an Item lookup.");
                 		return result;
                 	}
                 	ledger_cache = Map();
                 	quantity_cache = Map();
                 	// Process 200 incomplete vouchers per execution.
                 	target_vouchers = Sales_Voucher[Sales_Type == "Sand Sales" && Item == null || Unit_Of_Measure == null || Store_Item_Stock == null || Store == null || Quantity_Available == null || Display_Name_Item == "" || Display_Name_Unit_Of_Measure == "" || Display_Name_Store == ""] sort by ID range from 1 to 500;
                 	for each  sales_voucher in target_vouchers
                 	{
                 		processed_count = processed_count + 1;
                 		try 
                 		{
                 			record_changed = false;
                 			// -------------------------------------------------
                 			// 1. PRODUCT PRICE REGISTER ITEM
                 			// -------------------------------------------------
                 			if(sales_voucher.Item == null)
                 			{
                 				sales_voucher.Item=reference_product_price_id;
                 				record_changed = true;
                 			}
                 			if(ifnull(sales_voucher.Display_Name_Item,"").trim() == "")
                 			{
                 				sales_voucher.Display_Name_Item=reference_display_item;
                 				record_changed = true;
                 			}
                 			// -------------------------------------------------
                 			// 2. UNIT OF MEASURE
                 			// -------------------------------------------------
                 			if(sales_voucher.Unit_Of_Measure == null)
                 			{
                 				sales_voucher.Unit_Of_Measure=reference_uom_id;
                 				record_changed = true;
                 			}
                 			if(ifnull(sales_voucher.Display_Name_Unit_Of_Measure,"").trim() == "")
                 			{
                 				sales_voucher.Display_Name_Unit_Of_Measure=reference_display_uom;
                 				record_changed = true;
                 			}
                 			// -------------------------------------------------
                 			// 3. STORE
                 			// Preserve Clean Sand Pit or any existing Store.
                 			// Only blank stores receive the FA705 store.
                 			// -------------------------------------------------
                 			store_id = sales_voucher.Store;
                 			if(store_id == null)
                 			{
                 				store_id = reference_store_id;
                 				sales_voucher.Store=store_id;
                 				record_changed = true;
                 			}
                 			if(ifnull(sales_voucher.Display_Name_Store,"").trim() == "")
                 			{
                 				sales_voucher.Display_Name_Store=reference_display_store;
                 				record_changed = true;
                 			}
                 			// -------------------------------------------------
                 			// 4. STORE ITEM STOCK AND AVAILABLE QUANTITY
                 			// -------------------------------------------------
                 			if(reference_stock_item_id != null && store_id != null)
                 			{
                 				cache_key = reference_stock_item_id.toString() + "|" + store_id.toString();
                 				// Resolve the correct ledger for the voucher's Store.
                 				if(sales_voucher.Store_Item_Stock == null)
                 				{
                 					ledger_id = ledger_cache.get(cache_key);
                 					if(ledger_id == null)
                 					{
                 						ledger_id = store_management.get_or_create_store_item_stock(reference_stock_item_id,store_id,"New");
                 						if(ledger_id != null)
                 						{
                 							ledger_cache.put(cache_key,ledger_id);
                 						}
                 					}
                 					if(ledger_id == null)
                 					{
                 						throw "No Store Item Stock found for Item " + reference_stock_item_id.toString() + " and Store " + store_id.toString() + ".";
                 					}
                 					sales_voucher.Store_Item_Stock=ledger_id;
                 					record_changed = true;
                 				}
                 				// Fill Quantity Available only when blank.
                 				if(sales_voucher.Quantity_Available == null)
                 				{
                 					quantity_available = quantity_cache.get(cache_key);
                 					if(quantity_available == null)
                 					{
                 						stock_summary = store_management.stock.get_stock_summary(reference_stock_item_id,store_id,"New");
                 						quantity_available = ifnull(stock_summary.get("store_stock"),0.0);
                 						quantity_cache.put(cache_key,quantity_available);
                 					}
                 					sales_voucher.Quantity_Available=quantity_available;
                 					record_changed = true;
                 				}
                 			}
                 			if(record_changed == true)
                 			{
                 				updated_count = updated_count + 1;
                 			}
                 		}		catch (e)
                 		{
                 			failed_count = failed_count + 1;
                 			failed_records.add("ID " + sales_voucher.ID.toString() + ": " + e.toString());
                 		}
                 	}
                 	remaining_count = Sales_Voucher[Sales_Type == "Sand Sales" && Item == null || Unit_Of_Measure == null || Store_Item_Stock == null || Store == null || Quantity_Available == null || Display_Name_Item == "" || Display_Name_Unit_Of_Measure == "" || Display_Name_Store == ""].count();
                 	result.put("ok",failed_count == 0);
                 	result.put("processed_count",processed_count);
                 	result.put("updated_count",updated_count);
                 	result.put("failed_count",failed_count);
                 	result.put("remaining_count",remaining_count);
                 	result.put("failed_records",failed_records);
                 	if(remaining_count == 0)
                 	{
                 		result.put("message","Backfill completed. No incomplete Sand Sales vouchers remain.");
                 	}
                 	else
                 	{
                 		result.put("message","Batch completed. Run the function again.");
                 	}
                 	info result;
                 	return result;
                 }

void create_asset_issue_from_asset_management_payload(map payload)
{
                 	info "Masaka Sites payload received: " + payload;
                 	source_id = payload.get("Source_Record_ID");
                 	if(source_id == null)
                 	{
                 		info "Masaka Sites sync stopped: Source_Record_ID is null";
                 		return;
                 	}
                 	source_id = source_id.toLong();
                 	existing = Asset_Issues[Source_Record_ID == source_id && Source_Form == "Asset Management Asset Issues"];
                 	if(existing.count() > 0)
                 	{
                 		info "Masaka Sites sync skipped: issue already exists for Source_Record_ID " + source_id;
                 		return;
                 	}
                 	insert into Asset_Issues
                 	[
                 		Source_Record_ID=source_id
                 		Source_Form="Asset Management Asset Issues"
                 		Issue_Number=payload.get("Issue_Number")
                 		Asset=payload.get("Asset")
                 		Display_Name_Asset=payload.get("Display_Name_Asset")
                 		Current_Site=payload.get("Current_Site")
                 		Current_Custodian=payload.get("Current_Custodian")
                 		Odometer_Reading=payload.get("Odometer_Reading")
                 		Reported_Date=payload.get("Reported_Date")
                 		Issue=payload.get("Issue")
                 		Issue_Description=payload.get("Issue_Description")
                 		Severity=payload.get("Severity")
                 		Issue_Status="Open"
                 		Added_User=zoho.loginuser
                 	]
                 	info "Masaka Sites sync inserted issue: " + payload.get("Issue_Number");
                 }

void fix_sales_vouchers_from_invoice(int invoice_id)
{
                 	inv = Invoice[ID == invoice_id];
                 	if(inv.ID == null)
                 	{
                 		return;
                 	}
                 	total_invoice_paid = 0.0;
                 	for each  p in Payment_Receipt_Details[Payment_Document == "Invoice" && Invoice == inv.ID]
                 	{
                 		total_invoice_paid = total_invoice_paid + ifnull(p.Amount_Allocated,0.0);
                 	}
                 	remaining_paid = total_invoice_paid;
                 	for each  d in Invoice_Details[Invoice == inv.ID && Source_Form == "Sales Voucher"]
                 	{
                 		sv = Sales_Voucher[ID == d.Source_Record_ID];
                 		if(sv.ID != null)
                 		{
                 			sv_total = ifnull(sv.Grand_Total,0.0);
                 			current_credit = ifnull(sv.Amount_Credited,0.0);
                 			pay_for_this_sv = 0.0;
                 			if(remaining_paid >= sv_total)
                 			{
                 				pay_for_this_sv = sv_total;
                 			}
                 			else if(remaining_paid > 0)
                 			{
                 				pay_for_this_sv = remaining_paid;
                 			}
                 			remaining_paid = remaining_paid - pay_for_this_sv;
                 			bal = sv_total - pay_for_this_sv - current_credit;
                 			if(bal < 0)
                 			{
                 				bal = 0.0;
                 			}
                 			update Sales_Voucher[ID == sv.ID]
                 			[
                 				Amount_Paid=pay_for_this_sv
                 				Amount_Credited=current_credit
                 				Balance_Due=bal
                 				Payment_Status=if(bal <= 0,"Paid",if(pay_for_this_sv > 0,"Partially Paid",if(current_credit > 0,"Partially Credited","Unpaid")))
                 			];
                 		}
                 	}
                 }

map generate_missing_sales_voucher_details()
{
                 	result = Map();
                 	failed_records = List();
                 	skipped_records = List();
                 	item_cache = Map();
                 	processed_count = 0;
                 	generated_count = 0;
                 	already_existing_count = 0;
                 	skipped_count = 0;
                 	failed_count = 0;
                 	target_site = "Gomba Site - ARA075";
                 	batch_size = 100;
                 	/*
                 	 * Count existing Gomba Site Sand Sales detail lines.
                 	 *
                 	 * Because the system uses one detail line per Sand Sales
                 	 * voucher, this count becomes the automatic cursor.
                 	 */
                 	existing_gomba_details = Sales_Voucher_Details[Sales_Voucher.Sales_Type == "Sand Sales" && Sales_Voucher.Display_Name_Site == target_site].count();
                 	start_index = existing_gomba_details + 1;
                 	end_index = start_index + batch_size - 1;
                 	/*
                 	 * Retrieve the next Gomba Site batch.
                 	 *
                 	 * Basic mandatory fields are included in the criteria so
                 	 * the function does not spend its batch on clearly
                 	 * incomplete vouchers.
                 	 */
                 	voucher_batch = Sales_Voucher[Sales_Type == "Sand Sales" && Display_Name_Site == target_site && Item != null && Store_Item_Stock != null && Store != null && Unit_Of_Measure != null] sort by ID range from start_index to end_index;
                 	for each  sales_voucher in voucher_batch
                 	{
                 		processed_count = processed_count + 1;
                 		try 
                 		{
                 			voucher_reference = ifnull(sales_voucher.Sales_Voucher_Number,sales_voucher.ID.toString());
                 			/*
                 			 * Safety check against accidental duplicates.
                 			 */
                 			existing_lines = Sales_Voucher_Details[Sales_Voucher == sales_voucher.ID];
                 			if(existing_lines.count() > 0)
                 			{
                 				already_existing_count = already_existing_count + 1;
                 			}
                 			else
                 			{
                 				actual_item_id = null;
                 				/*
                 				 * Sales_Voucher.Item points to
                 				 * Product_Price_Register.
                 				 */
                 				if(sales_voucher.Item != null)
                 				{
                 					product_price_key = sales_voucher.Item.toString();
                 					actual_item_id = item_cache.get(product_price_key);
                 					if(actual_item_id == null)
                 					{
                 						product_price_records = Product_Price_Register[ID == sales_voucher.Item];
                 						if(product_price_records.count() > 0)
                 						{
                 							product_price_rec = product_price_records;
                 							if(product_price_rec.Item != null)
                 							{
                 								actual_item_id = product_price_rec.Item;
                 								item_cache.put(product_price_key,actual_item_id);
                 							}
                 						}
                 					}
                 				}
                 				if(actual_item_id == null)
                 				{
                 					skipped_count = skipped_count + 1;
                 					skipped_records.add("Voucher " + voucher_reference + " skipped. Product Price Register has no linked inventory Item.");
                 				}
                 				else
                 				{
                 					quantity_value = ifnull(sales_voucher.Truck_CBM,0.0);
                 					unit_price_value = ifnull(sales_voucher.Rate_per_CBM,0.0);
                 					line_total_value = round(quantity_value * unit_price_value,2);
                 					new_detail_id = insert into Sales_Voucher_Details
                 					[
                 						Sales_Voucher=sales_voucher.ID
                 						Display_Name_Sales_Voucher=ifnull(sales_voucher.Sales_Voucher_Number,"")
                 						Line_Number=1
                 						Store_Item_Stock=sales_voucher.Store_Item_Stock
                 						Store=sales_voucher.Store
                 						Display_Name_Store=ifnull(sales_voucher.Display_Name_Store,"")
                 						Quantity_Available=ifnull(sales_voucher.Quantity_Available,0.0)
                 						Item=actual_item_id
                 						Display_Name_Item=ifnull(sales_voucher.Display_Name_Item,"")
                 						Base_Unit_Of_Measure=sales_voucher.Unit_Of_Measure
                 						Display_Name_Base_Unit_Of_Measure=ifnull(sales_voucher.Display_Name_Unit_Of_Measure,"")
                 						Quantity=quantity_value
                 						Quantity_in_Base_Unit_Of_Measure=quantity_value
                 						Quantity_Issued_in_Base_Unit_Of_Measure=0.0
                 						Quantity_Not_Issued_in_Base_Unit_Of_Measure=quantity_value
                 						Issue_Status="Not Issued"
                 						Unit_Price=unit_price_value
                 						Line_Total=line_total_value
                 						Tax_Amount=0.0
                 						Added_User=zoho.loginuser
                 					];
                 					if(new_detail_id != null)
                 					{
                 						generated_count = generated_count + 1;
                 					}
                 					else
                 					{
                 						failed_count = failed_count + 1;
                 						failed_records.add("Voucher " + voucher_reference + ": insert returned no ID.");
                 					}
                 				}
                 			}
                 		}		catch (e)
                 		{
                 			failed_count = failed_count + 1;
                 			voucher_reference = ifnull(sales_voucher.Sales_Voucher_Number,sales_voucher.ID.toString());
                 			failed_records.add("Voucher " + voucher_reference + ": " + e.toString());
                 		}
                 	}
                 	total_eligible_gomba_vouchers = Sales_Voucher[Sales_Type == "Sand Sales" && Display_Name_Site == target_site && Item != null && Store_Item_Stock != null && Store != null && Unit_Of_Measure != null].count();
                 	updated_existing_gomba_details = Sales_Voucher_Details[Sales_Voucher.Sales_Type == "Sand Sales" && Sales_Voucher.Display_Name_Site == target_site].count();
                 	remaining_count = total_eligible_gomba_vouchers - updated_existing_gomba_details;
                 	if(remaining_count < 0)
                 	{
                 		remaining_count = 0;
                 	}
                 	has_more = remaining_count > 0;
                 	result.put("ok",failed_count == 0);
                 	result.put("site",target_site);
                 	result.put("batch_size",batch_size);
                 	result.put("start_index",start_index);
                 	result.put("end_index",end_index);
                 	result.put("processed_count",processed_count);
                 	result.put("generated_count",generated_count);
                 	result.put("already_existing_count",already_existing_count);
                 	result.put("skipped_count",skipped_count);
                 	result.put("failed_count",failed_count);
                 	result.put("total_eligible_gomba_vouchers",total_eligible_gomba_vouchers);
                 	result.put("existing_gomba_details",updated_existing_gomba_details);
                 	result.put("remaining_count",remaining_count);
                 	result.put("has_more",has_more);
                 	result.put("skipped_records",skipped_records);
                 	result.put("failed_records",failed_records);
                 	if(failed_count > 0)
                 	{
                 		result.put("message","Batch completed with failures. Review failed_records.");
                 	}
                 	else if(skipped_count > 0)
                 	{
                 		result.put("message","Batch completed. Some Product Price records have no linked inventory Item.");
                 	}
                 	else if(has_more == true)
                 	{
                 		result.put("message","Batch completed successfully. Execute the function again for the next Gomba Site batch.");
                 	}
                 	else
                 	{
                 		result.put("message","Backfill completed. All eligible Gomba Site Sand Sales vouchers have details.");
                 	}
                 	info result;
                 	return result;
                 }

string Generate_Voucher_Number(int documentKeyId)
{
                 	dk = Document_Key[ID == documentKeyId];
                 	if(dk == null)
                 	{
                 		return "";
                 	}
                 	// ---- Prefix: EXACTLY 3 letters ----
                 	prefix = ifnull(dk.Prefix,"").trim().toUpperCase();
                 	if(!prefix.matches("^[A-Z]{3}$"))
                 	{
                 		return "";
                 	}
                 	// ---- Next number ----
                 	nextNo = ifnull(dk.Next_Number,0);
                 	if(nextNo <= 0)
                 	{
                 		nextNo = 1;
                 	}
                 	// ---- HARD STOP at 999 ----
                 	if(nextNo > 999)
                 	{
                 		return "LIMIT_REACHED";
                 	}
                 	// ---- Pad to 3 digits ----
                 	numStr = nextNo.toString();
                 	if(numStr.length() == 1)
                 	{
                 		numStr = "00" + numStr;
                 	}
                 	else if(numStr.length() == 2)
                 	{
                 		numStr = "0" + numStr;
                 	}
                 	voucherNo = prefix + numStr;
                 	// ---- Increment counter ----
                 	dk.Next_Number=nextNo + 1;
                 	return voucherNo;
                 }

