map rebuildDraftSalesVoucherPaymentStatuses()
{
                 	response = Map();
                 	response.put("ok",false);
                 	batch_size = 200;
                 	processed_count = 0;
                 	success_count = 0;
                 	error_count = 0;
                 	last_processed_id = 0;
                 	try 
                 	{
                 		// =====================================================
                 		// FETCH NEXT 200 DRAFT SALES VOUCHERS
                 		// =====================================================
                 		draft_sales_vouchers = Sales_Voucher[Payment_Status == "Draft"] sort by ID range from 0 to 199;
                 		records_found = draft_sales_vouchers.count();
                 		// =====================================================
                 		// NO DRAFT RECORDS REMAIN
                 		// =====================================================
                 		if(records_found == 0)
                 		{
                 			response.put("ok",true);
                 			response.put("completed",true);
                 			response.put("message","No Draft Sales Vouchers remain.");
                 			response.put("processed_count",0);
                 			response.put("success_count",0);
                 			response.put("error_count",0);
                 			return response;
                 		}
                 		// =====================================================
                 		// PROCESS DRAFT RECORDS
                 		// =====================================================
                 		for each  sales_voucher_rec in draft_sales_vouchers
                 		{
                 			processed_count = processed_count + 1;
                 			last_processed_id = sales_voucher_rec.ID;
                 			try 
                 			{
                 				result = thisapp.rebuildSalesVoucherPaymentStatus(sales_voucher_rec.ID);
                 				if(ifnull(result.get("ok"),false) == true)
                 				{
                 					success_count = success_count + 1;
                 				}
                 				else
                 				{
                 					error_count = error_count + 1;
                 					info "Sales Voucher rebuild failed.";
                 					info "Sales Voucher ID: " + sales_voucher_rec.ID;
                 					info result;
                 				}
                 			}			catch (record_error)
                 			{
                 				error_count = error_count + 1;
                 				info "Sales Voucher rebuild error.";
                 				info "Sales Voucher ID: " + sales_voucher_rec.ID;
                 				info record_error.toString();
                 			}
                 		}
                 		// =====================================================
                 		// COUNT REMAINING DRAFT RECORDS
                 		// =====================================================
                 		remaining_draft_count = Sales_Voucher[Payment_Status == "Draft"].count();
                 		// =====================================================
                 		// RETURN BATCH SUMMARY
                 		// =====================================================
                 		response.put("ok",true);
                 		response.put("completed",remaining_draft_count == 0);
                 		response.put("message","Draft Sales Voucher batch completed.");
                 		response.put("batch_size",batch_size);
                 		response.put("records_found",records_found);
                 		response.put("processed_count",processed_count);
                 		response.put("success_count",success_count);
                 		response.put("error_count",error_count);
                 		response.put("remaining_draft_count",remaining_draft_count);
                 		response.put("last_processed_id",last_processed_id);
                 	}	catch (e)
                 	{
                 		response.put("message","Unable to process the Draft Sales Voucher batch.");
                 		response.put("error",e.toString());
                 		response.put("processed_count",processed_count);
                 		response.put("success_count",success_count);
                 		response.put("error_count",error_count);
                 	}
                 	return response;
                 }

map rebuildSalesVoucherPaymentStatus(INT sales_voucher_id)
{
                 	response = Map();
                 	response.put("ok",false);
                 	response.put("sales_voucher_id",sales_voucher_id);
                 	try 
                 	{
                 		// =====================================================
                 		// GET SALES VOUCHER
                 		// =====================================================
                 		sales_voucher_rec = Sales_Voucher[ID == sales_voucher_id];
                 		if(sales_voucher_rec.ID == null)
                 		{
                 			response.put("message","Sales Voucher was not found.");
                 			return response;
                 		}
                 		// =====================================================
                 		// CANCELLED VOUCHER
                 		// =====================================================
                 		if(ifnull(sales_voucher_rec.Cancel_Voucher,false) == true)
                 		{
                 			sales_voucher_rec.Amount_Paid=0.0;
                 			sales_voucher_rec.Amount_Credited=0.0;
                 			sales_voucher_rec.Balance_Due=0.0;
                 			sales_voucher_rec.Payment_Status="Cancelled";
                 			response.put("ok",true);
                 			response.put("message","Cancelled Sales Voucher updated.");
                 			response.put("payment_status","Cancelled");
                 			return response;
                 		}
                 		// =====================================================
                 		// INITIALISE TOTALS
                 		// =====================================================
                 		grand_total = ifnull(sales_voucher_rec.Grand_Total,0.0);
                 		total_amount_paid = 0.0;
                 		total_amount_credited = 0.0;
                 		payment_detail_count = 0;
                 		// =====================================================
                 		// GET PAYMENT RECEIPT DETAILS
                 		// =====================================================
                 		payment_details = Payment_Receipt_Details[Sales_Voucher == sales_voucher_id && Payment_Document == "Sales Voucher"];
                 		for each  payment_detail_rec in payment_details
                 		{
                 			total_amount_paid = total_amount_paid + ifnull(payment_detail_rec.Amount_Allocated,0.0);
                 			total_amount_credited = total_amount_credited + ifnull(payment_detail_rec.Amount_Credited,0.0);
                 			payment_detail_count = payment_detail_count + 1;
                 		}
                 		// =====================================================
                 		// PREVENT NEGATIVE PAYMENT VALUES
                 		// =====================================================
                 		if(total_amount_paid < 0)
                 		{
                 			total_amount_paid = 0.0;
                 		}
                 		if(total_amount_credited < 0)
                 		{
                 			total_amount_credited = 0.0;
                 		}
                 		// =====================================================
                 		// CALCULATE BALANCE
                 		// =====================================================
                 		total_settled = total_amount_paid + total_amount_credited;
                 		balance_due = grand_total - total_settled;
                 		// Allow for very small decimal rounding differences.
                 		if(balance_due > -0.01 && balance_due < 0.01)
                 		{
                 			balance_due = 0.0;
                 		}
                 		// A Sales Voucher should not normally display a
                 		// negative outstanding balance.
                 		if(balance_due < 0)
                 		{
                 			balance_due = 0.0;
                 		}
                 		// =====================================================
                 		// DETERMINE PAYMENT STATUS
                 		// =====================================================
                 		payment_status = "Unpaid";
                 		if(grand_total <= 0)
                 		{
                 			payment_status = "Paid";
                 		}
                 		else if(balance_due <= 0)
                 		{
                 			// Fully settled using credit only.
                 			if(total_amount_paid <= 0 && total_amount_credited > 0)
                 			{
                 				payment_status = "Credit";
                 			}
                 			else
                 			{
                 				// Fully settled by cash or a combination of
                 				// cash and credit.
                 				payment_status = "Paid";
                 			}
                 		}
                 		else if(total_amount_paid > 0)
                 		{
                 			// Cash has priority where both cash and credit
                 			// have partially settled the voucher.
                 			payment_status = "Partially Paid";
                 		}
                 		else if(total_amount_credited > 0)
                 		{
                 			payment_status = "Partially Credited";
                 		}
                 		else
                 		{
                 			payment_status = "Unpaid";
                 		}
                 		// =====================================================
                 		// UPDATE SALES VOUCHER
                 		// =====================================================
                 		sales_voucher_rec.Amount_Paid=total_amount_paid;
                 		sales_voucher_rec.Amount_Credited=total_amount_credited;
                 		sales_voucher_rec.Balance_Due=balance_due;
                 		sales_voucher_rec.Payment_Status=payment_status;
                 		// =====================================================
                 		// RETURN RESULT
                 		// =====================================================
                 		response.put("ok",true);
                 		response.put("message","Sales Voucher payment totals and status rebuilt successfully.");
                 		response.put("sales_voucher_number",sales_voucher_rec.Sales_Voucher_Number);
                 		response.put("grand_total",grand_total);
                 		response.put("amount_paid",total_amount_paid);
                 		response.put("amount_credited",total_amount_credited);
                 		response.put("total_settled",total_settled);
                 		response.put("balance_due",balance_due);
                 		response.put("payment_status",payment_status);
                 		response.put("payment_detail_count",payment_detail_count);
                 		response.put("ok",true);
                 	}	catch (e)
                 	{
                 		response.put("message",e.toString());
                 	}
                 	return response;
                 }

void rebuildSalesVoucherPaymentStatusBatch(INT start_index, INT batch_size)
{
                 	// =====================================================
                 	// VALIDATE INPUTS
                 	// =====================================================
                 	if(start_index == null || start_index < 0)
                 	{
                 		start_index = 0;
                 	}
                 	if(batch_size == null || batch_size <= 0)
                 	{
                 		batch_size = 100;
                 	}
                 	// Keep the batch controlled.
                 	if(batch_size > 200)
                 	{
                 		batch_size = 200;
                 	}
                 	end_index = start_index + batch_size - 1;
                 	// =====================================================
                 	// INITIALISE COUNTERS
                 	// =====================================================
                 	processed_count = 0;
                 	success_count = 0;
                 	error_count = 0;
                 	// =====================================================
                 	// FETCH SALES VOUCHERS
                 	// =====================================================
                 	sales_voucher_records = Sales_Voucher[ID != 0] sort by ID range from start_index to end_index;
                 	// =====================================================
                 	// PROCESS BATCH
                 	// =====================================================
                 	for each  sales_voucher_rec in sales_voucher_records
                 	{
                 		processed_count = processed_count + 1;
                 		try 
                 		{
                 			result = thisapp.rebuildSalesVoucherPaymentStatus(sales_voucher_rec.ID);
                 			if(ifnull(result.get("ok"),false) == true)
                 			{
                 				success_count = success_count + 1;
                 			}
                 			else
                 			{
                 				error_count = error_count + 1;
                 				info "Sales Voucher rebuild failed:";
                 				info result;
                 			}
                 		}		catch (e)
                 		{
                 			error_count = error_count + 1;
                 			info "Sales Voucher ID: " + sales_voucher_rec.ID;
                 			info "Batch error: " + e.toString();
                 		}
                 	}
                 	// =====================================================
                 	// BATCH SUMMARY
                 	// =====================================================
                 	info "========================================";
                 	info "SALES VOUCHER PAYMENT REBUILD BATCH";
                 	info "Start index: " + start_index;
                 	info "End index: " + end_index;
                 	info "Batch size requested: " + batch_size;
                 	info "Records processed: " + processed_count;
                 	info "Successful: " + success_count;
                 	info "Errors: " + error_count;
                 	info "Next start index: " + (end_index + 1);
                 	info "========================================";
                 }

void recalculateDailySiteReportFuelCost(int daily_site_report_id)
