                 	fuel_vouchers = Fuel_Receiving_Voucher[Manager_Voucher == daily_site_report_id];
                 	for each  fuel_rec in fuel_vouchers
                 	{
                 		total_fuel_cost = total_fuel_cost + ifnull(fuel_rec.Total,0.0);
