void recalculatePaymentVoucher(int voucherID)
{
                 	voucher = Payment_Made_Voucher[ID == voucherID];
                 	if(voucher.ID == null)
                 	{
                 		return;
                 	}
                 	total_allocated = 0.0;
                 	for each  md in Payment_Made_Details[Payment_Made_Voucher == voucher.ID]
                 	{
                 		total_allocated = total_allocated + ifnull(md.Amount_Allocated,0.0);
                 	}
                 	total_paid = ifnull(voucher.Total_Amount_Paid,0.0);
                 	not_allocated = total_paid - total_allocated;
                 	if(not_allocated < 0)
                 	{
                 		not_allocated = 0.0;
                 	}
                 	voucher.Total_Amount_Allocated=round(total_allocated,2);
                 	voucher.Total_Amount_Not_Allocated=round(not_allocated,2);
                 	if(total_allocated <= 0)
                 	{
                 		voucher.Payment_Made_Voucher_Status="Unassigned";
                 	}
                 	else if(not_allocated > 0)
                 	{
                 		voucher.Payment_Made_Voucher_Status="Partially Assigned";
                 	}
                 	else
                 	{
                 		voucher.Payment_Made_Voucher_Status="Assigned";
                 	}
                 }

void recalculateVoucherMaterialsCost(int voucher_id)
{
                 	if(voucher_id == null)
                 	{
                 		return;
                 	}
                 	v = Voucher_Register[ID == voucher_id];
                 	if(v.ID == null)
                 	{
                 		return;
                 	}
                 	total_cost = 0.0;
                 	// Item Issuing Details
                 	item_rows = Voucher_Issuing_Details[Voucher == voucher_id];
                 	for each  r in item_rows
                 	{
                 		total_cost = total_cost + ifnull(r.Quantity,0.0) * ifnull(r.Cost,0.0);
                 	}
                 	// Employee Issuing Details
                 	emp_rows = Employee_Issuing_Details[Voucher == voucher_id];
                 	for each  er in emp_rows
                 	{
                 		total_cost = total_cost + ifnull(er.Quantity,0.0) * ifnull(er.Cost,0.0);
                 	}
                 	v.Voucher_Cost=round(total_cost,2);
                 }

void runSeptember2026SpecialBackfillBySite()
{
                 	startDate = "01-Sep-2026".toDate();
                 	endDate = "30-Sep-2026".toDate();
                 	// ONLY THESE TWO LINES CHANGE BETWEEN RUNS
                 	firstSiteIndex = 0;
                 	// next run: 1, then 2, ...
                 	sitesPerRun = 1;
                 	// raise to 2-3 if you stay under the limit
                 	// Build the distinct site list from the data itself
                 	rawSites = Voucher_Register[Date_Time_In >= startDate && Date_Time_In < endDate.addDay(1)].Display_Name_Site.getAll();
                 	cleanSites = List();
                 	for each  s in rawSites
                 	{
                 		siteTrim = ifnull(s,"").trim();
                 		if(siteTrim != "" && !cleanSites.contains(siteTrim))
                 		{
                 			cleanSites.add(siteTrim);
                 		}
                 	}
                 	cleanSites = cleanSites.sort(true);
                 	// stable order so indexes stay consistent
                 	info "Total sites found: " + cleanSites.size();
                 	lastSiteIndex = firstSiteIndex + sitesPerRun;
                 	for each index i in cleanSites
                 	{
                 		if(i >= firstSiteIndex && i < lastSiteIndex)
                 		{
                 			siteToProcess = cleanSites.get(i);
                 			info "---------------------------------------------";
                 			info "Site #" + i + ": " + siteToProcess;
                 			result = thisapp.billing.backfillSpecialMonthlyEmployees1(startDate,endDate,siteToProcess);
                 			if(result != null)
                 			{
                 				info "Success: " + result.get("ok");
                 				info "Created: " + result.get("records_created") + " | Updated: " + result.get("records_updated") + " | Groups: " + result.get("groups_processed");
                 			}
                 		}
                 	}
                 	if(lastSiteIndex < cleanSites.size())
                 	{
                 		info "NEXT RUN: set firstSiteIndex = " + lastSiteIndex;
                 	}
                 	else
                 	{
                 		info "ALL SITES DONE.";
                 	}
                 }

