                 		existing_record.Updated_By_Email=ifnull(p.get("Updated_By_Email"),"");
                 		existing_record.Updated_By_Time=p.get("Updated_By_Time");
                 		current_status = ifnull(existing_record.Voucher_Status,"").toString().trim();
                 		stored_status = current_status;
                 		if(incoming_status != "Draft" || current_status == "" || current_status == "Draft")
                 		{
                 			existing_record.Voucher_Status=incoming_status;
                 			stored_status = incoming_status;
                 		}
                 		else
                 		{
                 			info "Machine Start Of Day status preserved as " + current_status + ". Incoming Draft status was ignored.";
                 		}
                 		resp.put("ok",true);
                 		resp.put("Machine_Start_Of_Day_ID",existing_record.ID);
                 		resp.put("Source_Record_ID",source_record_id);
                 		resp.put("Incoming_Status",incoming_status);
                 		resp.put("Stored_Status",stored_status);
                 		resp.put("message","Machine Start Of Day updated from Asset Management.");
                 		return resp;
                 	}
                 	// =====================================================
                 	// 5. INSERT NEW RECORD
                 	new_record_id = insert into Machine_Start_Of_Day
                 	[
                 		Voucher=voucher_id
                 		Display_Name_Voucher=ifnull(p.get("Display_Name_Voucher"),"")
                 		Display_Name_Employee=ifnull(p.get("Display_Name_Employee"),"")
                 		Display_Name_Voucher_Type=ifnull(p.get("Display_Name_Voucher_Type"),"")
                 		Display_Name_Site=site_display
                 		Display_Name_Asset_Type=ifnull(p.get("Display_Name_Asset_Type"),"")
                 		Asset=p.get("Asset")
                 		Display_Name_Asset=ifnull(p.get("Display_Name_Asset"),"")
                 		Turn_Man=p.get("Turn_Man")
                 		Display_Name_Turn_Man=ifnull(p.get("Display_Name_Turn_Man"),"")
                 		Odometer_Start=p.get("Odometer_Start")
                 		Fuel_Start_Level=p.get("Fuel_Start_Level")
                 		Time_Started=p.get("Time_Started")
                 		Odometer_End=p.get("Odometer_End")
                 		Fuel_End_Level=p.get("Fuel_End_Level")
                 		Time_Ended=p.get("Time_Ended")
                 		Voucher_Status=incoming_status
                 		Notes=ifnull(p.get("Notes"),"")
                 		User_Name=ifnull(p.get("User_Name"),"")
                 		User_Email=ifnull(p.get("User_Email"),"")
                 		User_Role=ifnull(p.get("User_Role"),"")
                 		Created_By_Name=ifnull(p.get("Created_By_Name"),"")
                 		Created_By_Email=ifnull(p.get("Created_By_Email"),"")
                 		Created_By_Time=p.get("Created_By_Time")
                 		Updated_By_Name=ifnull(p.get("Updated_By_Name"),"")
                 		Updated_By_Email=ifnull(p.get("Updated_By_Email"),"")
                 		Updated_By_Time=p.get("Updated_By_Time")
                 		Source_Record_ID=source_record_id
                 		Source_Form=source_form
                 		Added_User=zoho.loginuser
                 	];
                 	resp.put("ok",true);
                 	resp.put("Machine_Start_Of_Day_ID",new_record_id);
                 	resp.put("Source_Record_ID",source_record_id);
                 	resp.put("Incoming_Status",incoming_status);
                 	resp.put("Stored_Status",incoming_status);
                 	resp.put("message","Machine Start Of Day synced from Asset Management.");
                 	return resp;
                 }

