map syncTractorWorkReportFromAssetManagement(map p)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	resp.put("message","");
                 	// ============================================================
                 	// 1. SOURCE
                 	// ============================================================
                 	source_text = ifnull(p.get("Source_Record_ID"),"").toString().trim();
                 	source_form = ifnull(p.get("Source_Form"),"").toString().trim();
                 	if(source_text == "")
                 	{
                 		resp.put("message","Source_Record_ID is required.");
                 		return resp;
