                 	{
                 		source_form = "Asset Management - Tractor Work Report";
                 	}
                 	try 
                 	{
                 		source_id = source_text.toLong();
                 	}	catch (e)
                 	{
                 		resp.put("message","Invalid Source_Record_ID: " + source_text);
                 		return resp;
                 	}
                 	// ============================================================
                 	// 2. CONVERT LOOKUP IDS
                 	// ============================================================
                 	asset_voucher_id = 0;
                 	job_id = 0;
                 	card_id = 0;
                 	work_order_id = 0;
                 	batch_id = 0;
                 	try 
                 	{
                 		// Asset Management Voucher
                 		// Used later for Machine Start Of Day
                 		if(ifnull(p.get("Voucher"),"").toString().trim() != "")
                 		{
                 			asset_voucher_id = p.get("Voucher").toString().toLong();
                 		}
                 		if(ifnull(p.get("Job"),"").toString().trim() != "")
                 		{
                 			job_id = p.get("Job").toString().toLong();
                 		}
                 		if(ifnull(p.get("Card"),"").toString().trim() != "")
                 		{
                 			card_id = p.get("Card").toString().toLong();
                 		}
                 		if(ifnull(p.get("Work_Order_Task"),"").toString().trim() != "")
                 		{
                 			work_order_id = p.get("Work_Order_Task").toString().toLong();
                 		}
                 		if(ifnull(p.get("Batch_Number_Masaka"),"").toString().trim() != "")
                 		{
                 			batch_id = p.get("Batch_Number_Masaka").toString().toLong();
                 		}
                 	}	catch (e)
                 	{
                 		resp.put("message","Invalid lookup ID in payload: " + e.toString());
                 		return resp;
                 	}
                 	// ============================================================
                 	// 3. RESOLVE MASAKA VOUCHER REGISTER
                 	//
                 	// Voucher points to Masaka Voucher_Register.
                 	// Do NOT assign the Asset Voucher ID directly to Voucher.
                 	// ============================================================
                 	masaka_voucher_id = 0;
                 	voucher_number = ifnull(p.get("Display_Name_Voucher"),"").toString().trim();
                 	employee_name = ifnull(p.get("Display_Name_Employee"),"").toString().trim();
                 	if(voucher_number != "")
                 	{
                 		if(employee_name != "")
                 		{
                 			voucher_rec = Voucher_Register[Voucher_Number == voucher_number && Display_Name_Employee == employee_name];
                 		}
                 		else
                 		{
                 			voucher_rec = Voucher_Register[Voucher_Number == voucher_number];
                 		}
                 		if(voucher_rec.ID != null)
                 		{
                 			masaka_voucher_id = voucher_rec.ID;
                 			info "==============================================";
                 			info "MASAKA TRACTOR VOUCHER FOUND";
                 			info "Voucher Number: " + voucher_number;
                 			info "Employee: " + employee_name;
                 			info "Voucher Register ID: " + masaka_voucher_id;
                 			info "==============================================";
                 		}
                 		else
                 		{
                 			info "==============================================";
                 			info "MASAKA TRACTOR VOUCHER NOT FOUND";
                 			info "Voucher Number: " + voucher_number;
                 			info "Employee: " + employee_name;
                 			info "==============================================";
                 		}
                 	}
                 	// ============================================================
                 	// 4. CHECK WORK ORDER TASK
                 	// ============================================================
                 	if(work_order_id > 0)
                 	{
                 		work_order_rec = Work_Order_Tasks[ID == work_order_id];
                 		if(work_order_rec.ID == null)
                 		{
                 			info "Work Order Task not found in Masaka: " + work_order_id;
                 			work_order_id = 0;
                 		}
                 	}
                 	// ============================================================
                 	// 5. CHECK CARD
                 	// ============================================================
                 	if(card_id > 0)
                 	{
                 		card_rec = Sales_Voucher[ID == card_id];
                 		if(card_rec.ID == null)
                 		{
                 			info "Card not found in Masaka: " + card_id;
                 			card_id = 0;
                 		}
                 	}
                 	// ============================================================
                 	// 6. FIND EXISTING MASAKA TRACTOR WORK REPORT
                 	// ============================================================
                 	existing_rec = Tractor_Work_Report[Source_Record_ID == source_id && Source_Form == source_form];
                 	action_taken = "Updated";
                 	// ============================================================
                 	// 7. CREATE IF MISSING
                 	// ============================================================
                 	if(existing_rec.ID == null)
                 	{
                 		try 
                 		{
                 			new_id = insert into Tractor_Work_Report
                 			[
                 				Source_Record_ID=source_id
                 				Source_Form=source_form
                 				Added_User=zoho.loginuser
                 			];
                 			existing_rec = Tractor_Work_Report[ID == new_id];
                 			action_taken = "Created";
                 		}		catch (e)
                 		{
                 			resp.put("message","Could not create Masaka Tractor Work Report: " + e.toString());
                 			return resp;
                 		}
                 	}
                 	if(existing_rec.ID == null)
                 	{
                 		resp.put("message","Masaka Tractor Work Report could not be loaded.");
                 		return resp;
                 	}
                 	// ============================================================
                 	// 8. ASSIGN MASAKA VOUCHER
                 	// ============================================================
                 	if(masaka_voucher_id > 0)
                 	{
                 		try 
                 		{
                 			existing_rec.Voucher=masaka_voucher_id;
                 			info "Voucher lookup assigned successfully.";
                 			info "Voucher Register ID: " + masaka_voucher_id;
                 		}		catch (e)
                 		{
                 			info "Voucher assignment failed: " + e.toString();
                 		}
                 	}
                 	else
                 	{
                 		info "Voucher lookup not assigned because matching Voucher Register record was not found.";
                 	}
                 	// ============================================================
                 	// 9. MACHINE START OF DAY
                 	//
                 	// Same method used by Truck Movement.
                 	// Machine Start Of Day receives the Asset Management
                 	// Voucher ID.
                 	// ============================================================
                 	machine_start_message = "";
                 	if(asset_voucher_id > 0)
                 	{
                 		try 
                 		{
                 			existing_rec.Machine_Start_Of_Day=asset_voucher_id;
