                 			machine_start_message = e.toString();
                 			info "==============================================";
                 			info "TRACTOR MACHINE START OF DAY NOT ASSIGNED";
                 			info "Asset Voucher ID: " + asset_voucher_id;
                 			info "Voucher Number: " + voucher_number;
                 			info "Error: " + machine_start_message;
                 			info "==============================================";
                 		}
                 	}
                 	// ============================================================
                 	// 10. HEADER
                 	// ============================================================
                 	try 
                 	{
                 		existing_rec.Display_Name_Voucher=p.get("Display_Name_Voucher");
                 		existing_rec.Display_Name_Employee=p.get("Display_Name_Employee");
                 		existing_rec.Display_Name_Site=p.get("Display_Name_Site");
                 		existing_rec.Display_Name_Asset=p.get("Display_Name_Asset");
                 		existing_rec.Line_Number=p.get("Line_Number");
                 	}	catch (e)
                 	{
                 		resp.put("message","Header assignment failed: " + e.toString());
                 		return resp;
                 	}
                 	// ============================================================
                 	// 11. LOCATION
                 	// ============================================================
                 	existing_rec.Location=p.get("Location");
                 	// ============================================================
                 	// 12. JOB
                 	// ============================================================
                 	if(job_id > 0)
                 	{
                 		try 
                 		{
                 			existing_rec.Job=job_id;
                 			info "==============================================";
                 			info "TRACTOR JOB ASSIGNED";
                 			info "Job ID: " + job_id;
                 			info "Job Name: " + p.get("Display_Name_Job");
                 			info "==============================================";
                 		}		catch (e)
                 		{
                 			info "Job lookup assignment failed: " + e.toString();
                 		}
                 	}
                 	existing_rec.Display_Name_Job=p.get("Display_Name_Job");
                 	// ============================================================
                 	// 13. CARD
                 	// ============================================================
                 	if(card_id > 0)
                 	{
                 		try 
                 		{
                 			existing_rec.Card=card_id;
                 			info "Card assigned: " + card_id;
                 		}		catch (e)
                 		{
                 			info "Card assignment failed: " + e.toString();
                 		}
                 	}
                 	existing_rec.Display_Name_Card=p.get("Display_Name_Card");
                 	// ============================================================
                 	// 14. WORK ORDER TASK
                 	// ============================================================
                 	if(work_order_id > 0)
                 	{
                 		try 
                 		{
                 			existing_rec.Work_Order_Task=work_order_id;
                 			info "Work Order Task assigned: " + work_order_id;
                 		}		catch (e)
                 		{
                 			info "Work Order Task assignment failed: " + e.toString();
                 		}
                 	}
                 	// ============================================================
                 	// 15. BATCH NUMBER
                 	// ============================================================
                 	if(batch_id > 0)
                 	{
                 		try 
                 		{
                 			existing_rec.Batch_Number=batch_id;
                 			info "Batch Number assigned: " + batch_id;
                 		}		catch (e)
                 		{
                 			info "Batch Number assignment failed: " + e.toString();
                 		}
                 	}
