map syncTruckMovementFromAssetManagement(map p)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	resp.put("message","");
                 	// ============================================================
                 	// 1. SOURCE
                 	// ============================================================
                 	source_text = ifnull(p.get("Source_Record_ID"),"").toString().trim();
                 	source_form = ifnull(p.get("Source_Form"),"").toString().trim();
                 	if(source_text == "")
                 	{
                 		resp.put("message","Source_Record_ID is required.");
                 		return resp;
                 	}
                 	if(source_form == "")
                 	{
                 		source_form = "Asset Management - Truck Movement Voucher";
                 	}
                 	try 
                 	{
                 		source_id = source_text.toLong();
                 	}	catch (e)
                 	{
                 		resp.put("message","Invalid Source_Record_ID: " + source_text);
                 		return resp;
                 	}
                 	// ============================================================
                 	// 2. CONVERT LOOKUP IDS
                 	// ============================================================
                 	asset_voucher_id = 0;
                 	job_id = 0;
                 	card_id = 0;
                 	work_order_id = 0;
                 	site_from_id = 0;
                 	site_to_id = 0;
                 	site_location_from_id = 0;
                 	site_location_to_id = 0;
                 	try 
                 	{
                 		if(ifnull(p.get("Voucher"),"").toString().trim() != "")
                 		{
                 			asset_voucher_id = p.get("Voucher").toString().toLong();
                 		}
                 		if(ifnull(p.get("Job"),"").toString().trim() != "")
                 		{
                 			job_id = p.get("Job").toString().toLong();
                 		}
                 		if(ifnull(p.get("Card"),"").toString().trim() != "")
                 		{
                 			card_id = p.get("Card").toString().toLong();
                 		}
                 		if(ifnull(p.get("Work_Order_Task"),"").toString().trim() != "")
                 		{
                 			work_order_id = p.get("Work_Order_Task").toString().toLong();
                 		}
                 		if(ifnull(p.get("Site_From"),"").toString().trim() != "")
                 		{
                 			site_from_id = p.get("Site_From").toString().toLong();
                 		}
                 		if(ifnull(p.get("Site_To"),"").toString().trim() != "")
                 		{
                 			site_to_id = p.get("Site_To").toString().toLong();
                 		}
                 		if(ifnull(p.get("Site_Location_From"),"").toString().trim() != "")
                 		{
                 			site_location_from_id = p.get("Site_Location_From").toString().toLong();
                 		}
                 		if(ifnull(p.get("Site_Location_To"),"").toString().trim() != "")
                 		{
                 			site_location_to_id = p.get("Site_Location_To").toString().toLong();
                 		}
                 	}	catch (e)
                 	{
                 		resp.put("message","Invalid lookup ID in payload: " + e.toString());
                 		return resp;
                 	}
                 	// ============================================================
                 	// 3. RESOLVE MASAKA VOUCHER REGISTER
                 	//
                 	// IMPORTANT:
                 	// Voucher field points to Masaka Voucher_Register.
                 	//
                 	// We therefore DO NOT assign asset_voucher_id directly.
                 	//
                 	// We find:
                 	// QAH195 + Najib Kaweesa - 65
                 	// ============================================================
                 	masaka_voucher_id = 0;
                 	voucher_number = ifnull(p.get("Display_Name_Voucher"),"").toString().trim();
                 	employee_name = ifnull(p.get("Display_Name_Employee"),"").toString().trim();
                 	if(voucher_number != "")
                 	{
                 		if(employee_name != "")
                 		{
                 			voucher_rec = Voucher_Register[Voucher_Number == voucher_number && Display_Name_Employee == employee_name];
                 		}
                 		else
                 		{
                 			voucher_rec = Voucher_Register[Voucher_Number == voucher_number];
                 		}
                 		if(voucher_rec.ID != null)
                 		{
                 			masaka_voucher_id = voucher_rec.ID;
