                 			info "MASAKA VOUCHER NOT FOUND";
                 			info "Voucher Number: " + voucher_number;
                 			info "Employee: " + employee_name;
                 			info "==============================================";
                 		}
                 	}
                 	// ============================================================
                 	// 4. CHECK WORK ORDER TASK
                 	// ============================================================
                 	if(work_order_id > 0)
                 	{
                 		work_order_rec = Work_Order_Tasks[ID == work_order_id];
