                 		}
                 	}
                 	// ============================================================
                 	// 6. RESOLVE CUSTOMER FROM
                 	// ============================================================
                 	party_from_id = 0;
                 	party_from_name = ifnull(p.get("Display_Name_Party_From"),"").toString().trim();
