map syncVoucherFromEmployee(map payload)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	if(payload == null)
                 	{
                 		resp.put("message","Payload is null.");
                 		return resp;
                 	}
                 	concrete_id = payload.get("Concrete_Record_ID");
                 	if(concrete_id == null)
                 	{
                 		resp.put("message","Concrete Record ID missing.");
                 		return resp;
                 	}
                 	rec = Voucher_Register[ID == concrete_id];
                 	if(rec.ID == null)
                 	{
                 		resp.put("message","Concrete voucher not found.");
                 		return resp;
                 	}
                 	date_time_out_val = null;
                 	end_time_val = null;
                 	manager_time_val = null;
                 	time_checked_val = null;
                 	hr_time_checked_val = null;
                 	if(ifnull(payload.get("Date_Time_Out"),"") != "")
                 	{
                 		date_time_out_val = payload.get("Date_Time_Out").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	if(ifnull(payload.get("End_Time"),"") != "")
                 	{
                 		end_time_val = payload.get("End_Time").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	if(ifnull(payload.get("Manager_Time"),"") != "")
                 	{
                 		manager_time_val = payload.get("Manager_Time").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	if(ifnull(payload.get("Time_Checked"),"") != "")
                 	{
                 		time_checked_val = payload.get("Time_Checked").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	if(ifnull(payload.get("Hr_Time_Checked"),"") != "")
                 	{
                 		hr_time_checked_val = payload.get("Hr_Time_Checked").toDateTime("dd-MMM-yyyy HH:mm:ss");
                 	}
                 	voucher_status_val = ifnull(payload.get("Voucher_Status"),"");
                 	rec.Date_Time_Out=date_time_out_val;
                 	rec.Hours_Worked=payload.get("Hours_Worked");
                 	if(voucher_status_val != "")
                 	{
                 		rec.Voucher_Status=voucher_status_val;
                 	}
                 	rec.End_Time=end_time_val;
                 	rec.Odometer_End=payload.get("Odometer_End");
                 	rec.Fuel_End_Level=payload.get("Fuel_End_Level");
                 	rec.Manager_Time=manager_time_val;
                 	rec.Cancel_Voucher=payload.get("Cancel_Voucher");
                 	rec.Cancellation_Reason=ifnull(payload.get("Cancellation_Reason"),"");
                 	rec.Seen=payload.get("Seen");
                 	rec.Reason_for_not_Seen=ifnull(payload.get("Reason_for_not_Seen"),"");
                 	rec.Time_Checked=time_checked_val;
                 	rec.Hr_Time_Checked=hr_time_checked_val;
                 	resp.put("ok",true);
                 	resp.put("message","Concrete voucher updated from Employee Management.");
                 	resp.put("id",rec.ID);
                 	return resp;
                 }

map updateAssetIssueStatusFromAssetManagement(map p)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	resp.put("message","");
                 	source_record_id_text = ifnull(p.get("Source_Record_ID"),"").toString().trim();
                 	source_form = ifnull(p.get("Source_Form"),"").toString().trim();
                 	if(source_record_id_text == "")
                 	{
                 		resp.put("message","Source_Record_ID is required.");
                 		return resp;
                 	}
                 	if(source_form != "Masaka Site Management - Asset Issues")
                 	{
                 		resp.put("message","The Asset Issue is not linked to Masaka Site Management.");
                 		return resp;
                 	}
                 	source_record_id = source_record_id_text.toLong();
                 	freedom_issue = Asset_Issues[ID == source_record_id];
                 	if(freedom_issue.ID == null)
                 	{
                 		resp.put("message","The corresponding Masaka Site Management Asset Issue was not found.");
                 		return resp;
                 	}
                 	freedom_issue.Issue_Status="Open";
                 	resp.put("ok",true);
