map updatePaymentMadeStatusFromPayment(map payload)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	resp.put("message","");
                 	if(payload == null)
                 	{
                 		resp.put("message","Payload is null.");
                 		return resp;
                 	}
                 	source_record_id = ifnull(payload.get("Source_Record_ID"),0).toLong();
                 	voucher_number = ifnull(payload.get("Voucher_Number"),"");
                 	new_status = ifnull(payload.get("Payment_Made_Voucher_Status"),"");
                 	if(source_record_id == 0 && voucher_number == "")
                 	{
                 		resp.put("message","Source Record ID or Voucher Number missing.");
                 		return resp;
                 	}
                 	if(new_status == "")
                 	{
                 		resp.put("message","Payment Made Voucher Status missing.");
                 		return resp;
                 	}
                 	found = false;
                 	if(source_record_id != 0)
                 	{
                 		for each  rec in Payment_Made_Voucher[ID == source_record_id]
                 		{
                 			found = true;
                 			rec.Payment_Made_Voucher_Status=new_status;
                 			resp.put("ok",true);
                 			resp.put("message","Payment Made Voucher status updated.");
                 			resp.put("id",rec.ID);
                 			resp.put("status",new_status);
                 			break;
                 		}
                 	}
                 	if(found == false && voucher_number != "")
                 	{
                 		for each  rec in Payment_Made_Voucher[Payment_Made_Number == voucher_number]
                 		{
                 			found = true;
                 			rec.Payment_Made_Voucher_Status=new_status;
                 			resp.put("ok",true);
                 			resp.put("message","Payment Made Voucher status updated.");
                 			resp.put("id",rec.ID);
                 			resp.put("status",new_status);
                 			break;
                 		}
                 	}
                 	if(found == false)
                 	{
                 		resp.put("message","Payment Made Voucher not found.");
                 	}
                 	return resp;
                 }

map updatePaymentReceiptStatusFromPayment(map payload)
{
                 	resp = Map();
                 	resp.put("ok",false);
                 	source_record_id = payload.get("Source_Record_ID");
                 	new_status = ifnull(payload.get("Payment_Receipt_Voucher_Status"),"");
                 	if(source_record_id == null)
                 	{
                 		resp.put("message","Source Record ID is missing.");
                 		return resp;
                 	}
                 	if(new_status != "Pending" && new_status != "Confirmed")
                 	{
                 		resp.put("message","Invalid Payment Receipt Voucher status.");
                 		return resp;
                 	}
                 	receipt_rec = Payment_Receipt_Voucher[ID == source_record_id];
                 	if(receipt_rec.ID == null)
                 	{
                 		resp.put("message","Payment Receipt Voucher was not found.");
                 		return resp;
                 	}
                 	receipt_rec.Payment_Receipt_Voucher_Status=new_status;
                 	resp.put("ok",true);
                 	resp.put("status",new_status);
                 	resp.put("message","Payment Receipt Voucher status updated.");
                 	return resp;
                 }

