void update_invoice_payment(int invoice_id)
{
                 	total_allocated = 0.0;
                 	for each  rec in Payment_Receipt_Details[Invoice == invoice_id]
                 	{
                 		total_allocated = total_allocated + ifnull(rec.Amount_Allocated,0.0);
                 	}
                 	inv = Invoice[ID == invoice_id];
                 	if(inv.ID != null)
                 	{
                 		inv.Amount_Paid=total_allocated;
                 		inv.Balance_Due=ifnull(inv.Grand_Total,0.0) - total_allocated;
                 		if(inv.Balance_Due < 0)
                 		{
                 			inv.Balance_Due=0.0;
                 		}
                 		if(total_allocated <= 0)
                 		{
                 			inv.Payment_Status="Not Paid";
                 		}
                 		else if(inv.Balance_Due > 0)
                 		{
                 			inv.Payment_Status="Partially Paid";
                 		}
                 		else
                 		{
                 			inv.Payment_Status="Paid";
                 		}
                 	}
                 }

