void bill.update_parts_consumables_status(int bill_detail_id)
{
                 	// =====================================================
                 	// 1) VALIDATE BILL DETAIL ID
                 	// =====================================================
                 	if(bill_detail_id == null || bill_detail_id <= 0)
                 	{
                 		info "Bill Detail ID is required.";
                 		return;
                 	}
                 	// =====================================================
                 	// 2) LOAD BILL DETAILS RECORD
                 	// =====================================================
                 	bd = Bill_Details[ID == bill_detail_id];
                 	if(bd.ID == null)
                 	{
                 		info "Bill Details record was not found.";
                 		return;
                 	}
                 	// =====================================================
                 	// 3) ONLY RUN WHEN PARTS & CONSUMABLES IS SELECTED
                 	// =====================================================
                 	if(bd.Parts_Consumables == null)
                 	{
                 		info "No Parts & Consumables selected. Nothing to update.";
                 		return;
                 	}
                 	// =====================================================
                 	// 4) LOAD PARTS & CONSUMABLES RECORD
                 	// =====================================================
                 	pc = Parts_Consumables[ID == bd.Parts_Consumables];
                 	if(pc.ID == null)
                 	{
                 		info "Parts & Consumables record was not found.";
                 		return;
                 	}
                 	// =====================================================
                 	// 5) UPDATE PARTS & CONSUMABLES STATUS
                 	// =====================================================
                 	if(bd.Bill != null)
                 	{
                 		pc.Item_Status="Billed";
                 	}
                 	else
                 	{
                 		pc.Item_Status="Issued";
                 	}
                 	info "Parts & Consumables ID: " + pc.ID;
                 	info "Parts & Consumables status: " + pc.Item_Status;
                 	// =====================================================
                 	// 6) UPDATE LINKED WORK ORDER TASK
                 	// =====================================================
                 	if(pc.Work_Order_Task_Number == null)
                 	{
                 		info "Parts & Consumables has no linked Work Order Task.";
                 		return;
                 	}
                 	wot = Work_Order_Tasks[ID == pc.Work_Order_Task_Number];
                 	if(wot.ID == null)
                 	{
                 		info "Linked Work Order Task was not found.";
                 		return;
                 	}
                 	info "Work Order Task ID: " + wot.ID;
                 	info "Work Order Task status before: " + wot.Work_Order_Task_Status;
                 	// Only move to Invoiced when the Bill is selected
                 	if(bd.Bill != null)
                 	{
                 		wot.Work_Order_Task_Status="Invoiced";
                 		info "Work Order Task updated to Invoiced.";
                 	}
                 	else
                 	{
                 		// Restore it when the Bill is removed
                 		if(wot.Work_Order_Task_Status == "Invoiced")
                 		{
                 			wot.Work_Order_Task_Status="Invoicing";
                 			info "Work Order Task restored to Invoicing.";
                 		}
                 	}
                 }

map billing.backfillEmployeeBillDetailsBatch()
{
                 	result = Map();
                 	// =====================================================
                 	// CHANGE THIS AFTER EACH SUCCESSFUL BATCH
                 	// 1, 51, 101, 151, 201...
                 	// =====================================================
                 	start_from = 7213;
                 	batch_size = 40;
                 	end_at = start_from + batch_size - 1;
                 	loaded = 0;
                 	repaired = 0;
                 	no_bill_required = 0;
                 	failed = 0;
                 	last_voucher_id = 0;
                 	failed_vouchers = List();
                 	vouchersToProcess = Voucher_Register[Employee != null && Date_Time_In != null] sort by ID asc range from start_from to end_at;
                 	for each  voucherRecord in vouchersToProcess
                 	{
                 		loaded = loaded + 1;
                 		last_voucher_id = voucherRecord.ID;
                 		try 
                 		{
                 			syncResult = thisapp.billing.syncEmployeeBilling(voucherRecord.ID);
                 			if(syncResult != null && ifnull(syncResult.get("ok"),false) == true)
                 			{
                 				if(ifnull(syncResult.get("bill_record_ready"),false) == true)
                 				{
                 					repaired = repaired + 1;
                 				}
                 				else
                 				{
                 					no_bill_required = no_bill_required + 1;
                 				}
                 			}
                 			else
                 			{
                 				failed = failed + 1;
                 				failure = Map();
                 				failure.put("Voucher_ID",voucherRecord.ID);
                 				failure.put("Voucher_Number",ifnull(voucherRecord.Voucher_Number,""));
                 				if(syncResult != null)
                 				{
                 					failure.put("Message",ifnull(syncResult.get("message"),"Synchronization failed."));
                 				}
                 				else
                 				{
                 					failure.put("Message","No response was returned.");
                 				}
                 				failed_vouchers.add(failure);
                 			}
                 		}		catch (syncError)
                 		{
                 			failed = failed + 1;
                 			failure = Map();
                 			failure.put("Voucher_ID",voucherRecord.ID);
                 			failure.put("Voucher_Number",ifnull(voucherRecord.Voucher_Number,""));
                 			failure.put("Error",syncError.toString());
                 			failed_vouchers.add(failure);
                 		}
                 	}
                 	result.put("ok",true);
                 	result.put("message","Employee Bill Details repair batch completed.");
                 	result.put("start_from",start_from);
                 	result.put("end_at",end_at);
                 	result.put("batch_size",batch_size);
                 	result.put("loaded",loaded);
                 	result.put("repaired",repaired);
                 	result.put("no_bill_required",no_bill_required);
                 	result.put("failed",failed);
                 	result.put("last_voucher_id",last_voucher_id);
                 	result.put("next_start_from",start_from + batch_size);
                 	result.put("last_batch",loaded < batch_size);
                 	result.put("failed_vouchers",failed_vouchers);
                 	info result;
                 	return result;
                 }

