                 			{
                 				empNumber = voucherRecord.Employee.Employee_Number.toString();
                 				employee_number_value = voucherRecord.Employee.Employee_Number;
                 			}
                 			displayVendorName = empName;
                 			if(empNumber != "")
                 			{
                 				displayVendorName = empName + " - " + empNumber;
                 			}
                 			billName = displayVendorName;
                 			dailyAllowance = 0.0;
                 			weeklyAllowance = 0.0;
                 			monthlySalary = 0.0;
                 			allowanceInput = Map();
