                 				{
                 					if(vr.Date_Time_In.toDate() == vDate)
                 					{
                 						includeVoucher = true;
                 					}
                 				}
                 				if(includeVoucher == true)
                 				{
                 					vrNumber = ifnull(vr.Voucher_Number,"").trim();
                 					vrType = "";
                 					if(vr.Voucher_Type != null)
                 					{
                 						vrType = ifnull(vr.Voucher_Type.Voucher_Type,"").trim();
                 					}
                 					if(vrType == "")
                 					{
                 						vrType = ifnull(vr.Display_Name_Voucher_Type,"").trim();
                 					}
                 					if(vrNumber != "")
                 					{
                 						if(dailyVoucherReference == "")
                 						{
                 							dailyVoucherReference = vrNumber;
                 						}
                 						else
                 						{
                 							if(!dailyVoucherReference.contains(vrNumber))
                 							{
                 								dailyVoucherReference = dailyVoucherReference + ", " + vrNumber;
                 							}
                 						}
                 						voucherLine = vrNumber;
                 						if(vrType != "")
                 						{
                 							voucherLine = voucherLine + " - " + vrType;
                 						}
                 						if(dailyVoucherDetails == "")
                 						{
                 							dailyVoucherDetails = voucherLine;
                 						}
                 						else
                 						{
                 							if(!dailyVoucherDetails.contains(voucherLine))
                 							{
                 								dailyVoucherDetails = dailyVoucherDetails + "\n" + voucherLine;
                 							}
                 						}
                 					}
                 				}
                 			}
                 			if(dailyVoucherReference == "")
                 			{
                 				dailyVoucherReference = ifnull(voucherRecord.Voucher_Number,"");
                 			}
                 			if(dailyVoucherDetails == "")
                 			{
                 				dailyVoucherDetails = ifnull(voucherRecord.Voucher_Number,"");
                 				currentVoucherType = "";
                 				if(voucherRecord.Voucher_Type != null)
                 				{
                 					currentVoucherType = ifnull(voucherRecord.Voucher_Type.Voucher_Type,"").trim();
                 				}
                 				if(currentVoucherType == "")
                 				{
                 					currentVoucherType = ifnull(voucherRecord.Display_Name_Voucher_Type,"").trim();
                 				}
                 				if(currentVoucherType != "")
                 				{
                 					dailyVoucherDetails = dailyVoucherDetails + " - " + currentVoucherType;
                 				}
                 			}
                 			// =====================================================
                 			// DAILY / WEEKLY ALLOWANCE
                 			// =====================================================
                 			if(dailyAllowance > 0 || weeklyAllowance > 0)
                 			{
                 				periodResp = thisapp.billing.getEmployeeBillPeriod(vDate,"Weekly Payment");
                 				billDate = periodResp.get("Bill_Date");
                 				billNumber = periodResp.get("Bill_Number");
                 				existingBill = Bill[Employee_Vendor == employee_id && Bill_Number == billNumber && Bill_Type == "Employee Bill"];
                 				employeeBillID = null;
                 				if(existingBill.ID != null)
                 				{
                 					employeeBillID = existingBill.ID;
                 					existingBill.Bill_Date=billDate;
                 					existingBill.Bill_Name=billName;
                 					existingBill.Display_Name_Vendor=displayVendorName;
                 					existingBill.Employee_Vendor=employee_id;
                 					existingBill.Bill_Type="Employee Bill";
                 				}
                 				else
                 				{
                 					employeeBillID = insert into Bill
                 					[
                 						Bill_Date=billDate
                 						Bill_Type="Employee Bill"
                 						Employee_Vendor=employee_id
                 						Display_Name_Vendor=displayVendorName
                 						Bill_Name=billName
                 						Bill_Number=billNumber
                 						Bill_Status="Draft"
                 						Payment_Status="Not Paid"
                 						Added_User=zoho.loginuser
                 					];
                 				}
                 				if(employeeBillID != null)
                 				{
                 					weekDateKeys = List();
                 					weekDates = List();
                 					weekVoucherReference = "";
                 					weekVoucherDetails = "";
                 					weekStartDate = billDate.addDay(-7);
                 					weekEndDate = billDate;
                 					employeeWeekVouchers = Voucher_Register[Employee == employee_id && Date_Time_In >= weekStartDate && Date_Time_In < weekEndDate];
                 					for each  weekVoucher in employeeWeekVouchers
                 					{
                 						if(weekVoucher.Date_Time_In != null)
                 						{
                 							weekVoucherDate = weekVoucher.Date_Time_In.toDate();
                 							weekDateKey = weekVoucherDate.toString("yyyy-MM-dd");
                 							if(!weekDateKeys.contains(weekDateKey))
                 							{
                 								weekDateKeys.add(weekDateKey);
                 								weekDates.add(weekVoucherDate);
                 							}
                 							weekVoucherNumber = ifnull(weekVoucher.Voucher_Number,"").trim();
                 							weekVoucherType = "";
                 							if(weekVoucher.Voucher_Type != null)
                 							{
                 								weekVoucherType = ifnull(weekVoucher.Voucher_Type.Voucher_Type,"").trim();
                 							}
                 							if(weekVoucherType == "")
                 							{
                 								weekVoucherType = ifnull(weekVoucher.Display_Name_Voucher_Type,"").trim();
                 							}
                 							if(weekVoucherNumber != "")
                 							{
                 								if(weekVoucherReference == "")
                 								{
                 									weekVoucherReference = weekVoucherNumber;
                 								}
                 								else if(!weekVoucherReference.contains(weekVoucherNumber))
                 								{
                 									weekVoucherReference = weekVoucherReference + ", " + weekVoucherNumber;
                 								}
                 								weekVoucherLine = weekVoucherDate.toString("dd-MMM-yyyy") + " - " + weekVoucherNumber;
                 								if(weekVoucherType != "")
                 								{
                 									weekVoucherLine = weekVoucherLine + " - " + weekVoucherType;
                 								}
                 								if(weekVoucherDetails == "")
                 								{
                 									weekVoucherDetails = weekVoucherLine;
                 								}
                 								else if(!weekVoucherDetails.contains(weekVoucherLine))
                 								{
                 									weekVoucherDetails = weekVoucherDetails + "\n" + weekVoucherLine;
                 								}
                 							}
                 						}
                 					}
                 					qualifyingDateCount = weekDateKeys.size();
                 					// =================================================
                 					// DAILY ALLOWANCE
                 					// =================================================
                 					if(dailyAllowance > 0)
                 					{
                 						for each  workDate in weekDates
                 						{
                 							workDateVoucherReference = "";
                 							workDateVoucherDetails = "";
                 							workDateSource = sourceVal;
                 							workDateAccount = accountVal;
                 							workDateSite = siteVal;
                 							workDateSourceRecordID = voucherRecord.ID;
                 							for each  dateVoucher in employeeWeekVouchers
                 							{
                 								if(dateVoucher.Date_Time_In != null && dateVoucher.Date_Time_In.toDate() == workDate)
                 								{
                 									dateVoucherNumber = ifnull(dateVoucher.Voucher_Number,"").trim();
                 									dateVoucherType = "";
                 									if(dateVoucher.Voucher_Type != null)
                 									{
                 										dateVoucherType = ifnull(dateVoucher.Voucher_Type.Voucher_Type,"").trim();
                 									}
                 									if(dateVoucherType == "")
                 									{
                 										dateVoucherType = ifnull(dateVoucher.Display_Name_Voucher_Type,"").trim();
                 									}
                 									if(dateVoucherNumber != "")
                 									{
                 										if(workDateVoucherReference == "")
                 										{
                 											workDateVoucherReference = dateVoucherNumber;
                 										}
                 										else if(!workDateVoucherReference.contains(dateVoucherNumber))
                 										{
                 											workDateVoucherReference = workDateVoucherReference + ", " + dateVoucherNumber;
                 										}
                 										dateVoucherLine = dateVoucherNumber;
                 										if(dateVoucherType != "")
                 										{
                 											dateVoucherLine = dateVoucherLine + " - " + dateVoucherType;
                 										}
                 										if(workDateVoucherDetails == "")
                 										{
                 											workDateVoucherDetails = dateVoucherLine;
                 										}
                 										else if(!workDateVoucherDetails.contains(dateVoucherLine))
                 										{
                 											workDateVoucherDetails = workDateVoucherDetails + "\n" + dateVoucherLine;
                 										}
                 									}
                 									workDateSource = ifnull(dateVoucher.Display_Name_Employee,"").trim();
                 									workDateSite = ifnull(dateVoucher.Display_Name_Site,"").trim();
                 									workDateAccount = workDateSite;
                 									if(workDateAccount == "")
                 									{
                 										workDateAccount = "Unassigned Account";
                 									}
                 									workDateSourceRecordID = dateVoucher.ID;
                 								}
                 							}
                 							dailyAllowanceText = "Allowance Type: Daily Allowance";
                 							dailyAllowanceText = dailyAllowanceText + "\nDate: " + workDate.toString("dd-MMM-yyyy");
                 							dailyAllowanceText = dailyAllowanceText + "\nEmployee: " + displayVendorName;
                 							dailyAllowanceText = dailyAllowanceText + "\nSite: " + workDateSite;
                 							dailyAllowanceText = dailyAllowanceText + "\nWeek: " + billNumber;
                 							dailyAllowanceText = dailyAllowanceText + "\nDaily Allowance: " + dailyAllowance.toString();
                 							dailyAllowanceText = dailyAllowanceText + "\n\nVouchers:";
                 							dailyAllowanceText = dailyAllowanceText + "\n" + workDateVoucherDetails;
                 							existingDateDetails = Bill_Details[Bill == employeeBillID && Details_Date == workDate && Expense_Type == "Weekly Payment"];
                 							dailyDetailFound = false;
                 							for each  dateBD in existingDateDetails
                 							{
                 								dateBDText = ifnull(dateBD.Details,"");
                 								if(dateBDText.contains("Allowance Type: Weekly Allowance") == false && dailyDetailFound == false)
                 								{
                 									dateBD.Reference=workDateVoucherReference;
                 									dateBD.Details=dailyAllowanceText;
                 									dateBD.Quantity=1.00;
                 									dateBD.Rate=dailyAllowance;
                 									dateBD.Source=workDateSource;
                 									dateBD.Account=workDateAccount;
                 									dateBD.Current_Site=workDateSite;
                 									dateBD.Source_Record_ID=workDateSourceRecordID;
                 									dateBD.Display_Name_Bill=billName + " - " + billNumber;
                 									dailyDetailFound = true;
                 									bill_record_ready = true;
                 								}
                 							}
                 							if(dailyDetailFound == false)
                 							{
                 								newDailyDetailID = insert into Bill_Details
                 								[
                 									Bill=employeeBillID
                 									Display_Name_Bill=billName + " - " + billNumber
                 									Details_Date=workDate
                 									Source=workDateSource
                 									Reference=workDateVoucherReference
                 									Details=dailyAllowanceText
                 									Expense_Type="Weekly Payment"
                 									Quantity=1.00
                 									Rate=dailyAllowance
                 									Account=workDateAccount
                 									Current_Site=workDateSite
                 									Source_Record_ID=workDateSourceRecordID
                 									Source_Form="Masaka Site Management - Voucher Register"
                 									Bill_Details_Status="Draft"
                 									Added_User=zoho.loginuser
                 								];
                 								if(newDailyDetailID != null)
                 								{
                 									bill_record_ready = true;
                 								}
                 							}
                 						}
                 					}
                 					// =================================================
                 					// WEEKLY ALLOWANCE
                 					// =================================================
                 					if(weeklyAllowance > 0 && qualifyingDateCount > 0)
                 					{
                 						weeklyCalculatedRate = weeklyAllowance / qualifyingDateCount;
                 						weeklyAllowanceText = "Allowance Type: Weekly Allowance";
                 						weeklyAllowanceText = weeklyAllowanceText + "\nEmployee: " + displayVendorName;
                 						weeklyAllowanceText = weeklyAllowanceText + "\nWeek: " + billNumber;
                 						weeklyAllowanceText = weeklyAllowanceText + "\nQualifying Dates: " + qualifyingDateCount.toString();
                 						weeklyAllowanceText = weeklyAllowanceText + "\nFixed Weekly Allowance: " + weeklyAllowance.toString();
                 						weeklyAllowanceText = weeklyAllowanceText + "\n\nDaily Records / Vouchers:";
                 						weeklyAllowanceText = weeklyAllowanceText + "\n" + weekVoucherDetails;
                 						allWeeklyPaymentDetails = Bill_Details[Bill == employeeBillID && Expense_Type == "Weekly Payment"];
                 						weeklyAllowanceFound = false;
                 						for each  weeklyAllowanceBD in allWeeklyPaymentDetails
                 						{
                 							weeklyAllowanceBDText = ifnull(weeklyAllowanceBD.Details,"");
                 							if(weeklyAllowanceBDText.contains("Allowance Type: Weekly Allowance") && weeklyAllowanceFound == false)
                 							{
                 								weeklyAllowanceBD.Details_Date=billDate;
                 								weeklyAllowanceBD.Reference=weekVoucherReference;
                 								weeklyAllowanceBD.Details=weeklyAllowanceText;
                 								weeklyAllowanceBD.Quantity=qualifyingDateCount;
                 								weeklyAllowanceBD.Rate=weeklyCalculatedRate;
                 								weeklyAllowanceBD.Source=sourceVal;
                 								weeklyAllowanceBD.Account=accountVal;
                 								weeklyAllowanceBD.Current_Site=siteVal;
                 								weeklyAllowanceBD.Source_Record_ID=voucherRecord.ID;
                 								weeklyAllowanceBD.Display_Name_Bill=billName + " - " + billNumber;
                 								weeklyAllowanceFound = true;
                 								bill_record_ready = true;
                 							}
                 						}
                 						if(weeklyAllowanceFound == false)
                 						{
                 							newWeeklyAllowanceDetailID = insert into Bill_Details
                 							[
                 								Bill=employeeBillID
                 								Display_Name_Bill=billName + " - " + billNumber
                 								Details_Date=billDate
                 								Source=sourceVal
                 								Reference=weekVoucherReference
                 								Details=weeklyAllowanceText
                 								Expense_Type="Weekly Payment"
                 								Quantity=qualifyingDateCount
                 								Rate=weeklyCalculatedRate
                 								Account=accountVal
                 								Current_Site=siteVal
                 								Source_Record_ID=voucherRecord.ID
                 								Source_Form="Masaka Site Management - Voucher Register"
                 								Bill_Details_Status="Draft"
                 								Added_User=zoho.loginuser
                 							];
                 							if(newWeeklyAllowanceDetailID != null)
                 							{
                 								bill_record_ready = true;
                 							}
                 						}
                 					}
                 					totalsResp = thisapp.billing.recalculateBillTotals(employeeBillID);
                 					info totalsResp;
                 				}
                 			}
                 			// =====================================================
                 			// DETERMINE SPECIAL MONTHLY EMPLOYEE
                 			// =====================================================
                 			specialMonthlyEmployee = false;
                 			if(employee_number_value >= 10000 && employee_number_value <= 20000)
                 			{
                 				specialMonthlyEmployee = true;
                 			}
                 			// =====================================================
                 			// NORMAL MONTHLY EMPLOYEE
                 			// DO NOT CHANGE THIS LOGIC
                 			// =====================================================
                 			if(monthlySalary > 0 && specialMonthlyEmployee == false)
                 			{
                 				monthlyPeriodResp = thisapp.billing.getEmployeeBillPeriod(vDate,"Monthly Payment");
                 				monthlyBillDate = monthlyPeriodResp.get("Bill_Date");
                 				monthlyReference = monthlyPeriodResp.get("Bill_Number");
                 				existingMonthlyBill = Bill[Employee_Vendor == employee_id && Bill_Number == monthlyReference && Bill_Type == "Employee Bill"];
                 				monthlyBillID = null;
                 				if(existingMonthlyBill.ID != null)
                 				{
                 					monthlyBillID = existingMonthlyBill.ID;
                 					existingMonthlyBill.Bill_Date=monthlyBillDate;
                 					existingMonthlyBill.Bill_Type="Employee Bill";
                 					existingMonthlyBill.Employee_Vendor=employee_id;
                 					existingMonthlyBill.Display_Name_Vendor=displayVendorName;
                 					existingMonthlyBill.Bill_Name=billName;
                 					existingMonthlyBill.Bill_Number=monthlyReference;
                 				}
                 				else
                 				{
                 					monthlyBillID = insert into Bill
                 					[
                 						Bill_Date=monthlyBillDate
                 						Bill_Type="Employee Bill"
                 						Employee_Vendor=employee_id
                 						Display_Name_Vendor=displayVendorName
                 						Bill_Name=billName
                 						Bill_Number=monthlyReference
                 						Bill_Status="Draft"
                 						Payment_Status="Not Paid"
                 						Added_User=zoho.loginuser
                 					];
                 				}
                 				if(monthlyBillID != null)
                 				{
                 					existingDailyMonthly = Bill_Details[Bill == monthlyBillID && Details_Date == vDate && Expense_Type == "Monthly Payment"];
                 					monthlyDetailText = "";
                 					monthlyDetailText = "Date: " + vDate.toString("dd-MMM-yyyy");
                 					monthlyDetailText = monthlyDetailText + "\nEmployee: " + displayVendorName;
                 					monthlyDetailText = monthlyDetailText + "\nSite: " + siteVal;
                 					monthlyDetailText = monthlyDetailText + "\nMonth: " + monthlyReference;
                 					monthlyDetailText = monthlyDetailText + "\nMonthly Salary: " + monthlySalary.toString();
                 					monthlyDetailText = monthlyDetailText + "\n\nVouchers:";
                 					monthlyDetailText = monthlyDetailText + "\n" + dailyVoucherDetails;
                 					if(existingDailyMonthly.count() == 0)
                 					{
                 						newMonthlyDetailID = insert into Bill_Details
                 						[
                 							Bill=monthlyBillID
                 							Display_Name_Bill=billName + " - " + monthlyReference
                 							Details_Date=vDate
                 							Source=sourceVal
                 							Reference=dailyVoucherReference
                 							Details=monthlyDetailText
                 							Expense_Type="Monthly Payment"
                 							Quantity=1.00
                 							Account=accountVal
                 							Current_Site=siteVal
                 							Source_Record_ID=voucherRecord.ID
                 							Source_Form="Masaka Site Management - Voucher Register"
                 							Bill_Details_Status="Draft"
                 							Added_User=zoho.loginuser
                 						];
                 						if(newMonthlyDetailID != null)
                 						{
                 							bill_record_ready = true;
                 						}
                 					}
                 					else
                 					{
                 						for each  monthlyBD in existingDailyMonthly
                 						{
                 							monthlyBD.Reference=dailyVoucherReference;
                 							monthlyBD.Details=monthlyDetailText;
                 							monthlyBD.Quantity=1.00;
                 							monthlyBD.Source=sourceVal;
                 							monthlyBD.Account=accountVal;
                 							monthlyBD.Current_Site=siteVal;
                 							monthlyBD.Display_Name_Bill=billName + " - " + monthlyReference;
                 							bill_record_ready = true;
                 							break;
                 						}
                 					}
                 				}
                 			}
                 			if(specialMonthlyEmployee == true)
                 			{
                 				specialEmployees = List();
                 				supervisorVoucherList = List();
                 				specialDetailText = "";
                 				specialEmployeeCount = 0;
                 				siteVouchers = Voucher_Register[Display_Name_Site == siteVal && Date_Time_In >= vDate && Date_Time_In < nextVoucherDate];
                 				for each  siteVoucher in siteVouchers
                 				{
                 					isSameDay = false;
                 					if(siteVoucher.Date_Time_In != null)
                 					{
                 						if(siteVoucher.Date_Time_In.toDate() == vDate)
                 						{
                 							isSameDay = true;
                 						}
                 					}
                 					if(isSameDay == true && siteVoucher.Employee != null)
                 					{
                 						thisEmployeeNumber = 0;
                 						if(siteVoucher.Employee.Employee_Number != null)
                 						{
                 							thisEmployeeNumber = siteVoucher.Employee.Employee_Number;
                 						}
                 						if(thisEmployeeNumber >= 10000 && thisEmployeeNumber <= 20000)
                 						{
                 							thisEmployeeID = siteVoucher.Employee.ID;
                 							thisEmployeeKey = thisEmployeeID.toString();
                 							thisEmployeeName = ifnull(siteVoucher.Employee.Employee_Name,"").trim();
                 							thisEmployeeDisplay = thisEmployeeName;
                 							if(thisEmployeeNumber > 0)
                 							{
                 								thisEmployeeDisplay = thisEmployeeName + " - " + thisEmployeeNumber.toString();
                 							}
                 							if(!specialEmployees.contains(thisEmployeeKey))
                 							{
                 								specialEmployees.add(thisEmployeeKey);
                 								specialEmployeeCount = specialEmployeeCount + 1;
                 								if(specialDetailText != "")
                 								{
                 									specialDetailText = specialDetailText + "\n";
                 								}
                 								specialDetailText = specialDetailText + "\n" + thisEmployeeDisplay;
                 							}
                 							thisVoucherNumber = ifnull(siteVoucher.Voucher_Number,"").trim();
                 							thisVoucherType = "";
                 							if(siteVoucher.Voucher_Type != null)
                 							{
                 								thisVoucherType = ifnull(siteVoucher.Voucher_Type.Voucher_Type,"").trim();
                 							}
                 							if(thisVoucherType == "")
                 							{
                 								thisVoucherType = ifnull(siteVoucher.Display_Name_Voucher_Type,"").trim();
                 							}
                 							if(thisVoucherNumber != "")
                 							{
                 								thisVoucherLine = "  - " + thisVoucherNumber;
                 								if(thisVoucherType != "")
                 								{
                 									thisVoucherLine = thisVoucherLine + " - " + thisVoucherType;
                 								}
                 								if(!specialDetailText.contains(thisVoucherLine))
                 								{
                 									specialDetailText = specialDetailText + "\n" + thisVoucherLine;
                 								}
                 							}
                 							thisSupervisorVoucher = ifnull(siteVoucher.Display_Name_Issued_By,"").trim();
                 							if(thisSupervisorVoucher != "")
                 							{
                 								if(!supervisorVoucherList.contains(thisSupervisorVoucher))
                 								{
                 									supervisorVoucherList.add(thisSupervisorVoucher);
                 								}
                 							}
                 						}
                 					}
                 				}
                 				if(specialEmployeeCount > 0)
                 				{
                 					specialReference = "";
                 					for each  supervisorVoucher in supervisorVoucherList
                 					{
                 						if(specialReference == "")
                 						{
                 							specialReference = supervisorVoucher;
                 						}
                 						else
                 						{
                 							specialReference = specialReference + ", " + supervisorVoucher;
                 						}
                 					}
                 					specialMonthlyText = "";
                 					specialMonthlyText = "Date: " + vDate.toString("dd-MMM-yyyy");
                 					specialMonthlyText = specialMonthlyText + "\nSite: " + siteVal;
                 					specialMonthlyText = specialMonthlyText + "\nEmployees: " + specialEmployeeCount.toString();
                 					specialMonthlyText = specialMonthlyText + "\n\nEmployees / Vouchers:";
                 					specialMonthlyText = specialMonthlyText + specialDetailText;
                 					possibleSpecialMonthly = Bill_Details[Details_Date == vDate && Current_Site == siteVal && Expense_Type == "Monthly Payment" && Source_Form == "Masaka Site Management - Voucher Register"];
                 					specialRecordFound = false;
                 					specialRecordID = null;
                 					for each  existingBD in possibleSpecialMonthly
                 					{
                 						existingDetailsText = ifnull(existingBD.Details,"");
                 						if(existingDetailsText.contains("Employees / Vouchers:"))
                 						{
                 							specialRecordFound = true;
                 							specialRecordID = existingBD.ID;
                 							break;
                 						}
                 					}
                 					if(specialRecordFound == false)
                 					{
                 						newSpecialMonthlyDetailID = insert into Bill_Details
                 						[
                 							Details_Date=vDate
                 							Source=siteVal
                 							Reference=specialReference
                 							Details=specialMonthlyText
                 							Expense_Type="Monthly Payment"
                 							Quantity=specialEmployeeCount
                 							Account=accountVal
                 							Current_Site=siteVal
                 							Source_Record_ID=voucherRecord.ID
                 							Source_Form="Masaka Site Management - Voucher Register"
                 							Bill_Details_Status="Draft"
                 							Added_User=zoho.loginuser
                 						];
                 						if(newSpecialMonthlyDetailID != null)
                 						{
                 							bill_record_ready = true;
                 							info "==============================================";
                 							info "SPECIAL MONTHLY CREATED";
                 							info "Bill Details ID: " + newSpecialMonthlyDetailID;
                 							info "Source Record ID: " + voucherRecord.ID;
                 							info "Date: " + vDate;
                 							info "Site: " + siteVal;
                 							info "Employees: " + specialEmployeeCount;
                 							info "==============================================";
                 						}
                 					}
                 					else
                 					{
                 						specialBD = Bill_Details[ID == specialRecordID];
                 						if(specialBD.ID != null)
                 						{
                 							specialBD.Reference=specialReference;
                 							specialBD.Details=specialMonthlyText;
                 							specialBD.Quantity=specialEmployeeCount;
                 							specialBD.Account=accountVal;
                 							specialBD.Current_Site=siteVal;
                 							specialBD.Source=siteVal;
                 							specialBD.Source_Record_ID=voucherRecord.ID;
                 							bill_record_ready = true;
                 							info "==============================================";
                 							info "SPECIAL MONTHLY UPDATED";
                 							info "Bill Details ID: " + specialBD.ID;
                 							info "Source Record ID: " + voucherRecord.ID;
                 							info "Date: " + vDate;
                 							info "Site: " + siteVal;
                 							info "Employees: " + specialEmployeeCount;
                 							info "==============================================";
                 						}
                 					}
                 				}
                 			}
                 		}
                 	}
                 	// =====================================================
                 	// RESPONSE
                 	// =====================================================
                 	syncResponse.put("bill_record_ready",bill_record_ready);
                 	if(voucherRecord.ID == null)
                 	{
                 		syncResponse.put("message","Voucher Register record was not found.");
                 	}
                 	else if(voucherRecord.Employee == null)
                 	{
                 		syncResponse.put("message","The voucher has no employee.");
                 	}
                 	else
                 	{
                 		syncResponse.put("ok",true);
                 		syncResponse.put("message","Employee billing synchronized successfully.");
                 		syncResponse.put("voucher_id",voucher_id);
                 	}
                 	return syncResponse;
                 }

void card.generate_gate_pass_card(int sales_voucher_id)
{
                 	if(sales_voucher_id == null || sales_voucher_id <= 0)
                 	{
                 		info "FAILED: Sales Voucher ID is required.";
                 		return;
                 	}
                 	sales_rec = Sales_Voucher[ID == sales_voucher_id];
                 	if(sales_rec.ID == null)
                 	{
                 		info "FAILED: Sales Voucher record was not found.";
                 		return;
                 	}
                 	current_gate_pass = ifnull(sales_rec.Gate_Pass_Card,"").trim();
                 	if(current_gate_pass != "")
                 	{
                 		info "SKIPPED: Gate Pass Card already exists: " + current_gate_pass;
                 		return;
                 	}
                 	site_display = ifnull(sales_rec.Display_Name_Site,"").trim();
                 	if(site_display == "")
                 	{
                 		info "FAILED: Display Name Site is required on Sales Voucher.";
                 		return;
                 	}
                 	seq = Sequences[Display_Name_Site == site_display && Status == "Active"];
                 	if(seq.count() == 0)
                 	{
                 		info "FAILED: No active sequence found for: " + site_display;
                 		return;
                 	}
                 	if(seq.count() > 1)
                 	{
                 		info "FAILED: Multiple active sequences found for: " + site_display;
                 		return;
                 	}
                 	prefix_txt = ifnull(seq.Sequence_Key,"").trim().toUpperCase();
                 	next_no = ifnull(seq.Next_Number,1);
                 	max_no = seq.Max_Number;
                 	if(prefix_txt == "")
                 	{
                 		info "FAILED: Sequence Key is required.";
                 		return;
                 	}
                 	if(prefix_txt.contains(" "))
                 	{
                 		info "FAILED: Sequence Key must not contain spaces.";
                 		return;
                 	}
                 	if(next_no <= 0)
                 	{
                 		info "FAILED: Next Number must be greater than zero.";
                 		return;
                 	}
                 	if(max_no == null || max_no <= 0)
                 	{
                 		info "FAILED: Max Number must be greater than zero.";
                 		return;
                 	}
                 	if(next_no > max_no)
                 	{
                 		info "FAILED: Gate-pass sequence has reached its maximum number.";
                 		return;
                 	}
                 	num_txt = next_no.toString();
                 	if(next_no < 10)
                 	{
                 		num_txt = "00" + num_txt;
                 	}
                 	else if(next_no < 100)
                 	{
                 		num_txt = "0" + num_txt;
                 	}
                 	gate_pass_no = prefix_txt + num_txt;
                 	existing_pass = Sales_Voucher[Gate_Pass_Card == gate_pass_no && ID != sales_rec.ID];
                 	if(existing_pass.count() > 0)
                 	{
                 		info "FAILED: Gate Pass Card already exists: " + gate_pass_no;
                 		return;
                 	}
                 	sales_rec.Gate_Pass_Card=gate_pass_no;
                 	seq.Next_Number=next_no + 1;
                 	info "SUCCESS: Gate Pass Card generated: " + gate_pass_no;
                 	info "Site: " + site_display;
                 	info "Next Number is now: " + seq.Next_Number;
                 }

