void card.generate_sand_sales_card(int sales_voucher_id)
{
                 	if(sales_voucher_id == null || sales_voucher_id <= 0)
                 	{
                 		info "FAILED: Sales Voucher ID is required.";
                 		return;
                 	}
                 	sales_rec = Sales_Voucher[ID == sales_voucher_id];
                 	if(sales_rec.ID == null)
                 	{
                 		info "FAILED: Sales Voucher record was not found.";
                 		return;
                 	}
                 	sales_type = ifnull(sales_rec.Sales_Type,"").trim();
                 	if(sales_type != "Sand Sales")
                 	{
                 		info "SKIPPED: Sales Type is " + sales_type;
                 		return;
                 	}
                 	current_card_number = ifnull(sales_rec.Card_Number,"").trim();
                 	if(current_card_number != "")
                 	{
                 		info "SKIPPED: Card Number already exists: " + current_card_number;
                 		return;
                 	}
                 	site_display = ifnull(sales_rec.Display_Name_Site,"").trim();
                 	info "Sales Voucher Site: " + site_display;
                 	if(site_display == "")
                 	{
                 		info "FAILED: Display Name Site is empty on Sales Voucher.";
                 		return;
                 	}
                 	seq = Card_Sequence[Display_Name_Site == site_display && Card_Status == "Active"];
                 	if(seq.ID == null)
                 	{
                 		info "FAILED: No active Card Sequence found for: " + site_display;
                 		return;
                 	}
                 	info "Card Sequence found: " + seq.ID;
                 	prefix_txt = ifnull(seq.Prefix,"").trim().toUpperCase();
                 	next_no = ifnull(seq.Next_Number,1);
                 	rate_cbm = ifnull(seq.Rate_per_CBM,0.0);
                 	if(prefix_txt == "")
                 	{
                 		info "FAILED: Card Sequence Prefix is empty.";
                 		return;
                 	}
                 	if(next_no <= 0)
                 	{
                 		next_no = 1;
                 	}
                 	if(next_no > 999)
                 	{
                 		info "FAILED: Card Sequence has exceeded 999.";
                 		return;
                 	}
                 	// 001 to 999
                 	num_txt = next_no.toString();
                 	if(next_no < 10)
                 	{
                 		num_txt = "00" + num_txt;
                 	}
                 	else if(next_no < 100)
                 	{
                 		num_txt = "0" + num_txt;
                 	}
                 	card_no = prefix_txt + num_txt;
                 	existing_card = Sales_Voucher[Card_Number == card_no && ID != sales_rec.ID];
                 	if(existing_card.ID != null)
                 	{
                 		info "FAILED: Card Number already exists: " + card_no;
                 		return;
                 	}
                 	sales_rec.Card_Number=card_no;
                 	sales_rec.Sales_Voucher_Number=card_no;
                 	seq.Next_Number=next_no + 1;
                 	info "SUCCESS: Card Number generated: " + card_no;
                 	info "Rate per CBM: " + rate_cbm;
                 	info "Next Number is now: " + seq.Next_Number;
                 }

void customer.update_customer_performance(int customer_id)
{
                 	if(customer_id == null)
                 	{
                 		return;
                 	}
                 	customer_rec = Customer_Register[ID == customer_id];
                 	if(customer_rec.ID == null)
                 	{
                 		return;
                 	}
                 	valid_sales = Sales_Voucher[Customer == customer_id && Cancel_Voucher != true && Payment_Status != "Cancelled"];
                 	total_sales_orders = valid_sales.count();
                 	total_revenue = ifnull(valid_sales.sum(Grand_Total),0.0);
                 	last_purchase_date = valid_sales.maximum(Sales_Voucher_Date);
                 	valid_payments = Payment_Receipt_Voucher[Customer == customer_id && Payment_Receipt_Voucher_Status != "Cancelled"];
                 	total_paid = ifnull(valid_payments.sum(Total_Amount_Received),0.0);
                 	credit_sales = Sales_Voucher[Customer == customer_id && Payment_Status == "Credit" && Cancel_Voucher != true];
                 	outstanding_balance = ifnull(credit_sales.sum(Grand_Total),0.0);
                 	if(outstanding_balance < 0)
                 	{
                 		outstanding_balance = 0.0;
                 	}
                 	credit_limit = ifnull(customer_rec.Credit_Limit,0.0);
                 	available_credit = credit_limit - outstanding_balance;
                 	if(available_credit < 0)
                 	{
                 		available_credit = 0.0;
                 	}
                 	credit_status = "Not Applicable";
                 	if(ifnull(customer_rec.Customer_Type,"") == "Credit")
                 	{
                 		if(customer_rec.Credit_Allowed != true)
                 		{
                 			credit_status = "On Hold";
                 		}
                 		else if(credit_limit > 0 && outstanding_balance >= credit_limit)
                 		{
                 			credit_status = "Limit Reached";
                 		}
                 		else
                 		{
                 			credit_status = "Good Standing";
                 		}
                 	}
                 	customer_rec.Total_Sales_Orders=total_sales_orders;
                 	customer_rec.Total_Revenue=total_revenue;
                 	customer_rec.Total_Paid=total_paid;
                 	customer_rec.Outstanding_Balance=outstanding_balance;
                 	customer_rec.Current_Outstanding_Balance=outstanding_balance;
                 	customer_rec.Last_Purchase_Date=last_purchase_date;
                 	customer_rec.Available_Credit=available_credit;
                 	customer_rec.Credit_Status=credit_status;
                 }

map labour.recalculate_other_machines_labour(int employee_id, string employee_display_name, date work_date)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("employee_id",employee_id);
                 	result.put("employee",employee_display_name);
                 	result.put("monthly_salary",0.0);
                 	result.put("working_days",0);
                 	result.put("daily_labour",0.0);
                 	result.put("machine_lines_updated",0);
                 	result.put("calculated_labour_total",0.0);
                 	if(employee_id == null)
                 	{
                 		result.put("message","Employee ID is required.");
                 		return result;
                 	}
                 	employee_display_name = ifnull(employee_display_name,"").trim();
                 	if(work_date == null)
                 	{
                 		work_date = zoho.currentdate;
                 	}
                 	salary_result = employee_management.employee.get_employee_salary_details(employee_id,work_date);
                 	if(salary_result == null)
                 	{
                 		result.put("message","Employee Management returned no salary information.");
                 		return result;
                 	}
                 	if(ifnull(salary_result.get("ok"),false) != true)
                 	{
                 		result.put("message",ifnull(salary_result.get("message"),"Employee salary could not be retrieved."));
                 		return result;
                 	}
                 	monthly_salary = ifnull(salary_result.get("monthly_salary"),0.0);
                 	if(monthly_salary <= 0)
                 	{
                 		result.put("message","The employee monthly salary must be greater than zero.");
                 		return result;
                 	}
                 	result.put("monthly_salary",monthly_salary);
                 	month_number = work_date.getMonth();
                 	year_number = work_date.getYear();
                 	month_text = month_number.toString();
                 	if(month_number < 10)
                 	{
                 		month_text = "0" + month_number;
                 	}
                 	month_start_text = "01-" + month_text + "-" + year_number.toString();
                 	month_start = month_start_text.toDate("dd-MM-yyyy");
                 	next_month_start = month_start.addMonth(1);
                 	result.put("month_start",month_start);
                 	result.put("next_month_start",next_month_start);
                 	month_machines = Other_Machines[Voucher.Employee == employee_id && Time_Start >= month_start && Time_Start < next_month_start && Cancel_Voucher != true];
                 	if(month_machines.count() <= 0)
                 	{
                 		result.put("message","No Other Machines records were found for the employee in this month.");
                 		return result;
                 	}
                 	machines_per_day = Map();
                 	working_dates = List();
                 	for each  machine_rec in month_machines
                 	{
                 		if(machine_rec.Time_Start != null)
                 		{
                 			machine_date = machine_rec.Time_Start.toDate();
                 			day_key = machine_date.toString("yyyy-MM-dd");
                 			if(!working_dates.contains(day_key))
                 			{
                 				working_dates.add(day_key);
                 			}
                 			day_machine_count = 0;
                 			if(machines_per_day.containKey(day_key))
                 			{
                 				day_machine_count = ifnull(machines_per_day.get(day_key),0);
                 			}
                 			machines_per_day.put(day_key,day_machine_count + 1);
                 		}
                 	}
                 	working_days = working_dates.size();
                 	if(working_days <= 0)
                 	{
                 		result.put("message","No valid Other Machines working dates were found.");
                 		return result;
                 	}
                 	daily_labour = round(monthly_salary / working_days,2);
                 	result.put("working_days",working_days);
                 	result.put("daily_labour",daily_labour);
                 	updated_count = 0;
                 	calculated_total = 0.0;
                 	for each  machine_rec in month_machines
                 	{
                 		if(machine_rec.Time_Start != null)
                 		{
                 			day_key = machine_rec.Time_Start.toDate().toString("yyyy-MM-dd");
                 			machines_that_day = ifnull(machines_per_day.get(day_key),0);
                 			if(machines_that_day > 0)
                 			{
                 				labour_per_machine = round(daily_labour / machines_that_day,2);
                 				machine_rec.Labour_Cost=labour_per_machine;
                 				services_total = 0.0;
                 				for each  srv in machine_rec.Services
                 				{
                 					services_total = services_total + ifnull(srv.Line_Total,0.0);
                 				}
                 				services_total = round(services_total,2);
                 				machine_rec.Service_Cost=services_total;
                 				service_cost = round(ifnull(machine_rec.Service_Cost,0.0),2);
                 				fuel_cost = round(ifnull(machine_rec.Fuel_Cost,0.0),2);
                 				labour_cost = round(ifnull(machine_rec.Labour_Cost,0.0),2);
                 				line_total = round(service_cost + fuel_cost + labour_cost,2);
                 				machine_rec.Line_Total=line_total;
                 				duration_minutes = ifnull(machine_rec.Line_Duration_Minutes,0.0);
                 				hours_worked = 0.0;
                 				if(duration_minutes > 0)
                 				{
                 					hours_worked = round(duration_minutes / 60.0,2);
                 				}
                 				machine_rec.Line_Hours_Worked=hours_worked;
                 				if(hours_worked > 0)
                 				{
                 					machine_rec.Cost_Per_Odometer=round(line_total / hours_worked,2);
                 				}
                 				else
                 				{
                 					machine_rec.Cost_Per_Odometer=0.0;
                 				}
                 				line_income = round(ifnull(machine_rec.Line_Income,0.0),2);
                 				if(hours_worked > 0)
                 				{
                 					machine_rec.Income_Per_Odometer=round(line_income / hours_worked,2);
                 				}
                 				else
                 				{
                 					machine_rec.Income_Per_Odometer=0.0;
                 				}
                 				machine_rec.Line_Profit=round(line_income - line_total,2);
                 				calculated_total = calculated_total + labour_per_machine;
                 				updated_count = updated_count + 1;
                 			}
                 		}
                 	}
                 	calculated_total = round(calculated_total,2);
                 	result.put("machine_lines_updated",updated_count);
                 	result.put("calculated_labour_total",calculated_total);
                 	info "==============================================";
                 	info "OTHER MACHINES LABOUR RECALCULATION";
                 	info "Employee: " + employee_display_name;
                 	info "Employee ID: " + employee_id;
                 	info "Month Start: " + month_start;
                 	info "Monthly Salary: " + monthly_salary;
                 	info "Working Days: " + working_days;
                 	info "Daily Labour: " + daily_labour;
                 	info "Other Machines Updated: " + updated_count;
                 	info "Calculated Labour Total: " + calculated_total;
                 	info "==============================================";
                 	result.put("ok",true);
                 	result.put("message","Other Machines labour and movement totals were recalculated successfully.");
                 	return result;
                 }

map labour.recalculate_truck_movement_labour(int employee_id, string employee_display_name, date work_date)
{
                 	result = Map();
                 	result.put("ok",false);
                 	result.put("message","");
                 	result.put("employee_id",employee_id);
                 	result.put("employee",employee_display_name);
                 	result.put("monthly_salary",0.0);
                 	result.put("working_days",0);
                 	result.put("daily_labour",0.0);
                 	result.put("trip_lines_updated",0);
                 	result.put("calculated_labour_total",0.0);
                 	if(employee_id == null)
                 	{
                 		result.put("message","Employee ID is required.");
                 		return result;
                 	}
                 	employee_display_name = ifnull(employee_display_name,"").trim();
                 	if(work_date == null)
                 	{
                 		work_date = zoho.currentdate;
                 	}
                 	salary_result = employee_management.employee.get_employee_salary_details(employee_id,work_date);
                 	if(salary_result == null)
                 	{
                 		result.put("message","Employee Management returned no salary information.");
                 		return result;
                 	}
                 	if(ifnull(salary_result.get("ok"),false) != true)
                 	{
                 		result.put("message",ifnull(salary_result.get("message"),"Employee salary could not be retrieved."));
                 		return result;
                 	}
                 	monthly_salary = ifnull(salary_result.get("monthly_salary"),0.0);
                 	if(monthly_salary <= 0)
                 	{
                 		result.put("message","The employee monthly salary must be greater than zero.");
                 		return result;
                 	}
                 	result.put("monthly_salary",monthly_salary);
                 	month_number = work_date.getMonth();
                 	year_number = work_date.getYear();
                 	month_text = month_number.toString();
                 	if(month_number < 10)
                 	{
                 		month_text = "0" + month_number;
                 	}
                 	month_start_text = "01-" + month_text + "-" + year_number.toString();
                 	month_start = month_start_text.toDate("dd-MM-yyyy");
                 	next_month_start = month_start.addMonth(1);
                 	result.put("month_start",month_start);
                 	result.put("next_month_start",next_month_start);
                 	month_trips = Truck_Movement_Voucher[Voucher.Employee == employee_id && Time_Start >= month_start && Time_Start < next_month_start && Cancel_Voucher != true];
                 	if(month_trips.count() <= 0)
                 	{
                 		result.put("message","No truck movements were found for the employee in this month.");
                 		return result;
                 	}
                 	trips_per_day = Map();
                 	working_dates = List();
                 	for each  trip_rec in month_trips
                 	{
                 		if(trip_rec.Time_Start != null)
                 		{
                 			movement_date = trip_rec.Time_Start.toDate();
                 			day_key = movement_date.toString("yyyy-MM-dd");
                 			if(!working_dates.contains(day_key))
                 			{
                 				working_dates.add(day_key);
                 			}
                 			day_trip_count = 0;
                 			if(trips_per_day.containKey(day_key))
                 			{
                 				day_trip_count = ifnull(trips_per_day.get(day_key),0);
                 			}
                 			trips_per_day.put(day_key,day_trip_count + 1);
                 		}
                 	}
                 	working_days = working_dates.size();
                 	if(working_days <= 0)
                 	{
                 		result.put("message","No valid working dates were found.");
                 		return result;
                 	}
                 	daily_labour = round(monthly_salary / working_days,2);
                 	result.put("working_days",working_days);
                 	result.put("daily_labour",daily_labour);
                 	updated_count = 0;
                 	calculated_total = 0.0;
                 	for each  trip_rec in month_trips
                 	{
                 		if(trip_rec.Time_Start != null)
                 		{
                 			day_key = trip_rec.Time_Start.toDate().toString("yyyy-MM-dd");
                 			trips_that_day = ifnull(trips_per_day.get(day_key),0);
                 			if(trips_that_day > 0)
                 			{
                 				labour_per_trip = round(daily_labour / trips_that_day,2);
                 				trip_rec.Labour_Cost=labour_per_trip;
                 				services_total = 0.0;
                 				for each  srv in trip_rec.Services
                 				{
                 					services_total = services_total + ifnull(srv.Line_Total,0.0);
                 				}
                 				services_total = round(services_total,2);
                 				trip_rec.Service_Cost=services_total;
                 				material_cost = round(ifnull(trip_rec.Material_Cost,0.0),2);
                 				service_cost = round(ifnull(trip_rec.Service_Cost,0.0),2);
                 				fuel_cost = round(ifnull(trip_rec.Fuel_Cost,0.0),2);
                 				labour_cost = round(ifnull(trip_rec.Labour_Cost,0.0),2);
                 				line_total = round(material_cost + service_cost + fuel_cost + labour_cost,2);
                 				trip_rec.Line_Total=line_total;
                 				distance = ifnull(trip_rec.Line_Distance_Travelled,0.0);
                 				if(distance > 0)
                 				{
                 					trip_rec.Cost_Per_Odometer=round(line_total / distance,2);
                 				}
                 				else
                 				{
                 					trip_rec.Cost_Per_Odometer=0.0;
                 				}
                 				line_income = round(ifnull(trip_rec.Line_Income,0.0),2);
                 				if(distance > 0)
                 				{
                 					trip_rec.Income_Per_Odometer=round(line_income / distance,2);
                 				}
                 				else
                 				{
                 					trip_rec.Income_Per_Odometer=0.0;
                 				}
                 				trip_rec.Line_Profit=round(line_income - line_total,2);
                 				calculated_total = calculated_total + labour_per_trip;
                 				updated_count = updated_count + 1;
                 			}
                 		}
                 	}
                 	result.put("trip_lines_updated",updated_count);
                 	result.put("calculated_labour_total",round(calculated_total,2));
                 	result.put("ok",true);
                 	result.put("message","Truck movement labour and movement totals were recalculated successfully.");
                 	return result;
                 }

void payment.recalculate_all_bill_payments()
{
                 	for each  bill_rec in Bill[ID != 0]
                 	{
                 		total_amount = round(ifnull(bill_rec.Total_Amount,0.0),2);
                 		total_paid = 0.0;
                 		payment_rows = Payment_Made_Details[Bill == bill_rec.ID];
                 		for each  payment_row in payment_rows
                 		{
                 			total_paid = round(total_paid + ifnull(payment_row.Amount_Allocated,0.0),2);
                 		}
                 		balance_due = round(total_amount - total_paid,2);
                 		if(balance_due < 0)
                 		{
                 			balance_due = 0.0;
                 		}
                 		// Update all Bill payment totals.
                 		bill_rec.Amount_Paid=total_paid;
                 		bill_rec.Amount_Due=balance_due;
                 		bill_rec.Balance_Due=balance_due;
                 		// Update payment status.
                 		if(total_paid <= 0)
                 		{
                 			bill_rec.Payment_Status="Not Paid";
                 		}
                 		else if(total_paid < total_amount)
                 		{
                 			bill_rec.Payment_Status="Partially Paid";
                 		}
                 		else
                 		{
                 			bill_rec.Payment_Status="Paid";
                 		}
                 	}
                 	info "All Bill payment totals and statuses were recalculated successfully.";
                 }

